def _map_plan_safety_state(row: dict[str, Any]) -> PlanSafetyState:
    triage = {}
    why_log = row.get("why_log")
    if isinstance(why_log, dict):
        triage = why_log.get("injury_triage") or {}
    if not isinstance(triage, dict):
        triage = {}

    mode = str(triage.get("mode") or "")
    triage_blocked = str(row.get("status") or "").strip().lower() == "triage_blocked"
    stage2_was_skipped = bool(triage.get("should_block_stage2")) or triage_blocked
    if mode == "medical_hold":
        return PlanSafetyState(
            state="medical_hold",
            status_chip="MEDICAL HOLD",
            header="Medical hold: no training plan generated",
            subtext=(
                "Urgent neurological or medical red-flag signals were detected. "
                "Planning was intentionally blocked before normal generation."
            ),
            stage2_skipped=stage2_was_skipped,
            clinician_clearance_required=bool(triage.get("clinician_clearance_required", True)),
            matched_high_risk_categories=list(triage.get("matched_high_risk_categories") or []),
            red_flags=list(triage.get("red_flags") or []),
            sparring_risk_band=triage.get("sparring_risk_band"),
            next_steps=[
                "Seek appropriate medical review before training guidance.",
                "Update the intake after clearance.",
                "Regenerate only when medically cleared.",
            ],
        )
    if mode == "restricted_rehab_only":
        return PlanSafetyState(
            state="restricted_rehab_only",
            status_chip="RESTRICTED REHAB ONLY",
            header="Planning paused: clinician clearance required",
            subtext=(
                "Serious structural injury signals were detected. "
                "Normal fight-camp generation is paused to avoid unsafe loading recommendations."
            ),
            stage2_skipped=stage2_was_skipped,
            clinician_clearance_required=bool(triage.get("clinician_clearance_required", True)),
            matched_high_risk_categories=list(triage.get("matched_high_risk_categories") or []),
            red_flags=list(triage.get("red_flags") or []),
            sparring_risk_band=triage.get("sparring_risk_band"),
            next_steps=[
                "Review injury details and current restrictions.",
                "Update the intake after clinician clearance.",
                "Regenerate normal planning only when safe.",
            ],
        )
    if mode == "needs_review":
        return PlanSafetyState(
            state="needs_review",
            status_chip="NEEDS REVIEW",
            header="Safety review required before planning",
            subtext=(
                "Guided injury severity/trend combinations triggered a conservative safety gate. "
                "Automatic planning is paused pending coach/admin review."
            ),
            stage2_skipped=stage2_was_skipped,
            clinician_clearance_required=bool(triage.get("clinician_clearance_required", False)),
            matched_high_risk_categories=list(triage.get("matched_high_risk_categories") or []),
            red_flags=list(triage.get("red_flags") or []),
            sparring_risk_band=triage.get("sparring_risk_band"),
            next_steps=[
                "Review guided injury severity/trend details.",
                "Clarify diagnosis progression and restrictions.",
                "Approve before rerunning full planning.",
            ],
        )

    return PlanSafetyState(
        state="plan_ready",
        status_chip="PLAN READY",
        header="Plan ready",
        subtext="Normal planning completed.",
        stage2_skipped=False,
        clinician_clearance_required=False,
        matched_high_risk_categories=[],
        red_flags=[],
        sparring_risk_band=None,
        next_steps=[],
    )


_ALLOWED_PLAN_SOURCES: frozenset[str] = frozenset({"quick_build", "self_serve"})


def _lookup_plan_source(store: AppStore, plan_id: str) -> str | None:
    job = store.get_generation_job_by_plan_id(plan_id)
    if not isinstance(job, dict):
        return None
    raw = job.get("source")
    if not isinstance(raw, str):
        return None
    value = raw.strip()
    return value if value in _ALLOWED_PLAN_SOURCES else None


def _structured_card_reason_text(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        return value.strip() or None
    if isinstance(value, dict):
        for key in ("message", "reason", "detail", "error", "code"):
            text = _structured_card_reason_text(value.get(key))
            if text:
                return text
        try:
            return json.dumps(value, sort_keys=True, default=str)
        except (TypeError, ValueError):
            return str(value)
    text = str(value).strip()
    return text or None


def _structured_card_reason_list(value: Any) -> list[str]:
    values = value if isinstance(value, (list, tuple)) else [value]
    reasons: list[str] = []
    for item in values:
        text = _structured_card_reason_text(item)
        if text and text not in reasons:
            reasons.append(text)
    return reasons


def _merge_structured_card_reasons(*groups: list[str]) -> list[str]:
    merged: list[str] = []
    for group in groups:
        for reason in group:
            if reason not in merged:
                merged.append(reason)
    return merged


def _derive_structured_card_state(
    row: dict[str, Any],
    *,
    structured_plan: StructuredTrainingPlan | None,
    structured_schema_version: str | None,
    now: datetime | None = None,
) -> StructuredCardState:
    report = row.get("stage2_validator_report")
    report = report if isinstance(report, dict) else {}
    debug = report.get("structured_plan")
    debug = debug if isinstance(debug, dict) else {}
    debug_status = str(debug.get("status") or "").strip()

    error_reasons = _structured_card_reason_list(debug.get("errors"))
    warning_reasons = _structured_card_reason_list(debug.get("warnings"))
    recorded_reasons = _structured_card_reason_list(debug.get("reason"))
    reasons = _merge_structured_card_reasons(
        error_reasons,
        warning_reasons,
        recorded_reasons,
    )

    raw_schema_version = structured_schema_version or debug.get("schema_version")
    schema_version = (
        str(raw_schema_version).strip() if raw_schema_version is not None else None
    ) or None

    raw_attempt_started_at = report.get(STRUCTURED_CARD_ATTEMPT_STARTED_AT_KEY)
    attempt_at = parse_structured_card_attempt_started_at(raw_attempt_started_at)
    attempt_started_at: str | None = None
    if attempt_at is not None:
        attempt_started_at = (
            raw_attempt_started_at.strip()
            if isinstance(raw_attempt_started_at, str)
            else attempt_at.isoformat()
        )

    if structured_plan is not None and debug_status in _CLEAN_STRUCTURED_CARD_STATUSES:
        return StructuredCardState(
            state="live",
            reasons=reasons,
            schema_version=schema_version,
            attempt_started_at=attempt_started_at,
        )

    if attempt_at is not None:
        current_time = now or datetime.now(timezone.utc)
        if current_time.tzinfo is None:
            current_time = current_time.replace(tzinfo=timezone.utc)
        else:
            current_time = current_time.astimezone(timezone.utc)
        if current_time - attempt_at < STRUCTURED_CARD_BUILD_STALE_AFTER:
            return StructuredCardState(
                state="building",
                reasons=[],
                schema_version=schema_version,
                attempt_started_at=attempt_started_at,
            )
        stale_reasons = _merge_structured_card_reasons(
            [_STALE_STRUCTURED_CARD_REASON],
            reasons,
        )
        if debug_status in _CLEAN_STRUCTURED_CARD_STATUSES:
            stale_reasons = _merge_structured_card_reasons(
                stale_reasons,
                [_MISSING_SAVED_CARD_REASON],
            )
        return StructuredCardState(
            state="failed",
            reasons=stale_reasons,
            schema_version=schema_version,
            attempt_started_at=attempt_started_at,
        )

    if debug_status in _CLEAN_STRUCTURED_CARD_STATUSES:
        return StructuredCardState(
            state="failed",
            reasons=_merge_structured_card_reasons(
                [_MISSING_SAVED_CARD_REASON],
                reasons,
            ),
            schema_version=schema_version,
        )

    if debug_status in _FAILED_STRUCTURED_CARD_STATUSES:
        if not reasons:
            reasons = [
                "Enhanced card was blocked by the safety audit."
                if debug_status == "blocked_by_safety_audit"
                else "Enhanced card validation failed."
            ]
        return StructuredCardState(
            state="failed",
            reasons=reasons,
            schema_version=schema_version,
        )

    if debug_status == "not_attempted":
        return StructuredCardState(
            state="failed" if error_reasons else "not_attempted",
            reasons=reasons,
            schema_version=schema_version,
        )

    return StructuredCardState(
        state="none",
        reasons=reasons,
        schema_version=schema_version,
    )


def _map_plan_detail(
    row: dict[str, Any],
    *,
    include_admin: bool,
    plan_source: str | None = None,
    current_training_day: date | str | None = None,
    rehab_label_policy: RehabLabelPolicy | None = None,
    intake_injuries: AdminIntakeInjuries | None = None,
) -> PlanDetail:
    summary = _map_plan_summary(row, current_training_day=current_training_day)
    planning_brief = _decode_structured_text(row.get("planning_brief"))
    raw_stage2_payload = row.get("stage2_payload")
    # No fallback to stage2_payload["input_parsing_metadata"]: Stage 1 sets it and
    # the top-level parsing_metadata from the same plan_input.parsing_metadata in
    # the same result (fightcamp/main.py), so the fallback could only ever repeat
    # the value the column already holds — and when the column is falsy, so is it.
    # Rows predating the column predate stage2_payload too (both were added by
    # 20260427120000_stabilize_generation_runtime.sql, neither backfilled), so
    # there is no legacy era where the fallback supplied anything either.
    parsing_metadata = row.get("parsing_metadata") or {}
    display_plan_text = str(row.get("plan_text") or "")
    if not display_plan_text and summary.status == "archived" and not include_admin:
        display_plan_text = str(row.get("final_plan_text") or row.get("draft_plan_text") or "")
    is_legacy_review_required = str(row.get("status") or "").strip().lower() == "review_required"
    if (
        not display_plan_text
        and is_legacy_review_required
        and summary.status in {"ready", "publishable_with_flags"}
    ):
        display_plan_text = str(row.get("final_plan_text") or "")
    effective_structured_plan = resolve_effective_structured_plan(
        row,
        raw_markdown=display_plan_text,
    )
    structured_plan, structured_schema_version = _decode_structured_plan(
        effective_structured_plan,
        raw_markdown=display_plan_text,
    )
    structured_payload = (
        structured_plan.model_dump(mode="json") if structured_plan is not None else {}
    )
    locked_payload = merge_planner_owned_structured_content(
        structured_payload,
        planning_brief,
    ).plan
    if structured_plan is not None and locked_payload != structured_payload:
        locked_result = safe_parse_structured_plan(
            locked_payload,
            raw_markdown=display_plan_text or None,
        )
        if locked_result.ok and locked_result.plan is not None:
            structured_plan = locked_result.plan
            structured_payload = locked_payload
    reconciled_payload = reconcile_exercise_keys(
        reconcile_rehab_drill_ids(
            reconcile_late_fight_week_context(
                structured_payload,
                planning_brief,
            ),
            planning_brief,
        ),
        planning_brief,
    )
    if structured_plan is not None and reconciled_payload != structured_payload:
        reconciled_result = safe_parse_structured_plan(
            reconciled_payload,
            raw_markdown=display_plan_text or None,
        )
        if reconciled_result.ok and reconciled_result.plan is not None:
            structured_plan = reconciled_result.plan
            structured_payload = reconciled_payload
    # Restore any no-session calendar days a dated camp dropped, so week
    # boundaries / counts / phases render from the authoritative countdown spine
    # rather than only the days that carried a session. A no-op (returns the same
    # object) for open plans, undated plans, and calendars already continuous.
    spine_payload = reconcile_calendar_spine(structured_payload, planning_brief)
    if structured_plan is not None and spine_payload is not structured_payload:
        spine_result = safe_parse_structured_plan(
            spine_payload,
            raw_markdown=display_plan_text or None,
        )
        if spine_result.ok and spine_result.plan is not None:
            structured_plan = spine_result.plan
            structured_payload = spine_payload
    projected_payload, raw_schedule_context = project_open_structured_plan(
        row,
        structured_payload,
        current_training_day=current_training_day or datetime.now(timezone.utc).date(),
    )
    if (
        raw_schedule_context.get("schedule_mode") == "open_recurring"
        and raw_schedule_context.get("projection_status") == "unavailable"
    ):
        # An open plan that failed to project renders undated ("WEEK N · weekday")
        # in the Plan tab. The reason names the fail-closed guard that tripped so
        # the cause is one log line instead of a payload-shape trace.
        logger.warning(
            "open plan projection unavailable: plan_id=%s reason=%s",
            row.get("id"),
            raw_schedule_context.get("projection_reason"),
        )
    if structured_plan is not None and projected_payload != structured_payload:
        projected_result = safe_parse_structured_plan(
            projected_payload,
            raw_markdown=display_plan_text or None,
        )
        if projected_result.ok and projected_result.plan is not None:
            structured_plan = projected_result.plan
    report_dict = row.get("stage2_validator_report")
    report_dict = report_dict if isinstance(report_dict, dict) else {}
    structured_debug = report_dict.get("structured_plan")
    structured_debug = structured_debug if isinstance(structured_debug, dict) else {}
    return PlanDetail(
        **summary.model_dump(mode="json"),
        outputs=PlanOutputs(
            plan_text=display_plan_text,
            pdf_url=row.get("pdf_url"),
            structured_plan=structured_plan,
            schema_version=structured_schema_version,
        ),
        safety_state=_map_plan_safety_state(row),
        structured_card_state=_derive_structured_card_state(
            row,
            structured_plan=structured_plan,
            structured_schema_version=structured_schema_version,
        ),
        advisories=build_plan_advisories(planning_brief=planning_brief),
        plan_source=plan_source,
        schedule_context=PlanScheduleContext(**raw_schedule_context),
        profile_refresh_failed=bool(
            (row.get("why_log") if isinstance(row.get("why_log"), dict) else {}).get(
                PROFILE_REFRESH_FAILED_WHY_LOG_KEY
            )
        ),
        rehab_label_policy=rehab_label_policy or RehabLabelPolicy(),
        admin_outputs=(
            AdminPlanOutputs(
                coach_notes=str(row.get("coach_notes") or ""),
                why_log=row.get("why_log") or {},
                intake_injuries=intake_injuries,
                planning_brief=planning_brief,
                stage2_payload=raw_stage2_payload,
                parsing_metadata=parsing_metadata if isinstance(parsing_metadata, dict) else {},
                stage2_handoff_text=str(row.get("stage2_handoff_text") or ""),
                draft_plan_text=_admin_draft_text(row),
                final_plan_text=_admin_final_text(row),
                stage2_retry_text=str(row.get("stage2_retry_text") or ""),
                stage2_validator_report=row.get("stage2_validator_report") or {},
                stage2_status=str(row.get("stage2_status") or "legacy"),
                stage2_attempt_count=int(row.get("stage2_attempt_count") or 0),
                structured_plan_status=str(structured_debug.get("status") or "not_attempted"),
                structured_plan_errors=[str(err) for err in (structured_debug.get("errors") or [])],
                structured_schema_version=(
                    structured_schema_version or structured_debug.get("schema_version")
                ),
            )
            if include_admin
            else None
        ),
    )


def _decode_structured_plan(
    value: Any,
    *,
    raw_markdown: str = "",
) -> tuple[StructuredTrainingPlan | None, str | None]:
    """Best-effort decode of a stored structured plan column.

    Legacy plans have no structured payload, so this returns ``(None, None)``
    for missing/blank values. Malformed structured data never breaks the
    response: it is dropped and the raw markdown fallback still flows through
    ``plan_text``.
    """

    decoded = _decode_structured_text(value)
    # `_decode_structured_text` wraps non-JSON strings as {"raw": ...}; that is
    # not a structured plan, so treat it (and empty values) as "no structured".
    if not decoded or (len(decoded) == 1 and "raw" in decoded):
        return None, None
    result = safe_parse_structured_plan(decoded, raw_markdown=raw_markdown or None)
    if not result.ok or result.plan is None:
        # The column carried a structured payload that no longer parses against
        # the schema. Surface it instead of silently dropping to the markdown
        # fallback, so a stored-card regression is visible rather than invisible.
        logger.warning(
            "structured_plan column failed to parse; falling back to markdown (errors=%s)",
            "; ".join(result.errors) if getattr(result, "errors", None) else "unknown",
        )
        return None, None
    return result.plan, result.plan.schema_version


def _map_weekly_schedule(row: dict[str, Any], *, week_index: int) -> WeeklySchedule:
    planning_brief = _decode_structured_text(row.get("planning_brief"))
    schedule = extract_weekly_schedule(
        planning_brief,
        week_index=week_index,
        fight_date=row.get("fight_date"),
    )
    if schedule is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="weekly schedule not found")
    return WeeklySchedule(plan_id=str(row["id"]), **schedule)


def _map_admin_plan_summary(row: dict[str, Any]) -> AdminPlanSummary:
    profile = row.get("profiles") or {}
    summary = _map_plan_summary(row)
    return AdminPlanSummary(
        **summary.model_dump(mode="json"),
        athlete_email=str(profile.get("email") or ""),
        profile_unavailable=bool(row.get("profile_enrichment_failed")),
    )


def _map_admin_athlete(row: dict[str, Any], latest_intake: dict[str, Any] | None = None) -> AdminAthleteRecord:
    onboarding_draft = row.get("onboarding_draft")
    return AdminAthleteRecord(
        athlete_id=str(row["id"]),
        email=str(row.get("email") or ""),
        role=str(row.get("role") or "athlete"),
        access_status=str(row.get("access_status") or "pending"),
        full_name=str(row.get("full_name") or ""),
        technical_style=list(row.get("technical_style") or []),
        tactical_style=list(row.get("tactical_style") or []),
        stance=str(row.get("stance") or ""),
        professional_status=str(row.get("professional_status") or ""),
        record=str(row.get("record") or row.get("record_summary") or ""),
        athlete_timezone=str(row.get("athlete_timezone") or ""),
        athlete_locale=str(row.get("athlete_locale") or ""),
        appearance_mode=str(row.get("appearance_mode") or "dark"),
        onboarding_draft=onboarding_draft if isinstance(onboarding_draft, dict) else None,
        latest_intake=latest_intake.get("intake") if isinstance(latest_intake, dict) else None,
        nutrition_profile=row.get("nutrition_profile") or {},
        created_at=str(row.get("created_at") or ""),
        updated_at=str(row.get("updated_at") or ""),
        plan_count=int(row.get("plan_count") or 0),
        latest_plan_created_at=row.get("latest_plan_created_at"),
    )

api/routes/training_library.py:
"""Authenticated, read-only discovery. No planner or scheduling operations."""
import logging

from fastapi import APIRouter, Depends, HTTPException, Query

from api.contracts.training_library import LibraryCategory, LibraryFeaturedResponse, LibraryPreview, LibrarySearchResponse
from api.services import training_library as library
from api.services.exercise_media import load_media_index
from fightcamp.exercise_identity import normalize_exercise_key

logger = logging.getLogger(__name__)


def _index():
    try:
        return library.cache.get()
    except (OSError, ValueError, KeyError, TypeError, AttributeError):
        logger.exception("Training catalogue unavailable or invalid")
        raise HTTPException(503, "Training library is temporarily unavailable.") from None


def _attach_media(payload, record, media):
    entry = record["entry"]
    if payload["category"] == "training":
        key = entry["exercise_key"]
    elif payload["category"] == "rehab":
        key = normalize_exercise_key(entry["source_id"])
    else:
        return
    payload["media"] = media.get(key)


def build_training_library_router(*, require_profile, get_store):
    router = APIRouter(prefix="/api/training/library", tags=["training library"])

    @router.get("", response_model=LibrarySearchResponse)
    def find_drills(
        q: str = Query("", max_length=100), category: LibraryCategory = "training",
        type_filter: str | None = Query(None, alias="type", max_length=100),
        goal: str | None = Query(None, max_length=100), sport: str | None = Query(None, max_length=100),
        equipment: str | None = Query(None, max_length=100), body_focus: str | None = Query(None, max_length=100),
        offset: int = Query(0, ge=0, le=10000), limit: int = Query(24, ge=1, le=50),
        revision: str | None = Query(None, max_length=64),
        profile=Depends(require_profile), store=Depends(get_store),
    ):
        index = _index()
        if revision and revision != index.revision:
            raise HTTPException(409, "Library changed. Refresh your search.")
        result = library.search(index, q=q, category=category, offset=offset, limit=limit,
                                filters=dict(type=type_filter, goal=goal, sport=sport,
                                             equipment=equipment, body_focus=body_focus))
        media = load_media_index(store)
        for payload in result["entries"]:
            _attach_media(payload, index.by_id[payload["catalogue_id"]], media)
        return result

    @router.get("/featured", response_model=LibraryFeaturedResponse)
    def featured_drill(profile=Depends(require_profile), store=Depends(get_store)):
        # Editorial priority, never a popularity score or a prescription. Only
        # current, curated demos on exact Training identities may be featured.
        index = _index()
        media = load_media_index(store)
        preferred = ("medicine-ball-hook-throw", "check-hook-pivot-burst", "standing-cable-punch-simulation")
        candidates = [record for record in index.records if record["summary"]["category"] == "training"
                      and record["entry"]["exercise_key"] in media]
        if not candidates:
            return {"entry": None}
        candidates.sort(key=lambda record: (
            preferred.index(record["entry"]["exercise_key"]) if record["entry"]["exercise_key"] in preferred else len(preferred),
            record["entry"]["catalogue_id"],
        ))
        record = candidates[0]
        payload = dict(record["summary"])
        _attach_media(payload, record, media)
        return {"entry": payload}

    @router.get("/entry", response_model=LibraryPreview)
    def drill_preview(
        catalogue_id: str = Query(..., min_length=1, max_length=250),
        profile=Depends(require_profile), store=Depends(get_store),
    ):
        record = _index().by_id.get(catalogue_id)
        if record is None:
            raise HTTPException(404, "Drill is no longer available.")
        result = library.preview(record)
        _attach_media(result, record, load_media_index(store))
        return result

    return router

api/services/active_plan.py:
"""Authoritative active-plan resolution.

``profiles.active_plan_id`` is the only active-plan pointer. The referenced plan
is returned only when it belongs to the athlete, has an athlete-displayable
status and has not passed its fight date in the athlete-local training day. A
missing, invalid or unreadable pointer resolves to no active plan; this service
never promotes another saved plan as a fallback. Overlapping saved
or draft plans are allowed, but activating an overlapping second plan requires an
explicit pause or replacement choice. ``pause`` preserves the previous plan row
unchanged and switches the single active pointer to the selected plan, allowing
the previous plan to be reactivated later. ``replace`` switches the pointer and
archives the previous plan. Eligible statuses are ``ready`` and
``publishable_with_flags``. Generated, review, hold, failed, archived, missing,
and deleted plans are never active. Overview and Today both call this resolver;
UI code must not guess with “latest visible plan” logic.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date, timedelta
import json
import logging
from typing import Any, Literal, Mapping, Protocol

from fastapi import HTTPException, status
from api.datetimes import parse_calendar_date as _parse_date

logger = logging.getLogger(__name__)

ELIGIBLE_ACTIVE_PLAN_STATUSES = {"ready", "publishable_with_flags"}
ACTIVE_PLAN_OVERLAP_ACTIONS = {"pause", "replace"}
ACTIVE_PLAN_OVERLAP_CONFLICT_MESSAGE = (
    "This overlaps with your current active plan. Do you want to replace the current plan, pause it, or choose a new start date?"
)
ACTIVE_PLAN_OVERLAP_CONFLICT_CODE = "active_plan_overlap"
ACTIVE_PLAN_REPLACE_FAILED_MESSAGE = "Unable to replace the current active plan. The original active plan was restored."
PLAN_HAS_ENDED_CODE = "plan_has_ended"
PLAN_HAS_ENDED_MESSAGE = "This fight camp has ended and cannot be activated."
PlanActivationState = Literal["eligible", "fight_date_passed", "status_ineligible"]
NEVER_ACTIVE_PLAN_STATUSES = {
    "generated",
    "review_required",
    "held_for_review",
    "triage_blocked",
    "medical_hold",
    "restricted_rehab_only",
    "needs_review",
    "failed",
    "archived",
}


class ActivePlanStore(Protocol):
    def list_user_plans(self, athlete_id: str) -> list[dict[str, Any]]: ...
    def get_plan_for_athlete(self, plan_id: str, athlete_id: str) -> dict[str, Any] | None: ...
    def get_active_plan_id(self, athlete_id: str) -> str | None: ...
    def set_active_plan_id(self, athlete_id: str, plan_id: str) -> None: ...
    def archive_plan_for_athlete(self, plan_id: str, athlete_id: str) -> dict[str, Any]: ...


@dataclass(frozen=True)
class ActivePlanResolution:
    plan: dict[str, Any] | None
    source: str

    @property
    def plan_id(self) -> str | None:
        return str(self.plan.get("id")) if self.plan and self.plan.get("id") else None


@dataclass(frozen=True)
class PlanDateRange:
    start: date
    end: date


def normalize_plan_status(row: dict[str, Any] | None) -> str:
    return str((row or {}).get("status") or "").strip().lower()


def is_active_plan_eligible(
    row: dict[str, Any] | None,
    *,
    current_training_day: date | str | None = None,
) -> bool:
    return get_plan_activation_state(
        row,
        current_training_day=current_training_day,
    ) == "eligible"


def _explicit_active_plan_id(store: ActivePlanStore, athlete_id: str) -> str | None:
    value = store.get_active_plan_id(athlete_id)
    return str(value).strip() or None if value is not None else None


def _decode_mapping(value: Any) -> Mapping[str, Any]:
    if isinstance(value, Mapping):
        return value
    if isinstance(value, str):
        stripped = value.strip()
        if not stripped:
            return {}
        try:
            decoded = json.loads(stripped)
        except json.JSONDecodeError:
            return {}
        return decoded if isinstance(decoded, Mapping) else {}
    return {}


def get_plan_activation_state(
    row: dict[str, Any] | None,
    *,
    current_training_day: date | str | None = None,
) -> PlanActivationState:
    """Return the server-authoritative activation state for one saved plan.

    A scheduled fight camp remains eligible throughout its athlete-local fight
    day. Blank fight dates are ongoing plans. Non-empty malformed legacy dates
    fail closed so they can remain viewable without becoming operational.
    """

    if normalize_plan_status(row) not in ELIGIBLE_ACTIVE_PLAN_STATUSES:
        return "status_ineligible"

    raw_fight_date = (row or {}).get("fight_date")
    fight_date_text = str(raw_fight_date or "").strip()
    if not fight_date_text:
        return "eligible"

    fight_date = _parse_date(fight_date_text)
    if fight_date is None:
        return "status_ineligible"

    training_day = _parse_date(current_training_day) if current_training_day is not None else date.today()
    if training_day is None:
        training_day = date.today()
    if fight_date < training_day:
        return "fight_date_passed"
    return "eligible"


def _int_or_none(value: Any) -> int | None:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed > 0 else None


def _collect_structured_dates(row: dict[str, Any]) -> list[date]:
    structured_plan = _decode_mapping(row.get("structured_plan"))
    weeks = structured_plan.get("weeks")
    if not isinstance(weeks, list):
        return []
    dates: list[date] = []
    for week in weeks:
        if not isinstance(week, Mapping):
            continue
        for key in ("start_date", "end_date"):
            parsed = _parse_date(week.get(key))
            if parsed:
                dates.append(parsed)
        days = week.get("days")
        if isinstance(days, list):
            for day in days:
                if isinstance(day, Mapping):
                    parsed = _parse_date(day.get("date"))
                    if parsed:
                        dates.append(parsed)
    return dates


def _collect_planning_brief_dates(row: dict[str, Any]) -> list[date]:
    planning_brief = _decode_mapping(row.get("planning_brief"))
    role_map = planning_brief.get("weekly_role_map")
    weeks = role_map.get("weeks") if isinstance(role_map, Mapping) else None
    if not isinstance(weeks, list):
        return []
    dates: list[date] = []
    for week in weeks:
        if not isinstance(week, Mapping):
            continue
        calendar_days = week.get("calendar_days")
        if isinstance(calendar_days, list):
            for day in calendar_days:
                if isinstance(day, Mapping):
                    parsed = _parse_date(day.get("calendar_date"))
                    if parsed:
                        dates.append(parsed)
    return dates


def _camp_length_weeks(row: dict[str, Any]) -> int | None:
    planning_brief = _decode_mapping(row.get("planning_brief"))
    for container in (
        planning_brief.get("fight_demands"),
        planning_brief.get("athlete_snapshot"),
        planning_brief.get("athlete_model"),
    ):
        if isinstance(container, Mapping):
            parsed = _int_or_none(container.get("camp_length_weeks"))
            if parsed:
                return parsed
    return None


def plan_date_range(row: dict[str, Any] | None) -> PlanDateRange | None:
    if not row:
        return None

    dates = _collect_structured_dates(row) or _collect_planning_brief_dates(row)
    if dates:
        return PlanDateRange(start=min(dates), end=max(dates))

    fight_date = _parse_date(row.get("fight_date"))
    camp_length_weeks = _camp_length_weeks(row)
    if fight_date and camp_length_weeks:
        return PlanDateRange(
            start=fight_date - timedelta(days=(camp_length_weeks * 7) - 1),
            end=fight_date,
        )

    return None


def _ranges_overlap(left: PlanDateRange, right: PlanDateRange) -> bool:
    return left.start <= right.end and right.start <= left.end


def _active_plan_overlap(
    store: ActivePlanStore,
    athlete_id: str,
    candidate: dict[str, Any],
    *,
    current_training_day: date | str | None,
) -> dict[str, Any] | None:
    current = resolve_active_plan(
        store,
        athlete_id,
        current_training_day=current_training_day,
    ).plan
    if not current or str(current.get("id") or "") == str(candidate.get("id") or ""):
        return None
    if not is_active_plan_eligible(current, current_training_day=current_training_day):
        return None

    # The resolver may have selected from a summary projection. Re-read the row
    # before comparing dates so planning_brief / structured_plan can be used.
    current_id = str(current.get("id") or "")
    if current_id:
        full_current = store.get_plan_for_athlete(current_id, athlete_id)
        if full_current:
            current = full_current

    current_range = plan_date_range(current)
    candidate_range = plan_date_range(candidate)
    if not current_range or not candidate_range:
        return None
    return current if _ranges_overlap(current_range, candidate_range) else None


def resolve_active_plan(
    store: ActivePlanStore,
    athlete_id: str,
    *,
    current_training_day: date | str | None = None,
) -> ActivePlanResolution:
    try:
        explicit_id = _explicit_active_plan_id(store, athlete_id)
    except Exception:  # noqa: BLE001 - authority reads must fail closed
        logger.exception("[active-plan] pointer_read_failed athlete_id=%s", athlete_id)
        return ActivePlanResolution(plan=None, source="read_failure")
    if not explicit_id:
        return ActivePlanResolution(plan=None, source="none")

    try:
        explicit = store.get_plan_for_athlete(explicit_id, athlete_id)
    except Exception:  # noqa: BLE001 - authority reads must fail closed
        logger.exception(
            "[active-plan] referenced_plan_read_failed athlete_id=%s plan_id=%s",
            athlete_id,
            explicit_id,
        )
        return ActivePlanResolution(plan=None, source="read_failure")
    if explicit is None:
        logger.warning(
            "[active-plan] referenced_plan_missing_or_not_owned athlete_id=%s plan_id=%s",
            athlete_id,
            explicit_id,
        )
        return ActivePlanResolution(plan=None, source="invalid_reference")
    if not is_active_plan_eligible(explicit, current_training_day=current_training_day):
        logger.warning(
            "[active-plan] referenced_plan_unusable athlete_id=%s plan_id=%s status=%s",
            athlete_id,
            explicit_id,
            normalize_plan_status(explicit),
        )
        return ActivePlanResolution(plan=None, source="unusable")
    return ActivePlanResolution(plan=explicit, source="explicit")


def set_active_plan(
    store: ActivePlanStore,
    athlete_id: str,
    plan_id: str,
    *,
    overlap_action: str | None = None,
    current_training_day: date | str | None = None,
) -> dict[str, Any]:
    plan = store.get_plan_for_athlete(plan_id, athlete_id)
    if plan is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="plan not found")
    activation_state = get_plan_activation_state(
        plan,
        current_training_day=current_training_day,
    )
    if activation_state == "fight_date_passed":
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={
                "code": PLAN_HAS_ENDED_CODE,
                "message": PLAN_HAS_ENDED_MESSAGE,
                "activation_state": activation_state,
            },
        )
    if activation_state != "eligible":
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="plan is not eligible to become active")
    normalized_action = str(overlap_action or "").strip().lower() or None
    if normalized_action is not None and normalized_action not in ACTIVE_PLAN_OVERLAP_ACTIONS:
        raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_ENTITY, detail="invalid overlap action")
    overlapping_active = _active_plan_overlap(
        store,
        athlete_id,
        plan,
        current_training_day=current_training_day,
    )
    if overlapping_active and normalized_action is None:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT,
            detail={
                "code": ACTIVE_PLAN_OVERLAP_CONFLICT_CODE,
                "message": ACTIVE_PLAN_OVERLAP_CONFLICT_MESSAGE,
            },
        )
    if overlapping_active and normalized_action == "pause":
        # The active pointer is the pause state. Preserve the previous plan row
        # unchanged so it remains available for deliberate reactivation later.
        store.set_active_plan_id(athlete_id, plan_id)
        return plan
    if overlapping_active and normalized_action == "replace":
        current_plan_id = str(overlapping_active.get("id") or "")
        store.set_active_plan_id(athlete_id, plan_id)
        try:
            store.archive_plan_for_athlete(current_plan_id, athlete_id)
        except Exception as exc:
            store.set_active_plan_id(athlete_id, current_plan_id)
            if isinstance(exc, HTTPException):
                raise HTTPException(
                    status_code=exc.status_code,
                    detail=ACTIVE_PLAN_REPLACE_FAILED_MESSAGE,
                ) from exc
            raise HTTPException(
                status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                detail=ACTIVE_PLAN_REPLACE_FAILED_MESSAGE,
            ) from exc
        return plan
    store.set_active_plan_id(athlete_id, plan_id)
    return plan

api/services/effective_structured_plan.p:
"""Resolve the one effective structured calendar for a persisted plan row."""

from __future__ import annotations

import json
import logging
import re
from collections.abc import Mapping
from collections.abc import Sequence
from datetime import date
from typing import Any

from api.structured_block_identity import ensure_structured_block_ids
from api.structured_plan_deterministic_fallback import build_deterministic_structured_plan
from api.structured_plan_models import safe_parse_structured_plan

logger = logging.getLogger(__name__)


def _mapping(value: Any) -> Mapping[str, Any] | None:
    if isinstance(value, Mapping):
        return value
    if isinstance(value, str) and value.strip():
        try:
            decoded = json.loads(value)
        except json.JSONDecodeError:
            return None
        return decoded if isinstance(decoded, Mapping) else None
    return None


def _has_usable_dated_calendar(plan: Mapping[str, Any]) -> bool:
    weeks = plan.get("weeks")
    if not isinstance(weeks, Sequence) or isinstance(weeks, (str, bytes, bytearray)):
        return False
    for week in weeks:
        if not isinstance(week, Mapping):
            continue
        days = week.get("days")
        if not isinstance(days, Sequence) or isinstance(days, (str, bytes, bytearray)):
            continue
        for day in days:
            if not isinstance(day, Mapping):
                continue
            try:
                date.fromisoformat(str(day.get("date") or "")[:10])
            except ValueError:
                continue
            return True
    return False


def _has_usable_open_weekly_calendar(
    plan_row: Mapping[str, Any], plan: Mapping[str, Any]
) -> bool:
    """Recognise the older renewable cards whose rows are weekday templates."""

    if str(plan_row.get("fight_date") or "").strip():
        return False
    weeks = plan.get("weeks")
    if not isinstance(weeks, Sequence) or not weeks:
        return False
    valid_weekdays = {"mon", "tue", "wed", "thu", "fri", "sat", "sun"}
    for week in weeks:
        if not isinstance(week, Mapping):
            return False
        days = week.get("days")
        if not isinstance(days, Sequence) or len(days) < 2:
            return False
        if any(
            not isinstance(day, Mapping)
            or str(day.get("weekday") or "").strip().lower()[:3] not in valid_weekdays
            for day in days
        ):
            return False
    return True


_SLUG_RE = re.compile(r"[^a-z0-9]+")


def _slug(value: Any) -> str:
    return _SLUG_RE.sub("-", str(value or "").strip().lower()).strip("-")[:32].strip("-")


def _session_rows(day: Any) -> list[Any]:
    sessions = day.get("sessions") if isinstance(day, Mapping) else None
    return sessions if isinstance(sessions, list) else []


def _needs_session_ids(plan: Mapping[str, Any]) -> bool:
    weeks = plan.get("weeks")
    if not isinstance(weeks, list):
        return False
    return any(
        isinstance(session, Mapping) and not str(session.get("session_id") or "").strip()
        for week in weeks
        if isinstance(week, Mapping)
        for day in (week.get("days") if isinstance(week.get("days"), list) else [])
        for session in _session_rows(day)
    )


def ensure_structured_session_ids(
    plan: Any, *, plan_id: Any = None
) -> Any:
    """Give every structured session a stable id, deriving the missing ones.

    Completion, the session timer, streaks and week progress all key on
    ``session_id``. The converter is told identifiers are optional and usually
    emits null, which left most model-written sessions impossible to start or
    log ("completion is unavailable") and invisible to week progress. The
    derived id is a pure function of the stored card, so every reader of the
    same plan agrees on it without a write:
    ``ses-<plan>-<date or week/day slot>-<title>``, with a numeric suffix for a
    repeated title on the same day. The plan prefix keeps a regenerated plan's
    sessions from colliding with the old plan's completion rows on the same day.
    Existing ids are never changed. The input is not mutated.
    """
    if not isinstance(plan, Mapping):
        return plan
    if not _needs_session_ids(plan):
        return dict(plan)
    # Copy only the week -> day -> session path being written; blocks and every
    # other nested value stay shared with the (possibly cached) stored card.
    result = dict(plan)
    result["weeks"] = weeks = [
        dict(week) if isinstance(week, Mapping) else week for week in plan.get("weeks") or []
    ]
    plan_part = _slug(plan_id)[:8]
    for week_index, week in enumerate(weeks):
        if not isinstance(week, dict) or not isinstance(week.get("days"), list):
            continue
        week["days"] = days = [dict(day) if isinstance(day, Mapping) else day for day in week["days"]]
        for day_index, day in enumerate(days):
            if not isinstance(day, dict):
                continue
            sessions = [
                dict(session) if isinstance(session, Mapping) else session
                for session in _session_rows(day)
            ]
            if isinstance(day.get("sessions"), list):
                day["sessions"] = sessions
            taken = {
                str(session.get("session_id") or "").strip()
                for session in sessions
                if isinstance(session, Mapping)
            }
            date_part = str(day.get("date") or "").strip()[:10]
            try:
                date.fromisoformat(date_part)
            except ValueError:
                date_part = f"w{week_index + 1}d{day_index + 1}"
            for session_index, session in enumerate(sessions):
                if not isinstance(session, dict) or str(session.get("session_id") or "").strip():
                    continue
                title = _slug(session.get("title")) or _slug(session.get("session_type")) or str(
                    session_index + 1
                )
                base = "-".join(part for part in ("ses", plan_part, date_part, title) if part)
                candidate = base
                suffix = 2
                while candidate in taken:
                    candidate = f"{base}-{suffix}"
                    suffix += 1
                taken.add(candidate)
                session["session_id"] = candidate
    return result


def resolve_effective_structured_plan(
    plan_row: Mapping[str, Any], *, raw_markdown: str | None = None
) -> dict[str, Any] | None:
    """Return the valid stored card, or rebuild it from deterministic planner truth.

    Missing and malformed inputs fail closed. In particular, this resolver does
    not derive a calendar from broad recurring metadata. Every session in the
    returned card carries a ``session_id`` (see ensure_structured_session_ids),
    and every non-rehab block a ``block_id`` unique within its day (see
    ensure_structured_block_ids), which is what exercise logs key on.
    """
    resolved = _resolve_effective_structured_plan(plan_row, raw_markdown=raw_markdown)
    if resolved is None:
        return None
    resolved = ensure_structured_session_ids(resolved, plan_id=plan_row.get("id"))
    return ensure_structured_block_ids(resolved)


def _resolve_effective_structured_plan(
    plan_row: Mapping[str, Any], *, raw_markdown: str | None = None
) -> dict[str, Any] | None:

    legacy_open_calendar: dict[str, Any] | None = None
    stored = _mapping(plan_row.get("structured_plan"))
    if stored:
        parsed = safe_parse_structured_plan(stored, raw_markdown=raw_markdown or None)
        if parsed.ok and parsed.plan is not None:
            return dict(stored)
        # Some older cards predate the current strict display schema but still
        # carry the dated ``weeks`` calendar consumed by session services. Keep
        # their established behaviour; absence of that calendar is what permits
        # deterministic reconstruction.
        if _has_usable_dated_calendar(stored):
            return dict(stored)
        if _has_usable_open_weekly_calendar(plan_row, stored):
            # Try planner reconstruction first. This is retained only for old
            # renewable plans whose canonical cards are weekday templates.
            legacy_open_calendar = dict(stored)
        logger.warning(
            "stored structured_plan failed validation; trying deterministic fallback plan_id=%s",
            plan_row.get("id"),
        )

    planning_brief = _mapping(plan_row.get("planning_brief"))
    # Every surface (plan view, Today, progress) reads the same athlete-visible
    # plan text, so the rebuilt card carries the doses the athlete was given
    # wherever it renders. A held plan's unreleased text is never read here.
    plan_text = raw_markdown or str(plan_row.get("plan_text") or "")
    fallback = build_deterministic_structured_plan(planning_brief, plan_text=plan_text or None)
    if fallback is None:
        return legacy_open_calendar
    parsed = safe_parse_structured_plan(fallback, raw_markdown=raw_markdown or None)
    if not parsed.ok or parsed.plan is None:
        logger.warning(
            "deterministic structured fallback failed validation plan_id=%s",
            plan_row.get("id"),
        )
        return None
    logger.info("deterministic effective structured plan assembled plan_id=%s", plan_row.get("id"))
    return fallback


__all__ = ["ensure_structured_session_ids", "resolve_effective_structured_plan"]

api/services/exercise_media.py:
"""Demo videos for plan exercises.

Videos live in ``public.exercise_media`` (one row per exercise, keyed by a
normalized slug) and are attached to a plan when it is served, never stored in
``structured_plan``. That keeps two guarantees:

* the Stage-2 model is never the source of a video ID (a hallucinated ID is a
  broken or wrong player), and
* a video can be added, swapped or retired without regenerating any plan.

Resolution is best-effort: a missing table, an outage or an unknown exercise
yields no media, and the block renders cues-only.
"""

from __future__ import annotations

import logging
import os
import re
import threading
import time
from dataclasses import dataclass
from typing import Any, Callable, Iterable, Mapping
from urllib.parse import parse_qs, urlparse

import httpx

from api.models import ExerciseMedia
from fightcamp.exercise_identity import normalize_exercise_key

logger = logging.getLogger(__name__)

INDEX_TTL_SECONDS = 300.0
# After a failed load, retry sooner than the full TTL but not on every request.
INDEX_FAILURE_TTL_SECONDS = 60.0
YOUTUBE_VIDEOS_URL = "https://www.googleapis.com/youtube/v3/videos"
YOUTUBE_API_KEY_ENV = "YOUTUBE_DATA_API_KEY"
YOUTUBE_API_TIMEOUT_SECONDS = 8.0
# videos.list accepts up to 50 IDs per call (1 quota unit per call).
_VIDEOS_PER_REQUEST = 50

# With part=player, videos.list reports the embed size only when the request
# bounds it. The value is arbitrary: only the reported width:height ratio is
# read (see orientation_from_dimensions).
_PLAYER_MAX_HEIGHT = 720
# Matches the exercise_media.orientation check constraint. NULL (not detected
# yet) is served as None and rendered as landscape.
VIDEO_ORIENTATIONS = frozenset({"portrait", "landscape"})

_VIDEO_ID_RE = re.compile(r"^[A-Za-z0-9_-]{11}$")
# A dose the converter appended to the exercise name after a spaced dash:
# "Assault Bike - 25 min", "Turkish Get-Up – 3 reps per side". The tail must
# start with a number, so a hyphenated name ("Get-Up") or a worded qualifier
# ("Box Jump - Max Height") is never cut.
_DOSE_SUFFIX_RE = re.compile(r"\s+[-–—]\s+\d[^-–—]*$")


def strip_dose_suffix(name: str | None) -> str:
    """Drop a trailing " - <dose>" from an exercise name; unchanged otherwise.

    "Assault Bike - 25 min" -> "Assault Bike"
    "Turkish Get-Up - 3 reps per side" -> "Turkish Get-Up"
    """
    text = str(name or "")
    stripped = _DOSE_SUFFIX_RE.sub("", text).rstrip()
    # Keep the name whole when no exercise words would be left ("5 - 10 min").
    return stripped if re.search(r"[A-Za-z]", stripped) else text


def parse_youtube_video_id(value: str | None) -> str | None:
    """Accept a bare ID or any common YouTube URL shape; return the 11-char ID."""
    if not value:
        return None
    raw = value.strip()
    if _VIDEO_ID_RE.match(raw):
        return raw
    parsed = urlparse(raw if "://" in raw else f"https://{raw}")
    host = (parsed.hostname or "").lower().removeprefix("www.").removeprefix("m.")
    candidate: str | None = None
    if host == "youtu.be":
        candidate = parsed.path.strip("/").split("/")[0]
    elif host in {"youtube.com", "youtube-nocookie.com", "music.youtube.com"}:
        if parsed.path == "/watch":
            candidate = (parse_qs(parsed.query).get("v") or [None])[0]
        else:
            parts = [part for part in parsed.path.split("/") if part]
            if len(parts) >= 2 and parts[0] in {"embed", "shorts", "live", "v"}:
                candidate = parts[1]
    return candidate if candidate and _VIDEO_ID_RE.match(candidate) else None


@dataclass(frozen=True)
class _MediaIndex:
    by_key: Mapping[str, ExerciseMedia]
    loaded_at: float
    ttl: float

    def fresh(self, now: float) -> bool:
        return now - self.loaded_at < self.ttl


_index_lock = threading.Lock()
_index: _MediaIndex | None = None


def _media_from_row(row: Mapping[str, Any]) -> ExerciseMedia | None:
    video_id = str(row.get("video_id") or "")
    if not _VIDEO_ID_RE.match(video_id):
        return None
    # Keep YouTube's Made for Kids classification as metadata. Curator-approved
    # videos may serve whether it is true or false, but an unreported status is
    # still excluded as a safety/backstop against stale legacy rows.
    if not isinstance(row.get("made_for_kids"), bool):
        return None
    try:
        start_s = max(0, int(row.get("start_s") or 0))
        end_raw = row.get("end_s")
        end_s = int(end_raw) if end_raw is not None else None
    except (TypeError, ValueError):
        return None
    if end_s is not None and end_s <= start_s:
        end_s = None
    source = "coach" if row.get("source") == "coach" else "curated"
    channel_title = str(row.get("channel_title") or "").strip()[:200] or None
    orientation = row.get("orientation")
    return ExerciseMedia(
        video_id=video_id,
        start_s=start_s,
        end_s=end_s,
        source=source,
        channel_title=channel_title,
        # Anything but a stored portrait/landscape is "not detected yet".
        orientation=orientation if orientation in VIDEO_ORIENTATIONS else None,
    )


def build_media_index(rows: Iterable[Mapping[str, Any]]) -> dict[str, ExerciseMedia]:
    """Map every exercise_key and alias (normalized) to its media.

    A primary key always wins over another row's alias, so an alias can never
    hijack an exercise that has its own video.
    """
    primary: dict[str, ExerciseMedia] = {}
    aliased: dict[str, ExerciseMedia] = {}
    for row in rows:
        media = _media_from_row(row)
        key = normalize_exercise_key(row.get("exercise_key"))
        if media is None or not key:
            continue
        primary[key] = media
        for alias in row.get("aliases") or []:
            alias_key = normalize_exercise_key(alias)
            if alias_key and alias_key not in aliased:
                aliased[alias_key] = media
    return {**aliased, **primary}


def load_media_index(store: Any, *, now: float | None = None) -> Mapping[str, ExerciseMedia]:
    """Cached index of served media. Never raises."""
    global _index
    current = time.monotonic() if now is None else now
    snapshot = _index
    if snapshot is not None and snapshot.fresh(current):
        return snapshot.by_key
    with _index_lock:
        snapshot = _index
        if snapshot is not None and snapshot.fresh(current):
            return snapshot.by_key
        try:
            by_key = build_media_index(store.list_exercise_media())
            _index = _MediaIndex(by_key=by_key, loaded_at=current, ttl=INDEX_TTL_SECONDS)
        except Exception:  # noqa: BLE001 - media is decoration; the plan must still load
            logger.warning("exercise media index load failed", exc_info=True)
            stale = snapshot.by_key if snapshot is not None else {}
            _index = _MediaIndex(by_key=stale, loaded_at=current, ttl=INDEX_FAILURE_TTL_SECONDS)
        return _index.by_key


def reset_media_index_cache() -> None:
    global _index
    with _index_lock:
        _index = None


# Blocks that are never a physical exercise and so never carry a demo video.
NON_PHYSICAL_BLOCK_TYPES = frozenset({"mindset", "nutrition", "sparring"})
# Response-map key for a block resolved through its canonical identity. The
# prefix keeps it apart from the legacy display_name keys, so two blocks that
# share copy ("3 x 2 min easy rounds") but not identity never share a video.
EXERCISE_KEY_MEDIA_PREFIX = "exercise:"


def _iter_blocks(structured_plan: Any) -> Iterable[Any]:
    for week in getattr(structured_plan, "weeks", None) or []:
        for day in getattr(week, "days", None) or []:
            for session in getattr(day, "sessions", None) or []:
                for block in getattr(session, "blocks", None) or []:
                    if getattr(block, "block_type", None) in NON_PHYSICAL_BLOCK_TYPES:
                        continue
                    yield block


def _media_for_display_name(name: str, index: Mapping[str, ExerciseMedia]) -> ExerciseMedia | None:
    media = index.get(normalize_exercise_key(name))
    if media is None:
        # Plans saved before display names were cleaned can still carry the
        # dose in the name; the exercise is the part before it.
        base = strip_dose_suffix(name)
        if base != name:
            media = index.get(normalize_exercise_key(base))
    return media


def resolve_plan_exercise_media(
    structured_plan: Any,
    index: Mapping[str, ExerciseMedia],
) -> dict[str, ExerciseMedia]:
    """Media for every physical block in the plan that has a video.

    A block with a canonical ``exercise_key`` resolves on that identity only
    (its primary row, else an explicit alias of another row) and is keyed
    ``"exercise:<key>"``: its display_name is presentation copy and is never
    consulted. A block without one (every plan stored before identity existed)
    falls back to legacy display_name matching and is keyed by display_name.
    """
    if structured_plan is None or not index:
        return {}
    resolved: dict[str, ExerciseMedia] = {}
    for block in _iter_blocks(structured_plan):
        exercise_key = normalize_exercise_key(getattr(block, "exercise_key", None))
        if exercise_key:
            map_key = f"{EXERCISE_KEY_MEDIA_PREFIX}{exercise_key}"
            if map_key not in resolved and (media := index.get(exercise_key)) is not None:
                resolved[map_key] = media
            continue
        name = getattr(block, "display_name", None)
        if not isinstance(name, str) or not name.strip() or name in resolved:
            continue
        media = _media_for_display_name(name, index)
        if media is not None:
            resolved[name] = media
    return resolved


def resolve_session_exercise_media(session: Mapping[str, Any], index: Mapping[str, ExerciseMedia]) -> dict[str, ExerciseMedia]:
    """Current/frozen rehab can be generated after the saved plan. Exact IDs only."""
    resolved = {}
    for block in session.get("blocks", []):
        if block.get("block_type") in NON_PHYSICAL_BLOCK_TYPES:
            continue
        if (block.get("block_type") == "rehab" and block.get("exercise_key")
                and normalize_exercise_key(block["exercise_key"]) != normalize_exercise_key(block.get("rehab_drill_id"))):
            continue
        key = normalize_exercise_key(block.get("exercise_key") or block.get("rehab_drill_id"))
        if key and (media := index.get(key)) is not None:
            resolved[f"{EXERCISE_KEY_MEDIA_PREFIX}{key}"] = media
    return resolved


def attach_exercise_media(detail: Any, store: Any) -> Any:
    """Populate ``detail.outputs.exercise_media`` in place. Never raises."""
    try:
        outputs = getattr(detail, "outputs", None)
        structured_plan = getattr(outputs, "structured_plan", None)
        if outputs is None or structured_plan is None:
            return detail
        outputs.exercise_media = resolve_plan_exercise_media(
            structured_plan,
            load_media_index(store),
        )
    except Exception:  # noqa: BLE001
        logger.warning("exercise media attach failed", exc_info=True)
    return detail


# ---------------------------------------------------------------------------
# Availability checks (import tool + daily worker sweep)
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class VideoCheck:
    status: str  # "ok" | "unavailable" | "unknown"
    reason: str | None = None
    title: str | None = None
    channel_title: str | None = None
    made_for_kids: bool | None = None
    # "portrait" | "landscape", or None when YouTube reported no dimensions.
    orientation: str | None = None


def orientation_from_dimensions(width: Any, height: Any) -> str | None:
    """Portrait when taller than wide; square counts as landscape.

    None when either side is missing or unusable, so a caller can tell "not
    reported" from a real answer and keep what is already stored.
    """
    try:
        w, h = float(width), float(height)
    except (TypeError, ValueError):
        return None
    if not (w > 0 and h > 0):  # also rejects NaN
        return None
    return "portrait" if h > w else "landscape"


def is_youtube_provider_failure(check: VideoCheck) -> bool:
    """Whether an unknown result came from the Data API, not the video itself."""
    reason = (check.reason or "").lower()
    return check.status == "unknown" and (
        reason.startswith("transport:") or reason.startswith("data api")
    )


def youtube_api_key() -> str | None:
    return (os.getenv(YOUTUBE_API_KEY_ENV) or "").strip() or None


def _classify_video(item: Mapping[str, Any]) -> VideoCheck:
    snippet = item.get("snippet") or {}
    status = item.get("status") or {}
    player = item.get("player") or {}
    made_for_kids = status.get("madeForKids")
    found = {
        "title": str(snippet.get("title") or "").strip()[:200] or None,
        "channel_title": str(snippet.get("channelTitle") or "").strip()[:200] or None,
        "made_for_kids": made_for_kids if isinstance(made_for_kids, bool) else None,
        "orientation": orientation_from_dimensions(
            player.get("embedWidth"), player.get("embedHeight")
        ),
    }
    upload_status = status.get("uploadStatus")
    if upload_status is not None and upload_status != "processed":
        return VideoCheck(status="unavailable", reason=f"upload {upload_status}", **found)
    if status.get("privacyStatus") == "private":
        return VideoCheck(status="unavailable", reason="private", **found)
    if status.get("embeddable") is False:
        return VideoCheck(status="unavailable", reason="embedding disabled", **found)
    # A curator may deliberately approve an embeddable Made for Kids demo.
    # We still require YouTube to explicitly report the classification so the
    # stored metadata remains accurate.
    if not isinstance(made_for_kids, bool) or status.get("embeddable") is not True:
        return VideoCheck(status="unknown", reason="status not reported", **found)
    return VideoCheck(status="ok", **found)


def check_youtube_videos(
    video_ids: Iterable[str],
    *,
    api_key: str,
    client: httpx.Client | None = None,
) -> dict[str, VideoCheck]:
    """Check each video through the YouTube Data API (videos.list).

    One call covers up to 50 videos and reports what serving needs: whether
    the video still exists and is public or unlisted, whether embedding is
    allowed, its Made for Kids status, and whether it is portrait or
    landscape (from the embed dimensions). A video missing from the response
    is deleted or private. Transport errors and non-200 answers (quota, bad
    key) are "unknown": a flaky network must never retire a good video.
    """
    results: dict[str, VideoCheck] = {}
    pending: list[str] = []
    for video_id in dict.fromkeys(video_ids):
        if _VIDEO_ID_RE.match(video_id or ""):
            pending.append(video_id)
        else:
            results[video_id] = VideoCheck(status="unavailable", reason="invalid video id")
    if not pending:
        return results

    owns_client = client is None
    http = client or httpx.Client(timeout=YOUTUBE_API_TIMEOUT_SECONDS)
    try:
        for offset in range(0, len(pending), _VIDEOS_PER_REQUEST):
            batch = pending[offset : offset + _VIDEOS_PER_REQUEST]
            results.update(_check_batch(http, batch, api_key))
    finally:
        if owns_client:
            http.close()
    return results


def _check_batch(http: httpx.Client, batch: list[str], api_key: str) -> dict[str, VideoCheck]:
    def unknown(reason: str) -> dict[str, VideoCheck]:
        return {video_id: VideoCheck(status="unknown", reason=reason) for video_id in batch}

    try:
        # The key goes in a header, not the query string, so request logging
        # never records it.
        response = http.get(
            YOUTUBE_VIDEOS_URL,
            params={
                "part": "snippet,status,player",
                "id": ",".join(batch),
                # embedWidth / embedHeight are only returned with a size bound.
                "maxHeight": _PLAYER_MAX_HEIGHT,
                "fields": (
                    "items(id,snippet(title,channelTitle),"
                    "status(uploadStatus,privacyStatus,embeddable,madeForKids),"
                    "player(embedWidth,embedHeight))"
                ),
            },
            headers={"X-Goog-Api-Key": api_key},
        )
    except httpx.HTTPError as exc:
        return unknown(f"transport: {type(exc).__name__}")
    if response.status_code != 200:
        return unknown(f"data api {response.status_code}")
    try:
        items = response.json().get("items") or []
    except ValueError:
        return unknown("data api: invalid json")
    by_id = {str(item.get("id")): item for item in items if isinstance(item, dict)}
    return {
        video_id: _classify_video(by_id[video_id])
        if video_id in by_id
        else VideoCheck(status="unavailable", reason="not found or private")
        for video_id in batch
    }


def check_youtube_video(
    video_id: str,
    *,
    api_key: str,
    client: httpx.Client | None = None,
) -> VideoCheck:
    return check_youtube_videos([video_id], api_key=api_key, client=client)[video_id]


def run_media_verification_sweep(
    store: Any,
    *,
    api_key: str | None = None,
    client: httpx.Client | None = None,
    should_stop: Callable[[], bool] | None = None,
) -> dict[str, int]:
    """Re-check every stored video and record the result. Never raises per row.

    Unavailable rows are re-checked too, so a video that was only briefly
    private or restricted is served again once YouTube reports it as fine.

    Rows go in batches of 50 (one API call each) and ``should_stop`` is asked
    between batches, so a worker shutting down waits for at most one batch.

    The API process picks up the new statuses when its index cache expires
    (INDEX_TTL_SECONDS); this usually runs in the worker, whose cache is not
    the one serving plans.
    """
    counts = {"ok": 0, "unavailable": 0, "unknown": 0, "provider_stopped": 0}
    key = api_key or youtube_api_key()
    if not key:
        logger.warning("exercise media verification skipped: %s is not set", YOUTUBE_API_KEY_ENV)
        return counts
    rows = list(store.list_exercise_media_for_verification())
    owns_client = client is None
    http = client or httpx.Client(timeout=YOUTUBE_API_TIMEOUT_SECONDS)
    try:
        for offset in range(0, len(rows), _VIDEOS_PER_REQUEST):
            if should_stop is not None and should_stop():
                logger.info("exercise media verification stopped early at row %s of %s", offset, len(rows))
                break
            batch = rows[offset : offset + _VIDEOS_PER_REQUEST]
            results = check_youtube_videos(
                (str(row.get("video_id") or "") for row in batch),
                api_key=key,
                client=http,
            )
            provider_failures = [
                result for result in results.values()
                if is_youtube_provider_failure(result)
            ]
            if provider_failures:
                counts["unknown"] += len(provider_failures)
                counts["provider_stopped"] = 1
                logger.warning(
                    "exercise media verification stopped: YouTube Data API unavailable (%s)",
                    provider_failures[0].reason or "unknown provider failure",
                )
                break
            for row in batch:
                _record_check(row, results, store.update_exercise_media_status, counts)
    finally:
        if owns_client:
            http.close()
    logger.info("exercise media verification sweep: %s", counts)
    return counts


def _record_check(
    row: Mapping[str, Any],
    results: Mapping[str, VideoCheck],
    updater: Callable[..., Any],
    counts: dict[str, int],
) -> None:
    exercise_key = str(row.get("exercise_key") or "")
    result = results.get(str(row.get("video_id") or "")) or VideoCheck(status="unknown")
    counts[result.status] = counts.get(result.status, 0) + 1
    if result.status == "unknown":
        return
    try:
        updater(
            exercise_key,
            status=result.status,
            reason=result.reason,
            made_for_kids=result.made_for_kids,
            title=result.title,
            channel_title=result.channel_title,
            orientation=result.orientation,
        )
    except Exception:  # noqa: BLE001
        logger.warning("exercise media status update failed key=%s", exercise_key, exc_info=True)

api/services/open_plan_timeline.py:
"""Calendar projection for renewable open training plans.

Open plans do not have an event countdown. Their persisted structured card is a
weekly template (or four already-expanded weeks), and this module projects it
onto the current renewable block from one stable anchor: the Monday of the week
the athlete can start training in — the creation week for a plan generated
Mon-Thu, the coming Monday for one generated Fri-Sun (see
``open_plan_anchor_date``).

The projection is deliberately strict.  Legacy cards are only assigned
weekdays when their day count and coach-owned pattern agree with the saved
``open_plan_spec.weekly_template``; ambiguous cards remain undated rather than
silently attaching a session to the wrong day.
"""

from __future__ import annotations

import copy
import json
import re
from datetime import date, timedelta
from typing import Any, Mapping

from fightcamp.weekly_schedule_view import normalize_weekday
from api.datetimes import parse_calendar_date as _parse_date


WEEKDAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
# Detects an athlete-owned hard-sparring / contact day from its card text. Matches
# the coach-neutral labels ("Hard sparring", "Technical-only combat", "controlled
# hard contact", "Light Combat / Technical") and the legacy "coach-led" wording so
# stored plans still resolve.
_COACH_LED_RE = re.compile(
    r"\b(coach|spar(?:r(?:ing|ed)|s)?|boxing|pads?|mitts?|technical[-\s]+only|controlled\s+hard\s+contact"
    r"|light\s+(?:technical\s+)?combat)\b",
    re.I,
)


def _mapping(value: Any) -> dict[str, Any]:
    if isinstance(value, Mapping):
        return dict(value)
    if isinstance(value, str) and value.strip():
        try:
            decoded = json.loads(value)
        except (TypeError, ValueError):
            return {}
        return dict(decoded) if isinstance(decoded, Mapping) else {}
    return {}


def _ordered_weekdays(values: Any) -> list[str]:
    if not isinstance(values, (list, tuple, set)):
        return []
    normalized = {day for value in values if (day := normalize_weekday(value))}
    return [day for day in WEEKDAYS if day in normalized]


def open_plan_spec(plan_row: Mapping[str, Any]) -> dict[str, Any] | None:
    if _parse_date(plan_row.get("fight_date")) is not None:
        return None
    planning_brief = _mapping(plan_row.get("planning_brief"))
    spec = planning_brief.get("open_plan_spec")
    if not isinstance(spec, Mapping) or spec.get("plan_type") != "open_ongoing_system":
        return None
    return dict(spec)


def schedule_mode(plan_row: Mapping[str, Any]) -> str:
    if _parse_date(plan_row.get("fight_date")) is not None:
        return "event_countdown"
    if open_plan_spec(plan_row) is not None:
        return "open_recurring"
    return "static_undated"


# How far into the week a plan can be created and still join the week it was
# created in. Creating on Mon-Thu leaves at least three days of the block's first
# week to train, so the plan goes live immediately; a Fri/Sat/Sun plan would join
# a week that is effectively over, so it starts on the coming Monday instead.
_JOIN_CURRENT_WEEK_SHIFT = timedelta(days=3)


def _athlete_local_creation_date(plan_row: Mapping[str, Any]) -> date | None:
    """Creation date corrected to the athlete-local calendar day when known.

    ``plans.created_at`` is stored as a UTC timestamp. Around midnight UTC its
    date prefix can be one day ahead of, or behind, the athlete's local date. The
    Stage 2 planning brief already persists the creation weekday together with
    ``plan_creation_weekday_basis=athlete_local_weekday``. Since real timezone
    offsets can only move a timestamp onto the same, previous, or next calendar
    day, that persisted weekday is enough to correct the UTC date without adding
    timezone-dependent response plumbing or changing the database schema.

    Legacy briefs without the explicit athlete-local basis keep the historical
    UTC/date-only fallback.
    """

    created = _parse_date(plan_row.get("created_at"))
    if created is None:
        return None

    planning_brief = _mapping(plan_row.get("planning_brief"))
    athlete_model = planning_brief.get("athlete_snapshot")
    if not isinstance(athlete_model, Mapping):
        # Compatibility for hand-built fixtures and any early brief shape that
        # used the model's internal name instead of the persisted contract key.
        athlete_model = planning_brief.get("athlete_model")
    if not isinstance(athlete_model, Mapping):
        return created
    if athlete_model.get("plan_creation_weekday_basis") != "athlete_local_weekday":
        return created

    local_weekday = normalize_weekday(athlete_model.get("plan_creation_weekday"))
    if local_weekday not in WEEKDAYS:
        return created

    utc_weekday_index = created.weekday()
    local_weekday_index = WEEKDAYS.index(local_weekday)
    if local_weekday_index == (utc_weekday_index - 1) % 7:
        return created - timedelta(days=1)
    if local_weekday_index == (utc_weekday_index + 1) % 7:
        return created + timedelta(days=1)
    return created


def open_plan_anchor_date(plan_row: Mapping[str, Any]) -> date | None:
    """The Monday the plan's renewable block starts on.

    A plan is generated mid-week far more often than on a Monday, so the anchor
    is the Monday of the week the athlete can actually start training in: the
    current week for a Mon-Thu plan, the coming Monday for a Fri-Sun one.
    Anchoring every plan forward to the *next* Monday left a plan created on
    Tuesday dormant for six days, and made the projected block sit a week ahead
    of the live calendar — so nothing on the plan matched the real training day.
    """

    created = _athlete_local_creation_date(plan_row)
    if created is None:
        return None
    shifted = created + _JOIN_CURRENT_WEEK_SHIFT
    return shifted - timedelta(days=shifted.weekday())


def _coach_owned_days(template: Mapping[str, Any]) -> list[str]:
    coach_owned = template.get("coach_owned_days")
    coach_owned = coach_owned if isinstance(coach_owned, Mapping) else {}
    values: list[Any] = []
    for key in ("technical_skill_days", "support_work_days", "hard_sparring_days"):
        raw = coach_owned.get(key)
        if isinstance(raw, (list, tuple, set)):
            values.extend(raw)
    # Older open-plan briefs exposed these declarations only at template level.
    for key in ("support_work_days", "hard_sparring_days"):
        raw = template.get(key)
        if isinstance(raw, (list, tuple, set)):
            values.extend(raw)
    return _ordered_weekdays(values)


def _is_coach_led_day(day: Mapping[str, Any]) -> bool:
    today_card = day.get("today_card")
    today_card = today_card if isinstance(today_card, Mapping) else {}
    if str(today_card.get("coach_led_contact") or "").strip():
        return True

    sessions = [item for item in (day.get("sessions") or []) if isinstance(item, Mapping)]
    has_executable_blocks = any(
        isinstance(session.get("blocks"), list) and bool(session.get("blocks"))
        for session in sessions
    )
    text = " ".join(
        str(value or "")
        for value in (
            today_card.get("headline"),
            *(session.get("title") for session in sessions),
            *(session.get("session_type") for session in sessions),
        )
    )
    return not has_executable_blocks and _COACH_LED_RE.search(text) is not None


def _is_safe_legacy_off_day(day: Mapping[str, Any]) -> bool:
    """Whether a full-calendar legacy slot is provably not a training day."""

    sessions = [item for item in (day.get("sessions") or []) if isinstance(item, Mapping)]
    today_card = day.get("today_card")
    today_card = today_card if isinstance(today_card, Mapping) else {}
    return (
        not sessions
        and not str(today_card.get("coach_led_contact") or "").strip()
        and str(day.get("day_type") or "").strip().lower() in {"rest", "recovery"}
    )


def _resolve_template_days(
    days: Any, training_days: list[str]
) -> list[dict[str, Any]] | None:
    """Resolve one template week without guessing ambiguous session placement.

    Current cards contain only the configured training weekdays.  One historical
    converter emitted all seven calendar slots instead; that shape is safe to
    recover only when every omitted weekday is an empty rest/recovery day.
    """

    if not isinstance(days, list):
        return None

    if len(days) == len(training_days):
        pairs = list(zip(training_days, days, strict=True))
    elif len(days) == len(WEEKDAYS):
        calendar_pairs = list(zip(WEEKDAYS, days, strict=True))
        for weekday, day in calendar_pairs:
            if not isinstance(day, Mapping):
                return None
            explicit_weekday = normalize_weekday(day.get("weekday"))
            if explicit_weekday and explicit_weekday != weekday:
                return None
            if weekday not in training_days and not _is_safe_legacy_off_day(day):
                return None
        pairs = [(weekday, day) for weekday, day in calendar_pairs if weekday in training_days]
    else:
        return None

    resolved: list[dict[str, Any]] = []
    for weekday, day in pairs:
        if not isinstance(day, Mapping):
            return None
        explicit_weekday = normalize_weekday(day.get("weekday"))
        if explicit_weekday and explicit_weekday != weekday:
            return None
        normalized = copy.deepcopy(dict(day))
        normalized["weekday"] = weekday
        resolved.append(normalized)
    return resolved


_OPEN_TEMPLATE_WEEK_TYPES = ("stabilise", "build", "specific_peak", "deload")


def _expand_single_template_week(
    weeks: list[dict[str, Any]], spec: Mapping[str, Any]
) -> list[dict[str, Any]] | None:
    if len(weeks) == 4:
        return weeks
    if len(weeks) != 1:
        return None

    development = spec.get("development_block")
    development = development if isinstance(development, Mapping) else {}
    base = weeks[0]
    base_id = str(base.get("week_id") or "open-template").strip() or "open-template"
    expanded: list[dict[str, Any]] = []
    for position in range(1, 5):
        week = copy.deepcopy(base)
        goal = str(development.get(f"week_{position}") or week.get("week_goal") or "").strip()
        week["week_id"] = f"{base_id}-w{position}"
        week["week_index"] = position
        if goal:
            week["week_goal"] = goal
        progression = week.get("progression")
        if not isinstance(progression, Mapping):
            progression = {}

        progression["week_type"] = _OPEN_TEMPLATE_WEEK_TYPES[position - 1]
        if goal:
            progression["planned_change_from_previous"] = goal
        week["progression"] = progression
        expanded.append(week)
    return expanded


# Fail-closed reason codes for an open plan that could not be projected. Each is
# set at exactly one early-return in ``project_open_structured_plan`` so an
# undated open plan resolves to a single logged field. ``None`` means either the
# projection succeeded or the plan is not an open plan (no projection attempted).
PROJECTION_REASON_NO_ANCHOR = "no_anchor"
PROJECTION_REASON_NO_TRAINING_DAYS = "no_training_days"
PROJECTION_REASON_NO_WEEKS = "no_weeks"
PROJECTION_REASON_MALFORMED_WEEK = "malformed_week"
# Day count is neither ``len(training_days)`` nor 7, or a legacy full-week card
# has an ambiguous off-day / a weekday that disagrees with its position.
PROJECTION_REASON_DAY_SHAPE_UNRESOLVED = "day_shape_unresolved"
PROJECTION_REASON_COACH_LED_OFF_OWNED_DAY = "coach_led_off_owned_day"
PROJECTION_REASON_HARD_DAY_NOT_COACH_LED = "hard_day_not_coach_led"
PROJECTION_REASON_WEEK_COUNT_UNEXPANDABLE = "week_count_unexpandable"


def _base_context(
    plan_row: Mapping[str, Any], *, current_training_day: date | None
) -> dict[str, Any]:
    mode = schedule_mode(plan_row)
    return {
        "schedule_mode": mode,
        "projection_status": "not_required" if mode == "event_countdown" else "unavailable",
        "projection_reason": None,
        "anchor_date": None,
        "current_training_day": current_training_day.isoformat() if current_training_day else None,
        "block_number": None,
        "current_week_number": None,
    }


def project_open_structured_plan(
    plan_row: Mapping[str, Any],
    structured_plan: Mapping[str, Any] | None,
    *,
    current_training_day: date | str | None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Return ``(projected_plan, response_context)`` for an open plan.

    Dated camps and non-open legacy plans pass through unchanged.  A failed
    legacy reconciliation also passes through unchanged with
    ``projection_status=unavailable``.
    """

    source = dict(structured_plan or {})
    training_day = (
        current_training_day
        if isinstance(current_training_day, date)
        else _parse_date(current_training_day)
    )
    context = _base_context(plan_row, current_training_day=training_day)
    spec = open_plan_spec(plan_row)
    if spec is None:
        return source, context

    def _unavailable(reason: str) -> tuple[dict[str, Any], dict[str, Any]]:
        """Return the card undated, recording which fail-closed guard tripped."""
        context["projection_reason"] = reason
        return source, context

    anchor = open_plan_anchor_date(plan_row)
    template = spec.get("weekly_template")
    template = template if isinstance(template, Mapping) else {}
    training_days = _ordered_weekdays(template.get("training_days"))
    coach_owned_days = set(_coach_owned_days(template))
    hard_sparring_days = set(_ordered_weekdays(template.get("hard_sparring_days")))
    weeks = source.get("weeks")
    if anchor is None:
        return _unavailable(PROJECTION_REASON_NO_ANCHOR)
    if not training_days:
        return _unavailable(PROJECTION_REASON_NO_TRAINING_DAYS)
    if not isinstance(weeks, list) or not weeks:
        return _unavailable(PROJECTION_REASON_NO_WEEKS)

    if training_day is None or training_day < anchor:
        block_number = 1
        current_week_number = 1
    else:
        elapsed = (training_day - anchor).days
        block_number = elapsed // 28 + 1
        current_week_number = (elapsed % 28) // 7 + 1

    # Validate every week before applying any dates so projection is atomic.
    resolved_weeks: list[dict[str, Any]] = []
    for week in weeks:
        if not isinstance(week, Mapping):
            return _unavailable(PROJECTION_REASON_MALFORMED_WEEK)
        resolved_days = _resolve_template_days(week.get("days"), training_days)
        if resolved_days is None:
            return _unavailable(PROJECTION_REASON_DAY_SHAPE_UNRESOLVED)
        for day, expected_weekday in zip(resolved_days, training_days, strict=True):
            is_coach_led = _is_coach_led_day(day)
            # A coach-led card may only land on a declared coach-owned day, and
            # a declared hard-sparring day must remain coach-led. Technical days
            # are allowed to carry executable app work as well, so they do not
            # have to be sessionless to reconcile safely.
            if is_coach_led and expected_weekday not in coach_owned_days:
                return _unavailable(PROJECTION_REASON_COACH_LED_OFF_OWNED_DAY)
            if expected_weekday in hard_sparring_days and not is_coach_led:
                return _unavailable(PROJECTION_REASON_HARD_DAY_NOT_COACH_LED)
        normalized_week = copy.deepcopy(dict(week))
        normalized_week["days"] = resolved_days
        resolved_weeks.append(normalized_week)

    resolved_weeks = _expand_single_template_week(resolved_weeks, spec)
    if resolved_weeks is None:
        return _unavailable(PROJECTION_REASON_WEEK_COUNT_UNEXPANDABLE)

    projected = copy.deepcopy(source)
    projected["weeks"] = resolved_weeks
    block_anchor = anchor + timedelta(days=(block_number - 1) * 28)
    for week_position, week in enumerate(projected["weeks"]):
        week_start = block_anchor + timedelta(days=week_position * 7)
        week["start_date"] = week_start.isoformat()
        week["end_date"] = (week_start + timedelta(days=6)).isoformat()
        week["countdown_start"] = None
        week["countdown_end"] = None
        for day, weekday in zip(week["days"], training_days, strict=True):
            projected_date = week_start + timedelta(days=WEEKDAYS.index(weekday))
            day["weekday"] = weekday
            day["date"] = projected_date.isoformat()
            day["countdown_label"] = ""

    context.update(
        {
            "projection_status": "projected",
            "anchor_date": anchor.isoformat(),
            "block_number": block_number,
            "current_week_number": current_week_number,
        }
    )
    return projected, context

api/services/streaks.py:
"""Server-authoritative app, training-consistency and plan-adherence streaks."""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from datetime import date, datetime
from typing import Any

from api.services.active_plan import resolve_active_plan
from api.services.today_service import _structured_session_entry_for_day, resolve_training_day
from api.services.week_progress import COMPLETED_STATUSES, _latest_statuses, _plan_for_training_day
from api.store import AppStore
from api.optional_sessions import is_optional_session


def _rows(value: object) -> list[dict[str, Any]]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
        return []
    return [dict(row) for row in value if isinstance(row, Mapping)]


def _read_state(store: AppStore, athlete_id: str) -> dict[str, Any]:
    return dict(store.get_athlete_streaks(athlete_id) or {})


def _write_state(store: AppStore, athlete_id: str, fields: Mapping[str, Any]) -> dict[str, Any]:
    return dict(store.upsert_athlete_streaks(athlete_id, dict(fields)))


def _public_state(row: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "login": {
            "current": max(0, int(row.get("login_current") or 0)),
            "best": max(0, int(row.get("login_best") or 0)),
            "last_active_date": row.get("login_last_active_date"),
        },
        "adherence": {
            # API key retained for the existing XP-card contract. The values are
            # the athlete-facing Training Streak, not plan adherence.
            "current": max(0, int(row.get("training_current") or 0)),
            "best": max(0, int(row.get("training_best") or 0)),
            "last_qualifying_day": row.get("training_last_qualifying_day"),
        },
        "plan_adherence": {
            "current": max(0, int(row.get("adherence_current") or 0)),
            "best": max(0, int(row.get("adherence_best") or 0)),
            "last_qualifying_day": row.get("adherence_last_qualifying_day"),
        },
    }


def record_daily_activity(
    store: AppStore, *, athlete_id: str, athlete_timezone: str | None, now: datetime | None = None
) -> dict[str, Any]:
    """Record at most one activity row for the server-resolved effective day.

    The store records the day and rebuilds the login streak in one atomic step
    (the ``record_athlete_daily_activity`` RPC) and returns the streak row.
    """
    activity_day = date.fromisoformat(resolve_training_day(athlete_timezone, now=now))
    return _public_state(store.record_daily_activity(athlete_id, activity_day.isoformat()))


def _scheduled_days(plan: Mapping[str, Any], training_day: str) -> list[tuple[date, set[str]]]:
    projected = _plan_for_training_day(plan, training_day)
    structured = projected.get("structured_plan")
    weeks = structured.get("weeks") if isinstance(structured, Mapping) else None
    result: list[tuple[date, set[str]]] = []
    for week in _rows(weeks):
        for day_row in _rows(week.get("days")):
            if str(day_row.get("day_type") or "").lower() == "rest":
                continue
            try:
                scheduled = date.fromisoformat(str(day_row.get("date")))
            except ValueError:
                continue
            ids = {
                str(row.get("session_id") or "").strip()
                for row in _rows(day_row.get("sessions"))
                if not is_optional_session(row)
            }
            ids.discard("")
            if ids:
                result.append((scheduled, ids))
    return sorted(result)


def _training_schedule(plan: Mapping[str, Any], training_day: str) -> dict[date, set[str]]:
    """Expected training days and their canonical app-session identities."""
    projected = _plan_for_training_day(plan, training_day)
    structured = projected.get("structured_plan")
    weeks = structured.get("weeks") if isinstance(structured, Mapping) else None
    result: dict[date, set[str]] = {}
    for week in _rows(weeks):
        for day_row in _rows(week.get("days")):
            try:
                scheduled = date.fromisoformat(str(day_row.get("date")))
            except ValueError:
                continue
            ids = {
                str(session.get("session_id") or "").strip()
                for session in _rows(day_row.get("sessions"))
                if not is_optional_session(session)
            }
            ids.discard("")
            # Sessionless coach/technical work is still expected training. The
            # Today projection owns the distinction between that and true rest.
            if ids or _structured_session_entry_for_day(day_row, week=week) is not None:
                result[scheduled] = ids
    return result


def _all_completions(store: AppStore, athlete_id: str) -> list[dict[str, Any]]:
    return _rows(store.list_session_completions(athlete_id, limit=500))


def _session_logs(store: AppStore, athlete_id: str) -> list[dict[str, Any]]:
    return _rows(store.list_session_logs(athlete_id, limit=500))


def qualifying_training_days(
    store: AppStore,
    *,
    athlete_id: str,
    today: date,
) -> tuple[set[date], set[date]]:
    """Return (completed training days, explicitly skipped expected days).

    Current session completions qualify only when tied to a canonical scheduled
    session, or to a sessionless coach/technical day in that completion's plan.
    Completed legacy/manual ``session_logs`` are authoritative actual training.
    """
    schedules: dict[str, dict[date, set[str]]] = {}
    qualifying: set[date] = set()
    skipped: set[date] = set()
    for row in _all_completions(store, athlete_id):
        if str(row.get("status") or "") not in {"done", "modified", "skipped"}:
            continue
        try:
            activity_day = date.fromisoformat(str(row.get("training_day")))
        except ValueError:
            continue
        plan_id = str(row.get("plan_id") or "")
        if plan_id not in schedules:
            plan = store.get_plan_for_athlete(plan_id, athlete_id) if plan_id else None
            schedules[plan_id] = _training_schedule(plan, today.isoformat()) if plan else {}
        expected_ids = schedules[plan_id].get(activity_day)
        session_id = str(row.get("session_id") or "").strip()
        # Before canonical identity was enforced, the supported Today flow used
        # the local day as its key for sessionless coach/technical cards. Accept
        # that narrow historical provenance for streak rebuild only; it remains
        # ineligible for XP and arbitrary ids still fail closed.
        legacy_sessionless = (
            expected_ids == set() and session_id == activity_day.isoformat()
        )
        legitimate = expected_ids is not None and (
            session_id in expected_ids or legacy_sessionless
        )
        if not legitimate:
            continue
        if row.get("status") == "skipped":
            skipped.add(activity_day)
        else:
            qualifying.add(activity_day)
    for row in _session_logs(store, athlete_id):
        if row.get("completed") is not True:
            continue
        try:
            qualifying.add(date.fromisoformat(str(row.get("session_date"))))
        except ValueError:
            continue
    return qualifying, skipped


def reconcile_training_streak(
    store: AppStore, *, athlete_id: str, athlete_timezone: str | None, now: datetime | None = None
) -> dict[str, Any]:
    """Rebuild actual-training consistency without awarding XP.

    Completed training advances once per athlete-local day. Expected training
    missed before today breaks the run. Genuine rest days are absent and neutral;
    an unresolved expected current day is also neutral.
    """
    today = date.fromisoformat(resolve_training_day(athlete_timezone, now=now))
    resolution = resolve_active_plan(store, athlete_id, current_training_day=today)
    plan = resolution.plan
    expected = set(_training_schedule(plan, today.isoformat())) if plan else set()
    qualifying, skipped = qualifying_training_days(
        store, athlete_id=athlete_id, today=today
    )
    current = best = 0
    last: date | None = None
    for activity_day in sorted(expected | qualifying | skipped):
        if activity_day > today:
            continue
        if activity_day in qualifying:
            current += 1
            best = max(best, current)
            last = activity_day
        elif activity_day < today or activity_day in skipped:
            current = 0
            last = None
    row = _write_state(store, athlete_id, {
        "training_current": current,
        "training_best": best,
        "training_last_qualifying_day": last.isoformat() if last else None,
    })
    return _public_state(row)


def reconcile_adherence_streak(
    store: AppStore, *, athlete_id: str, athlete_timezone: str | None, now: datetime | None = None
) -> dict[str, Any]:
    today = date.fromisoformat(resolve_training_day(athlete_timezone, now=now))
    resolution = resolve_active_plan(store, athlete_id, current_training_day=today)
    prior = _read_state(store, athlete_id)
    if resolution.plan is None:
        if resolution.source == "read_failure":
            return _public_state(prior)
        row = _write_state(store, athlete_id, {
            "adherence_current": 0,
            "adherence_best": max(0, int(prior.get("adherence_best") or 0)),
            "adherence_last_qualifying_day": None,
        })
        return _public_state(row)
    plan_id = str(resolution.plan.get("id") or "")
    completions = _rows(store.list_plan_session_completions(athlete_id, plan_id, limit=500))
    current = 0
    last_qualifying: date | None = None
    for scheduled, planned in _scheduled_days(resolution.plan, today.isoformat()):
        if scheduled > today:
            continue
        day_completions = [
            row for row in completions
            if str(row.get("training_day") or "") == scheduled.isoformat()
        ]
        statuses, ambiguous = _latest_statuses(planned=planned, completions=day_completions)
        qualifies = not ambiguous and all(statuses.get(item) in COMPLETED_STATUSES for item in planned)
        skipped = any(statuses.get(item) == "skipped" for item in planned)
        if qualifies:
            current += 1
            last_qualifying = scheduled
        elif scheduled < today or skipped:
            current = 0
            last_qualifying = None
        # An unresolved current day is still in progress and is neutral.
    best = max(int(prior.get("adherence_best") or 0), current)
    row = _write_state(store, athlete_id, {
        "adherence_current": current,
        "adherence_best": best,
        "adherence_last_qualifying_day": last_qualifying.isoformat() if last_qualifying else None,
    })
    return _public_state(row)


def get_streak_state(
    store: AppStore, *, athlete_id: str, athlete_timezone: str | None, now: datetime | None = None
) -> dict[str, Any]:
    """Read persisted streak state without recording activity or writing counters."""
    return _public_state(_read_state(store, athlete_id))


__all__ = ["get_streak_state", "qualifying_training_days", "record_daily_activity", "reconcile_adherence_streak", "reconcile_training_streak"]

api/services/training_library.py:
"""Deterministic source-backed search, separate from all prescription engines."""
from __future__ import annotations

from collections import Counter, defaultdict
from dataclasses import asdict, dataclass
from difflib import SequenceMatcher
from pathlib import Path
import re
import threading
import unicodedata

from fightcamp.training_catalogue import (
    ALIASES_FILE, DATA_DIR, MANIFEST_FILE, PHYSICAL_CLASSES, SOURCE_CLASSES,
    build_catalogue, content_hash, source_hash, strings,
)
from api.services.training_library_vocabulary import CONCEPTS, supports

CLASS_LABELS = {
    "strength_power": "Strength & power", "conditioning": "Conditioning",
    "technical_coordination": "Technical drills", "rehabilitation": "Rehabilitation",
    "care_instruction": "Care", "tactical_educational": "Tactical study",
    "visualisation": "Visualisation",
}
SOURCE_LABELS = {
    "exercise_bank.json": "Strength", "conditioning_bank.json": "Conditioning",
    "style_conditioning_bank.json": "Style conditioning", "style_taper_conditioning.json": "Taper conditioning",
    "technical_footwork_bank.json": "Footwork", "rehab_bank.json": "Rehab",
    "tactical_watch_bank.json": "Tactical study", "fight_visualization_bank.json": "Visualisation",
}
BODY_LABELS = {"lower_body": "Legs", "upper_body": "Upper body", "core": "Core", "full_body": "Full body"}
GUIDANCE_FIELDS = {
    "Instructions": ("instructions", "description", "notes"), "Cues": ("cue", "pro_tip"),
    "Why": ("why", "combat_carryover"), "Progress": ("progress", "progression", "progress_when"),
    "Regress": ("regress", "regression", "regress_when"), "Stop": ("stop", "stop_rules", "stop_when", "quality_stop_rule"),
}
FILTERS = ("type", "goal", "sport", "equipment", "body_focus")


def text_key(text: str) -> str:
    text = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode().casefold()
    return " ".join(re.findall(r"[a-z0-9]+", text))


def label(value: str) -> str:
    return {"mma": "MMA", "bjj": "BJJ", "muay_thai": "Muay Thai"}.get(value, value.replace("_", " ").replace("-", " ").capitalize())


def category_of(content_type: str) -> str:
    return "training" if content_type in PHYSICAL_CLASSES else "rehab" if content_type == "rehabilitation" else "learn"


def _known(entry: dict, field: str) -> list[str]:
    return strings(entry["raw"].get(field)) if entry["metadata"].get(field, {}).get("state") == "known" else []


def _prepare(entry: dict) -> dict:
    goals = {alias["label"] for alias in entry["aliases"]}
    goals.update(label(value) for value in _known(entry, "goals"))
    body = set(_known(entry, "body_region") + _known(entry, "target_regions"))
    body.update(v for v in _known(entry, "category") if v in BODY_LABELS)
    # Reviewed context conjunction: lower-body explosive work. Neither generic
    # power nor an anatomical label alone earns this discovery alias.
    if "lower_body" in body and "explosive" in _known(entry, "tags"):
        goals.add("Explosive legs")
    # Explicit defensive technical function, never all footwork.
    if {"defensive_exit", "takedown_defense"}.intersection(_known(entry, "tactical_function")):
        goals.add("Defensive movement")
    equipment = _known(entry, "equipment")
    equipment_known = entry["metadata"]["equipment"]["state"] == "known"
    equipment_values = set(equipment)
    if equipment_known and (not equipment or equipment_values <= {"none", "bodyweight"}):
        equipment_values = {"no_equipment"}
    facets = {
        "type": {entry["content_class"]}, "goal": goals,
        "sport": {e["value"] for e in entry["sport_evidence"]},
        "equipment": equipment_values if equipment_known else set(), "body_focus": body,
    }
    groups = entry["raw_group"] or {}
    context = " · ".join([SOURCE_LABELS.get(entry["source"], "Coordination"),
                           *[label(str(groups[f])) for f in ("location", "type") if groups.get(f)],
                           *[label(v) for f in ("sports", "styles") for v in _known(entry, f)]])
    focus = sorted(goals) or [label(v) for f in ("movement", "category", "qualities", "function") for v in _known(entry, f)][:2]
    aliases = " ".join(sorted(goals))
    metadata = " ".join(piece["text"] for piece in entry["search_evidence"] if piece["field"] not in {"name", "description", "cue", "notes", "instructions", "why"})
    descriptions = " ".join(piece["text"] for piece in entry["search_evidence"] if piece["field"] in {"description", "cue", "notes", "instructions", "why"})
    name = text_key(entry["name"])
    alias_text, metadata_text, description_text = map(text_key, (aliases, metadata, descriptions))
    discovery = [rule for rule in CONCEPTS if entry["content_class"] in PHYSICAL_CLASSES and supports(entry, rule)]
    # A reviewed display term for the explicit lower_body category lets a fighter
    # type 'legs' without inventing a training quality.
    body_text = " ".join(BODY_LABELS.get(value, label(value)) for value in body)
    gear_text = "no equipment bodyweight" if equipment_values == {"no_equipment"} else ""
    # Keep expanded discovery phrases out of the lexical word bag: otherwise a
    # hand-timing phrase plus an unrelated speed tag could manufacture a match.
    corpus = text_key(" ".join((name, alias_text, metadata_text, description_text, body_text, gear_text)))
    return {
        "entry": entry, "facets": facets, "name": name, "aliases": alias_text,
        "metadata": metadata_text, "description": description_text,
        "discovery": discovery,
        "words": frozenset(corpus.split()),
        "summary": {
            "catalogue_id": entry["catalogue_id"], "name": entry["name"],
            "content_type": entry["content_class"], "category": category_of(entry["content_class"]),
            "context": context, "focus": focus, "equipment": equipment if equipment_known else None,
            "equipment_state": entry["metadata"]["equipment"]["state"],
            "exercise_key": entry["exercise_key"], "media": None,
            "selection_boundary": entry["eligibility"]["boundary"], "prescription_allowed": False,
        },
    }


@dataclass(frozen=True)
class LibraryIndex:
    signature: tuple
    revision: str
    records: tuple[dict, ...]
    by_id: dict[str, dict]


class LibraryCache:
    """Cheap source stats per request; content-based public pagination revision.

    Invalid revisions fail closed: never fall back to a previously valid index.
    The lock prevents concurrent requests rebuilding the same 2,855 records.
    """
    def __init__(self, data_dir: Path = DATA_DIR):
        self.data_dir = data_dir
        self._lock = threading.Lock()
        self._index: LibraryIndex | None = None

    def _signature(self) -> tuple:
        sources = tuple((source, stat.st_mtime_ns, stat.st_ctime_ns, stat.st_size)
                     for source in (*SOURCE_CLASSES, MANIFEST_FILE, ALIASES_FILE)
                     for stat in [(self.data_dir / source).stat()])
        # Stats only invalidate this process's cache, never the public revision.
        # The reviewed vocabulary is also a cache input.
        return (*sources, ("discovery_vocabulary", repr(CONCEPTS)))

    def _revision(self) -> str:
        # Include every source and review input, including files with no entries.
        # Normalise checkout line endings just like the catalogue's source hashes.
        sources = [(source, source_hash((self.data_dir / source).read_bytes()))
                   for source in (*SOURCE_CLASSES, MANIFEST_FILE, ALIASES_FILE)]
        return content_hash({"sources": sources, "discovery_vocabulary": [asdict(rule) for rule in CONCEPTS]})

    def get(self) -> LibraryIndex:
        with self._lock:
            signature = self._signature()
            if self._index is not None and self._index.signature == signature:
                return self._index
            revision = self._revision()
            entries = build_catalogue(self.data_dir)
            if self._signature() != signature:
                raise ValueError("Catalogue changed while loading")
            records = tuple(_prepare(entry) for entry in entries)
            duplicate_contexts = defaultdict(list)
            for record in records:
                duplicate_contexts[(record["summary"]["category"], record["name"], record["summary"]["context"])].append(record)
            for group in duplicate_contexts.values():
                if len(group) < 2:
                    continue
                notes = [" ".join(_known(r["entry"], "notes")) for r in group]
                for ordinal, (record, note) in enumerate(zip(group, notes), start=1):
                    # Source wording distinguishes repeated pathway variants;
                    # identical/absent notes use neutral numbered variants.
                    suffix = note if all(notes) and len(set(notes)) == len(group) else f"Variant {ordinal}"
                    record["summary"]["context"] += f" · {suffix}"
            self._index = LibraryIndex(signature, revision, records, {r["entry"]["catalogue_id"]: r for r in records})
            return self._index


cache = LibraryCache()


def _score(record: dict, query: str, matches: dict[str, dict[str, int]], groups: list | None = None) -> int | None:
    if not query:
        return 0
    terms = _query_terms(query)
    words = record["words"]
    penalties = 0
    semantic_scores = []
    for chunk, rules in groups or [(terms, ())]:
        supported = [rule for rule in rules if rule in record.get("discovery", [])]
        literal = all(set(matches[term]).intersection(words) for term in chunk)
        # Recognised fighter intents need a phrase/name match or supported
        # concept. Scattered mechanical-risk words cannot satisfy the intent.
        phrase = " ".join(chunk)
        strong_literal = any(phrase in record.get(field, "") for field in ("name", "aliases", "metadata", "description")) or all(
            any(word.startswith(term) for word in record["name"].split()) for term in chunk)
        if supported:
            semantic_scores.append(max(450 if rule.related else
                800 if any(text_key(phrase) in record.get("aliases", "") for phrase in rule.phrases) else 700 for rule in supported))
        elif not literal or (rules and not strong_literal):
            return None
        for term in chunk:
            costs = [cost for word, cost in matches[term].items() if word in words]
            if costs:
                penalties += min(costs)
    if query == record["name"]:
        return 1000
    scores = [400]
    for field, score in (("name", 900), ("aliases", 800), ("metadata", 650), ("description", 500)):
        if query in record.get(field, ""):
            scores.append(score)
    if all(any(word.startswith(term) for word in record["name"].split()) for term in terms):
        scores.append(850)
    if semantic_scores:
        scores.append(min(semantic_scores))
    return max(scores) - penalties


def _query_terms(query: str) -> list[str]:
    words = query.split()
    # A small closed list permits "I want to hit harder" without treating
    # unsupported training concepts as synonyms. Single-word searches survive.
    meaningful = [word for word in words if word not in {"i", "want", "to", "my", "for", "the", "a", "an", "and", "with"}]
    return meaningful or words


def _intent_groups(query: str) -> list:
    terms = _query_terms(query)
    phrases = [(tuple(_query_terms(text_key(phrase))), rule) for rule in CONCEPTS for phrase in rule.phrases]
    groups = []
    position = 0
    while position < len(terms):
        candidates = []
        for words, rule in phrases:
            chunk = terms[position:position + len(words)]
            if len(chunk) == len(words) and all(term == word or (len(term) >= 3 and word.startswith(term)) or
                    (len(term) >= 4 and abs(len(term) - len(word)) <= 2 and SequenceMatcher(None, term, word).ratio() >= .84)
                    for term, word in zip(chunk, words)):
                candidates.append((len(words), rule))
        length = max((length for length, _ in candidates), default=1)
        groups.append((terms[position:position + length], tuple(dict.fromkeys(rule for size, rule in candidates if size == length))))
        position += length
    return groups


def _discovery_match(record: dict, query: str, groups: list) -> str | None:
    terms = set(_query_terms(query))
    original = set(text_key(" ".join(record.get(field, "") for field in ("name", "aliases", "metadata", "description"))).split())
    if not terms or terms <= original:
        return None
    for _, rules in groups:
        supported = [rule for rule in rules if rule in record.get("discovery", [])]
        if supported:
            rule = next((rule for rule in supported if not rule.related), supported[0])
            return f"{'Related' if rule.related else 'Matches'} · {rule.label}"
    return None


def _matches(record: dict, filters: dict, *, except_field: str | None = None) -> bool:
    for field, selected in filters.items():
        if selected and field != except_field:
            values = record["facets"][field]
            if selected not in values and not (field == "sport" and "universal" in values):
                return False
    return True


def search(index: LibraryIndex, *, q: str = "", category: str = "training", filters: dict | None = None, offset: int = 0, limit: int = 24) -> dict:
    filters = filters or {}
    ranked = []
    query = text_key(q)
    groups = _intent_groups(query) if query and category == "training" else []
    vocabulary = set().union(*(r["words"] for r in index.records if r["summary"]["category"] == category))
    matches = {term: {word: 0 if term == word else 1 if word.startswith(term) else 2
                      for word in vocabulary if term == word or
                      (len(term) >= 3 and word.startswith(term)) or
                      (len(term) >= 4 and abs(len(term) - len(word)) <= 2 and SequenceMatcher(None, term, word).ratio() >= .84)}
               for term in _query_terms(query)}
    for record in index.records:
        if record["summary"]["category"] != category:
            continue
        score = _score(record, query, matches, groups)
        if score is not None:
            ranked.append((score, record))
    facets = {}
    for field in FILTERS:
        counts = Counter(value for _, r in ranked if _matches(r, filters, except_field=field) for value in r["facets"][field])
        facets[field] = [{"value": value, "label": CLASS_LABELS.get(value, BODY_LABELS.get(value, "No equipment" if value == "no_equipment" else label(value))), "count": count}
                         for value, count in sorted(counts.items(), key=lambda pair: label(pair[0]))]
    selected = [r for score, r in sorted(ranked, key=lambda pair: (-pair[0], pair[1]["name"], pair[1]["entry"]["catalogue_id"])) if _matches(r, filters)]
    return {"entries": [{**r["summary"], "discovery_match": _discovery_match(r, query, groups)} for r in selected[offset:offset + limit]], "total": len(selected),
            "catalogue_total": len(index.records), "offset": offset, "limit": limit,
            "next_offset": offset + limit if offset + limit < len(selected) else None,
            "revision": index.revision, "facets": facets}


def preview(record: dict) -> dict:
    entry = record["entry"]
    return {**record["summary"], "source": entry["source"], "source_revision": entry["source_sha256"],
            "row_revision": entry["row_sha256"], "guidance": {
                title: list(dict.fromkeys(value for field in fields for value in _known(entry, field)))
                for title, fields in GUIDANCE_FIELDS.items() if any(_known(entry, field) for field in fields)
            }}

