                raise HTTPException(
                    status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
                    detail="failed to persist feedback",
                )
            return rows[0]
        except HTTPException:
            raise
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to persist feedback")

    def list_admin_feedback(self, *, limit: int = 50) -> list[dict[str, Any]]:
        try:
            response = (
                self.client.table("beta_feedback")
                .select(
                    "id,submitted_by_profile_id,surface,category,response,reason,comment,"
                    "structured_response,contact_allowed,priority,plan_id,today_checkin_id,"
                    "session_id,camp_phase,app_version,"
                    "readiness_snapshot,injury_snapshot,technical_context,"
                    "screenshot_path,screenshot_expires_at,created_at,updated_at,"
                    "profiles!beta_feedback_submitted_by_profile_id_fkey(email,full_name)"
                )
                .order("created_at", desc=True)
                .limit(100)
                .execute()
            )
            rows = getattr(response, "data", None) or []
            rows.sort(
                key=lambda row: (
                    str(row.get("priority") or "normal") == "safety",
                    str(row.get("created_at") or ""),
                ),
                reverse=True,
            )
            return rows[: max(1, min(limit, 100))]
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to read admin feedback")

    def get_feedback_screenshot_path(self, feedback_id: str) -> str | None:
        try:
            row = self._select_first(
                self.client.table("beta_feedback")
                .select("screenshot_path")
                .eq("id", feedback_id)
                .gt("screenshot_expires_at", datetime.now(timezone.utc).isoformat())
            )
            return str(row.get("screenshot_path") or "").strip() or None if row else None
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to read feedback screenshot")

    def create_feedback_screenshot_signed_url(self, path: str, *, expires_in: int) -> str:
        try:
            response = self.client.storage.from_("feedback-screenshots").create_signed_url(
                path,
                expires_in,
            )
            url = str(response.get("signedURL") or response.get("signedUrl") or "").strip()
            if not url:
                raise HTTPException(
                    status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
                    detail="feedback screenshot unavailable",
                )
            return url
        except HTTPException:
            raise
        except _STORAGE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to open feedback screenshot")

    def claim_feedback_rate_limit(
        self,
        profile_id: str,
        *,
        report_limit: int,
        screenshot_limit: int,
        has_screenshot: bool,
    ) -> tuple[bool, str | None, int]:
        try:
            response = self.client.rpc(
                "claim_beta_feedback_rate_limit",
                {
                    "p_submitted_by_profile_id": profile_id,
                    "p_report_limit": report_limit,
                    "p_screenshot_limit": screenshot_limit,
                    "p_window_seconds": 3600,
                    "p_has_screenshot": has_screenshot,
                },
            ).execute()
            rows = getattr(response, "data", None) or []
            if not rows:
                raise HTTPException(
                    status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
                    detail="feedback rate limit unavailable",
                )
            row = rows[0]
            return bool(row.get("allowed")), row.get("blocked_scope"), int(row.get("retry_after_seconds") or 0)
        except HTTPException:
            raise
        except _STORE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="feedback rate limit unavailable")

    def upload_feedback_screenshot(self, path: str, data: bytes, mime: str) -> None:
        try:
            self.client.storage.from_("feedback-screenshots").upload(
                path,
                data,
                {"content-type": mime, "upsert": "false"},
            )
        except _STORAGE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to upload screenshot")

    def delete_feedback_screenshots(self, paths: list[str]) -> None:
        if not paths:
            return
        try:
            self.client.storage.from_("feedback-screenshots").remove(paths)
        except _STORAGE_CLIENT_ERRORS as exc:
            self._raise_feedback_store_error(exc, detail="failed to delete screenshot")

    def list_expired_feedback_screenshots(self, *, limit: int = 100) -> list[dict[str, Any]]:
        response = (
            self.client.table("beta_feedback")
            .select("id,screenshot_path,screenshot_expires_at")
            .not_.is_("screenshot_path", "null")
            .is_("screenshot_deleted_at", "null")
            .lte("screenshot_expires_at", datetime.now(timezone.utc).isoformat())
            .order("screenshot_expires_at")
            .limit(max(1, min(limit, 500)))
            .execute()
        )
        return getattr(response, "data", None) or []

    def list_profile_feedback_screenshots(self, profile_id: str, *, limit: int = 100) -> list[dict[str, Any]]:
        response = (
            self.client.table("beta_feedback")
            .select("id,screenshot_path,screenshot_expires_at")
            .eq("submitted_by_profile_id", profile_id)
            .not_.is_("screenshot_path", "null")
            .order("created_at")
            .limit(max(1, min(limit, 500)))
            .execute()
        )
        return getattr(response, "data", None) or []

    def clear_feedback_screenshot(self, feedback_id: str, expected_path: str) -> bool:
        response = (
            self.client.table("beta_feedback")
            .update(
                {
                    "screenshot_path": None,
                    "screenshot_mime": None,
                    "screenshot_size_bytes": None,
                    "screenshot_width": None,
                    "screenshot_height": None,
                    "screenshot_expires_at": None,
                    "screenshot_deleted_at": datetime.now(timezone.utc).isoformat(),
                }
            )
            .eq("id", feedback_id)
            .eq("screenshot_path", expected_path)
            .execute()
        )
        return bool(getattr(response, "data", None) or [])

api/structured_plan_locked_merge.py:
"""Deterministically render governed banked roles in structured cards.

Stage 1 owns a banked prescription once its role governance marks the selected
drill as locked. Structured conversion may enrich the surrounding card, but it
must not omit, rename, or paraphrase those bank-owned fields. The role's
countdown day is authoritative: converter slips in the day itself (the day split
across two rows, a blank label on a dated row, or the day dropped outright) are
repaired onto that day, and within it this module repairs, moves, or creates the
governed session and block without another model call. Only a drill the
converter placed on a different day stays unresolved, since moving it would be
guessing.

Two banked systems share this pathway (see ``_LOCKED_CONTENT_SPECS``): the
Tactical Watch and the Fight Visualisation countdown protocol. They differ only
in which role field carries the bank object, the fixed session title, and how the
bank record's own fields map onto the card's block -- so the repair, move and
create logic below is written once and driven by that spec.
"""
from __future__ import annotations

import copy
import re
from dataclasses import dataclass, field
from datetime import date
from typing import Any, Iterable, Mapping

from fightcamp.fight_date_utils import parse_fight_date

from .structured_plan_calendar_spine import _resolve_fight_date, _rest_day, _valid_phase
from .structured_plan_sparring_reconcile import reconcile_coach_led_sparring_days


@dataclass(frozen=True)
class LockedContentSpec:
    """How one banked system projects onto a structured card."""

    content_field: str
    session_title: str
    session_slug: str
    session_type: str
    block_type: str


# Order is precedence: a role carrying more than one bank object (never expected)
# resolves to the first match, deterministically.
_LOCKED_CONTENT_SPECS = (
    LockedContentSpec(
        content_field="tactical_watch",
        session_title="Tactical Focus",
        session_slug="tactical-watch",
        session_type="skill",
        block_type="mindset",
    ),
    LockedContentSpec(
        content_field="fight_visualization",
        session_title="Fight Visualisation",
        session_slug="fight-visualization",
        session_type="skill",
        block_type="mindset",
    ),
)


def _spec_for_role(role: Mapping[str, Any]) -> tuple[LockedContentSpec, Mapping[str, Any]] | None:
    for spec in _LOCKED_CONTENT_SPECS:
        content = role.get(spec.content_field)
        if isinstance(content, Mapping):
            return spec, content
    return None


@dataclass(frozen=True)
class LockedMergeApplication:
    countdown_label: str
    block_name: str


@dataclass(frozen=True)
class LockedMergeIssue:
    countdown_label: str | None
    block_name: str
    reason: str


@dataclass
class LockedMergeResult:
    plan: dict[str, Any]
    applied: list[LockedMergeApplication] = field(default_factory=list)
    unresolved: list[LockedMergeIssue] = field(default_factory=list)


def _locked_roles(value: Any) -> Iterable[Mapping[str, Any]]:
    if isinstance(value, Mapping):
        governance = value.get("governance")
        if isinstance(governance, Mapping) and governance.get("selected_drill_locked") is True:
            yield value
        for child in value.values():
            yield from _locked_roles(child)
    elif isinstance(value, (list, tuple)):
        for child in value:
            yield from _locked_roles(child)


def _normalise(value: Any) -> str:
    return " ".join(
        str(value or "")
        .replace("\u2018", "'")
        .replace("\u2019", "'")
        .replace("\u2013", "-")
        .replace("\u2014", "-")
        .lower()
        .split()
    )


def _is_named_variant(value: Any, name: str, *, session_title: str | None = None) -> bool:
    """Recognise converter labels that explicitly name the locked bank drill."""
    label = _normalise(value)
    drill = _normalise(name)
    if label in {
        drill,
        f"{drill} mental rehearsal",
        f"{drill} visualisation",
        f"{drill} visualization",
    }:
        return True
    return bool(
        session_title
        and label in {
            f"{_normalise(session_title)}: {drill}",
            f"{_normalise(session_title)} - {drill}",
        }
    )


def _countdown(value: Any) -> str | None:
    match = re.search(r"D-\s*(\d+)", str(value or ""), re.IGNORECASE)
    return f"D-{int(match.group(1))}" if match else None


def _role_day(role: Mapping[str, Any]) -> str | None:
    # This is the same precedence used by the existing locked faithfulness path.
    for key in ("scheduled_countdown_label", "countdown_label", "countdown_display_label"):
        label = _countdown(role.get(key))
        if label:
            return label
    return None


def _days(plan: Mapping[str, Any]) -> Iterable[dict[str, Any]]:
    for week in plan.get("weeks") or []:
        if not isinstance(week, Mapping):
            continue
        for day in week.get("days") or []:
            if isinstance(day, dict):
                yield day


def _day_dday(day: Mapping[str, Any], fight_date: date | None) -> int | None:
    """A day's countdown distance from its label, else from its ISO date."""
    label = _countdown(day.get("countdown_label"))
    if label is not None:
        return int(label[2:])
    if fight_date is None:
        return None
    parsed = parse_fight_date(str(day.get("date") or "").strip())
    if parsed is None:
        return None
    delta = (fight_date - parsed).days
    return delta if delta >= 0 else None


def _drill_on_card(plan: Mapping[str, Any], names: set[str]) -> bool:
    return any(
        _is_named_variant(value, name)
        for day in _days(plan)
        for session in day.get("sessions") or []
        if isinstance(session, Mapping)
        for value in [session.get("title")]
        + [
            block.get("display_name")
            for block in session.get("blocks") or []
            if isinstance(block, Mapping)
        ]
        for name in names
    )


def _insert_day(plan: dict[str, Any], day: dict[str, Any], d_day: int, fight_date: date) -> None:
    """Place a new day in the week whose countdown span covers it, else the nearest."""
    best: tuple[int, list[Any]] | None = None
    for week in plan.get("weeks") or []:
        if not isinstance(week, dict) or not isinstance(week.get("days"), list):
            continue
        ddays = [
            value
            for value in (
                _day_dday(item, fight_date) for item in week["days"] if isinstance(item, Mapping)
            )
            if value is not None
        ]
        if not ddays:
            continue
        distance = 0 if min(ddays) <= d_day <= max(ddays) else min(abs(v - d_day) for v in ddays)
        if best is None or distance < best[0]:
            best = (distance, week["days"])
    days = best[1] if best else None
    if days is None:
        weeks = plan.get("weeks")
        if not isinstance(weeks, list) or not weeks or not isinstance(weeks[0], dict):
            return
        days = weeks[0].setdefault("days", [])
    index = next(
        (
            position
            for position, item in enumerate(days)
            if isinstance(item, Mapping)
            and (_day_dday(item, fight_date) is not None)
            and _day_dday(item, fight_date) < d_day
        ),
        len(days),
    )
    days.insert(index, day)


def _resolve_authoritative_day(
    plan: dict[str, Any],
    *,
    day_label: str,
    names: set[str],
    role: Mapping[str, Any],
    planning_brief: Mapping[str, Any],
) -> tuple[dict[str, Any] | None, str | None]:
    """Find the one card day for the role's countdown, repairing converter slips.

    The role's day is authoritative, so the card's day structure is repaired to
    it rather than rejecting the whole card:

    * a day split across two rows is coalesced into the first (no session lost),
    * a dated row with a blank/garbled label is matched by date and relabelled,
    * a dropped day is recreated as an empty day for the watch to land on.

    A dropped day is only recreated when the drill is nowhere else on the card.
    If the converter put it on another day, moving it would be guessing, so that
    stays unresolved and faithfulness rejects the card.
    """
    fight_date = parse_fight_date(_resolve_fight_date(dict(planning_brief)))
    d_day = int(day_label[2:])
    matches: list[tuple[dict[str, Any], dict[str, Any]]] = []
    for week in plan.get("weeks") or []:
        if not isinstance(week, dict):
            continue
        for day in week.get("days") or []:
            if isinstance(day, dict) and _day_dday(day, fight_date) == d_day:
                matches.append((week, day))

    if matches:
        _, keep = matches[0]
        for week, duplicate in matches[1:]:
            keep.setdefault("sessions", []).extend(
                session for session in duplicate.get("sessions") or [] if isinstance(session, dict)
            )
            week["days"] = [item for item in week.get("days") or [] if item is not duplicate]
        if _countdown(keep.get("countdown_label")) is None:
            keep["countdown_label"] = day_label
        return keep, None

    if _drill_on_card(plan, names):
        return None, "locked drill is on a different structured day"
    if fight_date is None:
        return None, "structured day missing and fight date unknown"
    dated = [
        (distance, day)
        for day in _days(plan)
        if (distance := _day_dday(day, fight_date)) is not None
        and _valid_phase(day.get("phase_label"))
    ]
    neighbour_phase = (
        _valid_phase(min(dated, key=lambda pair: abs(pair[0] - d_day))[1].get("phase_label"))
        if dated
        else ""
    )
    day = _rest_day(d_day, fight_date, _valid_phase(role.get("camp_phase"), neighbour_phase))
    # It will carry the zero-load watch, so it is not a rest day.
    day["day_type"] = "low"
    _insert_day(plan, day, d_day, fight_date)
    return day, None


def _stable_id(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-") or "watch"


def _duration(content: Mapping[str, Any]) -> dict[str, Any]:
    """Normalise the bank's duration onto the card's single-value shape.

    The Tactical Watch bank stores one integer; the Fight Visualisation bank
    stores a ``[min, max]`` bound. The selected duration takes precedence on
    the card; older roles without that field retain the upper-bound fallback.
    """
    raw = content.get("prescribed_duration_min") or content.get("duration_min")
    if isinstance(raw, (list, tuple)) and raw:
        value = raw[-1]
    else:
        value = raw
    return {"value": value if isinstance(value, int) else 1, "unit": "minutes"}


def _mindset_anchor(content: Mapping[str, Any]) -> dict[str, Any]:
    """The card's coaching lines, one distinct claim per slot.

    A Tactical Watch carries a real four-part mindset block. The Fight
    Visualisation bank carries a single trusted ``cue`` instead, and filling
    every slot with it printed that one sentence three times on the card
    ("Focus", "Reset" and "Coach cue" all reading "Take the space, do not chase
    it."). A single cue is a single cue: it fills the coach-cue slot and the
    others stay empty rather than repeating it or inventing generic filler.
    """
    mindset = content.get("mindset")
    mindset = mindset if isinstance(mindset, Mapping) else {}
    cue = str(content.get("cue") or "").strip()
    intent = str(mindset.get("intent") or "").strip()
    focus = str(mindset.get("focus") or "").strip()
    reset = str(mindset.get("reset") or "").strip()
    anchor = str(mindset.get("anchor") or "").strip()
    if not (intent or focus or reset or anchor):
        return {
            "intent": cue,
            "focus_cue": "",
            "reset_cue": "",
            "confidence_anchor": None,
        }
    return {
        "intent": intent or cue,
        "focus_cue": focus,
        "reset_cue": reset,
        "confidence_anchor": anchor or None,
    }


def _restore_open_plan_tactical_watches(
    plan: dict[str, Any], planning_brief: Mapping[str, Any]
) -> None:
    """Restore open-plan Tactical Watch fields from the deterministic rotation."""
    spec = planning_brief.get("open_plan_spec")
    spec = spec if isinstance(spec, Mapping) else {}
    tactical = spec.get("tactical_watch")
    tactical = tactical if isinstance(tactical, Mapping) else {}
    rotation = tactical.get("weekly_rotation")
    if not isinstance(rotation, (list, tuple)):
        return

    for entry in rotation:
        if not isinstance(entry, Mapping):
            continue
        watch = entry.get("tactical_watch")
        if not isinstance(watch, Mapping):
            continue
        name = str(entry.get("name") or watch.get("name") or "").strip()
        if not name:
            continue

        targets = [
            (session, block)
            for day in _days(plan)
            for session in day.get("sessions") or []
            if isinstance(session, dict)
            for block in session.get("blocks") or []
            if isinstance(block, dict)
            and _normalise(block.get("display_name")) == _normalise(name)
        ]
        if len(targets) != 1:
            continue

        session, block = targets[0]
        session["session_type"] = "skill"
        session["objective"] = watch.get("why")
        session["mindset_anchor"] = _mindset_anchor(watch)
        block.update(
            {
                "block_type": "mindset",
                "display_name": watch.get("name") or name,
                "duration": _duration(watch),
                "coaching_cues": [
                    str(value) for value in watch.get("instructions") or []
                ],
                "purpose": watch.get("why"),
            }
        )
        if watch.get("progress"):
            block["progression_rule"] = watch["progress"]


def _new_watch_block(
    *, day_label: str, name: str, watch: Mapping[str, Any], spec: LockedContentSpec
) -> dict[str, Any]:
    return {
        "block_id": f"locked-{_stable_id(day_label)}-{_stable_id(name)}",
        "block_type": spec.block_type,
        "display_name": name,
        "duration": _duration(watch),
        "coaching_cues": [],
        "regression_options": [],
        "substitutions": [],
    }


def _new_watch_session(
    *,
    day_label: str,
    title: str,
    name: str,
    watch: Mapping[str, Any],
    spec: LockedContentSpec,
) -> dict[str, Any]:
    return {
        "session_id": f"locked-{_stable_id(day_label)}-{spec.session_slug}",
        "session_type": spec.session_type,
        "title": title,
        "objective": str(watch.get("why") or "Review the tactical plan."),
        "completion_status": "not_started",
        "mindset_anchor": _mindset_anchor(watch),
        "blocks": [],
    }


def _is_safe_named_watch_shell(
    session: Mapping[str, Any], authoritative_names: set[str]
) -> bool:
    """Return whether a drill-titled session can safely become the Watch.

    The structured converter occasionally emits the locked drill name as its
    own otherwise-empty session. It is the same governed content, not a second
    athlete session. Only reuse or remove that shell when it has not been
    started and carries no independent blocks.
    """
    if not _is_unstarted(session):
        return False

    blocks = session.get("blocks") or []
    return isinstance(blocks, list) and all(
        isinstance(block, Mapping)
        and any(
            _is_named_variant(block.get("display_name"), name)
            for name in authoritative_names
        )
        for block in blocks
    )


def _is_unstarted(session: Mapping[str, Any]) -> bool:
    return _normalise(session.get("completion_status")) in {"", "not_started", "not started"}


def _is_generic_visualization_shell(session: Mapping[str, Any], name: str) -> bool:
    """Only remove an unstarted converter session explicitly titled as a visualisation."""
    if not _is_unstarted(session):
        return False
    title = _normalise(session.get("title"))
    if not title.startswith("fight visualisation -"):
        return False
    blocks = session.get("blocks") or []
    return isinstance(blocks, list) and all(
        isinstance(block, Mapping)
        and _normalise(block.get("block_type")) in {"", "mindset"}
        and (
            _normalise(block.get("display_name")) == "fight visualisation"
            or _is_named_variant(block.get("display_name"), name)
        )
        for block in blocks
    )


def merge_locked_structured_content(
    structured_plan: dict[str, Any], planning_brief: Any
) -> LockedMergeResult:
    """Apply locked fields on their authoritative day.

    The role's countdown day is authoritative: a split, unlabelled or dropped
    day is repaired onto it (see ``_resolve_authoritative_day``), while a drill
    the converter placed on another day stays unresolved. Inside that day,
    Stage 1 is authoritative, so harmless converter drift (renamed/moved/missing
    Tactical Watch structure) is repaired deterministically instead of rejecting
    the entire athlete card.
    """
    plan = copy.deepcopy(structured_plan)
    result = LockedMergeResult(plan=plan)
    # ``optional`` is server-owned: only a locked optional role below may set
    # it, so a model-supplied value can never make real training skippable.
    for day in _days(plan):
        for session in day.get("sessions") or []:
            if isinstance(session, dict):
                session.pop("optional", None)
    if not isinstance(planning_brief, Mapping):
        return result

    _restore_open_plan_tactical_watches(plan, planning_brief)

    for role in _locked_roles(planning_brief):
        governance = role.get("governance")
        governance = governance if isinstance(governance, Mapping) else {}
        resolved = _spec_for_role(role)
        spec, watch = resolved if resolved is not None else (None, None)
        name = str(
            governance.get("selected_drill_name")
            or (watch or {}).get("name")
            or "locked drill"
        )
        day_label = _role_day(role)
        if watch is None or spec is None:
            result.unresolved.append(
                LockedMergeIssue(day_label, name, "missing locked bank metadata")
            )
            continue
        if day_label is None:
            result.unresolved.append(LockedMergeIssue(None, name, "missing authoritative countdown label"))
            continue

        authoritative_names = {
            _normalise(governance.get("selected_drill_name")),
            _normalise(watch.get("name")),
        } - {""}
        target_day, day_issue = _resolve_authoritative_day(
            plan,
            day_label=day_label,
            names=authoritative_names,
            role=role,
            planning_brief=planning_brief,
        )
        if target_day is None:
            result.unresolved.append(LockedMergeIssue(day_label, name, day_issue or "structured day not resolved"))
            continue
        matching_days = [target_day]
        sessions = [
            session
            for session in matching_days[0].get("sessions") or []
            if isinstance(session, dict)
        ]
        # This is fixed product copy. The selected drill is the card's block,
        # never an alternate session title supplied by structured conversion.
        display_title = spec.session_title
        session_title = _normalise(display_title)
        watch_sessions = [
            session
            for session in sessions
            if _normalise(session.get("title")) == session_title
        ]
        if len(watch_sessions) > 1:
            result.unresolved.append(
                LockedMergeIssue(
                    day_label,
                    name,
                    f"{spec.session_title} session not uniquely resolved",
                )
            )
            continue

        named_watch_sessions = [
            session
            for session in sessions
            if any(
                _is_named_variant(session.get("title"), candidate, session_title=display_title)
                for candidate in authoritative_names
            )
            and _normalise(session.get("title")) != session_title
        ]
        if len(named_watch_sessions) > 1:
            result.unresolved.append(
                LockedMergeIssue(
                    day_label,
                    name,
                    f"named {spec.session_title} session not uniquely resolved",
                )
            )
            continue
        named_watch_session = named_watch_sessions[0] if named_watch_sessions else None
        reusable_named_watch = (
            named_watch_session
            if named_watch_session
            and _is_safe_named_watch_shell(named_watch_session, authoritative_names)
            else None
        )

        targets = [
            (session, block)
            for session in sessions
            if _is_unstarted(session) or any(session is watch_session for watch_session in watch_sessions)
            for block in session.get("blocks") or []
            if isinstance(block, dict)
            and any(
                _is_named_variant(block.get("display_name"), candidate)
                for candidate in authoritative_names
            )
        ]
        exact_targets = [
            pair for pair in targets
            if _normalise(pair[1].get("display_name")) in authoritative_names
        ]
        if len(exact_targets) > 1:
            result.unresolved.append(
                LockedMergeIssue(day_label, name, "locked block not uniquely resolved")
            )
            continue

        # The converter can emit both "Tactical Picture mental rehearsal" and
        # the exact bank title, or only qualified copies. Keep the exact block,
        # else the first qualified one; every other copy is the same locked
        # prescription with invented duration and cues, and the kept block is
        # overwritten from the bank below.
        emptied_alias_owners: list[dict[str, Any]] = []
        kept_targets = exact_targets or targets[:1]
        if len(targets) > len(kept_targets):
            for owner, duplicate in targets:
                if _is_unstarted(owner) and all(
                    duplicate is not kept_block for _, kept_block in kept_targets
                ):
                    owner["blocks"] = [
                        item for item in owner.get("blocks") or [] if item is not duplicate
                    ]
                    if not owner["blocks"] and _is_safe_named_watch_shell(owner, authoritative_names):
                        emptied_alias_owners.append(owner)
        targets = kept_targets

        if watch_sessions:
            session = watch_sessions[0]
        elif reusable_named_watch:
            # The converter used the locked drill name as the session title.
            # Reuse it as the canonical Watch instead of creating a twin card.
            session = reusable_named_watch
        elif targets:
            # Keep unrelated same-day work intact. Create the governed session,
            # then move only the authoritative block into it below.
            session = _new_watch_session(
                day_label=day_label,
                title=display_title,
                name=name,
                watch=watch,
                spec=spec,
            )
            matching_days[0].setdefault("sessions", []).append(session)
            sessions.append(session)
        else:
            session = _new_watch_session(
                day_label=day_label,
                title=display_title,
                name=name,
                watch=watch,
                spec=spec,
            )
            matching_days[0].setdefault("sessions", []).append(session)
            sessions.append(session)

        if targets:
            owner, block = targets[0]
            if owner is not session:
                owner["blocks"] = [item for item in owner.get("blocks") or [] if item is not block]
                session.setdefault("blocks", []).append(block)
        else:
            # A generic mindset block is not proof that it represents this
            # governed drill. Preserve ambiguous/unrelated content and append
            # the authoritative block instead of destructively repurposing it.
            block = _new_watch_block(
                day_label=day_label, name=name, watch=watch, spec=spec
            )
            session.setdefault("blocks", []).append(block)

        mindset = watch.get("mindset")
        mindset = mindset if isinstance(mindset, Mapping) else {}
        anchor = _mindset_anchor(watch)
        session["title"] = display_title
        session["objective"] = watch.get("why")
        if watch.get("optional") is True:
            # Offered, not required: the flag drives logging and adherence
            # (api.optional_sessions); the prefix tells the athlete.
            session["optional"] = True
            session["objective"] = f"Optional. {watch.get('why') or ''}".strip()
        else:
            session.pop("optional", None)
        session["mindset_anchor"] = anchor
        # ``coaching_cues`` carries the bank's instructions. The Fight
        # Visualisation bank's trusted ``cue`` (and its optional immediate
        # pre-bout version) are part of the prescription, so they ride along
        # rather than being dropped on the floor.
        coaching_cues = [str(value) for value in watch.get("instructions") or []]
        for extra_field, prefix in (("cue", "Cue"), ("pre_bout", "Pre-bout")):
            extra = str(watch.get(extra_field) or "").strip()
            if extra:
                coaching_cues.append(f"{prefix}: {extra}")
        block.update(
            {
                "display_name": watch.get("name") or governance.get("selected_drill_name"),
                "duration": _duration(watch),
                "coaching_cues": coaching_cues,
                "purpose": mindset.get("context") or watch.get("why"),
            }
        )
        # Only the Tactical Watch bank carries a progression rule. Writing a
        # null for a system that has no such concept would just blank a field.
        if watch.get("progress"):
            block["progression_rule"] = watch["progress"]

        if emptied_alias_owners:
            matching_days[0]["sessions"] = [
                item
                for item in matching_days[0].get("sessions") or []
                if item is session or all(item is not owner for owner in emptied_alias_owners)
            ]

        if spec.content_field == "fight_visualization":
            matching_days[0]["sessions"] = [
                item
                for item in matching_days[0].get("sessions") or []
                if item is session or not _is_generic_visualization_shell(item, name)
            ]

        if (
            watch_sessions
            and reusable_named_watch is not None
            and reusable_named_watch is not session
        ):
            # Remove the old converter shell only after its authoritative
            # content has been repaired on the canonical Watch. The safety
            # check above protects completed or independently populated work.
            matching_days[0]["sessions"] = [
                item
                for item in matching_days[0].get("sessions") or []
                if item is not reusable_named_watch
            ]
        result.applied.append(LockedMergeApplication(day_label, str(block["display_name"])))

    return result


def merge_planner_owned_structured_content(
    structured_plan: dict[str, Any], planning_brief: Any
) -> LockedMergeResult:
    """Carry all planner-owned session and contact truth into one final card.

    Contact reconciliation must run after locked sessions are present. Otherwise
    adding Tactical Focus can turn a contact-only day into a session day while
    leaving its contact truth stranded in the now-hidden day headline.
    """
    result = merge_locked_structured_content(structured_plan, planning_brief)

    reconcile_coach_led_sparring_days(result.plan, planning_brief)
    return result

fightcamp/weekly_schedule_view.py:
from __future__ import annotations

from datetime import date, timedelta
from typing import Any

from .normalization import clean_list as _clean_list

WEEKDAY_SHORT = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

# Canonical weekday alias table. Stage 1 and the API weekday normalizers both
# read this so a spelling accepted in one path is accepted in all of them.
WEEKDAY_ALIASES = {
    "mon": "Mon",
    "monday": "Mon",
    "tue": "Tue",
    "tues": "Tue",
    "tuesday": "Tue",
    "wed": "Wed",
    "weds": "Wed",
    "wednesday": "Wed",
    "thu": "Thu",
    "thur": "Thu",
    "thurs": "Thu",
    "thursday": "Thu",
    "fri": "Fri",
    "friday": "Fri",
    "sat": "Sat",
    "saturday": "Sat",
    "sun": "Sun",
    "sunday": "Sun",
}
_SPARRING_DAY_CLASSES = {"primary_hard", "secondary_hard", "managed_hard", "technical", "none"}
_EFFECTIVE_LOADS = {"hard", "technical", "reduced", "none"}


def normalize_weekday(value: Any) -> str | None:
    """Map a loose weekday spelling onto its canonical ``Mon``..``Sun`` short form."""
    normalized = str(value or "").strip().lower().rstrip(".")
    if not normalized:
        return None
    return WEEKDAY_ALIASES.get(normalized)


_normalize_weekday = normalize_weekday


def _empty_day(weekday: str) -> dict[str, Any]:
    return {
        "weekday": weekday,
        "d_day": None,
        "day_label": "",
        "weekday_with_label": weekday,
        "calendar_date": None,
        "is_fight_day": False,
        "is_after_fight_day": False,
        "sparring_day_class": "none",
        "effective_load": "none",
        "status": "",
        "reason": "",
        "coach_note": "",
        "reason_codes": [],
    }


def _coerce_hard_day_class(entry: dict[str, Any]) -> str:
    status = str(entry.get("status") or "").strip()
    effective_load = _coerce_effective_load(entry)
    if effective_load == "hard":
        hard_day_class = str(entry.get("hard_day_class") or entry.get("hard_sparring_class") or "").strip()
        return "secondary_hard" if hard_day_class == "secondary_hard" else "primary_hard"
    if effective_load == "reduced" or status == "deload_suggested":
        return "managed_hard"
    if effective_load == "technical" or status == "convert_to_technical_suggested":
        return "technical"
    return "none"


def _coerce_effective_load(entry: dict[str, Any]) -> str:
    effective_load = str(entry.get("effective_load") or "").strip()
    if effective_load in _EFFECTIVE_LOADS:
        return effective_load

    status = str(entry.get("status") or "").strip()

    if status == "hard_as_planned":
        return "hard"
    if status == "convert_to_technical_suggested":
        return "technical"
    if status == "deload_suggested":
        return "reduced"
    if status in {"blocked", "suppressed", "none", "no_hard_sparring_day"}:
        return "none"

    reason_codes = {str(code).strip() for code in _clean_list(entry.get("reason_codes"))}
    if reason_codes & {"d14_hard_sparring_ban", "d17_hard_sparring_ban", "final_week_sparring_cap"}:
        return "technical"

    return "none"


def _fill_hard_day(day: dict[str, Any], entry: dict[str, Any]) -> None:
    reason_codes = _clean_list(entry.get("reason_codes"))
    day.update(
        {
            "sparring_day_class": _coerce_hard_day_class(entry),
            "effective_load": _coerce_effective_load(entry),
            "status": str(entry.get("status") or "").strip(),
            "reason": str(entry.get("reason") or "").strip(),
            "coach_note": str(entry.get("coach_note") or "").strip(),
            "reason_codes": reason_codes,
        }
    )


def _fill_legacy_hard_day(day: dict[str, Any]) -> None:
    day.update(
        {
            "sparring_day_class": "primary_hard",
            "effective_load": "hard",
            "status": "hard_as_planned",
        }
    )


def _is_protected_late_week(week: dict[str, Any]) -> bool:
    final_week_sparring_cap = week.get("final_week_sparring_cap")
    if isinstance(final_week_sparring_cap, dict) and final_week_sparring_cap.get("active"):
        return True

    candidates = [
        str(week.get("phase") or "").strip().lower(),
        str(week.get("stage_key") or "").strip().lower(),
        str(week.get("payload_mode") or "").strip().lower(),
    ]

    intentional_compression = week.get("intentional_compression")
    if isinstance(intentional_compression, dict):
        candidates.extend(
            str(code).strip().lower()
            for code in _clean_list(intentional_compression.get("reason_codes"))
        )
        candidates.append(str(intentional_compression.get("reason") or "").strip().lower())
        candidates.append(str(intentional_compression.get("summary") or "").strip().lower())

    return any(
        token in candidate
        for candidate in candidates
        for token in ("bridge", "taper", "fight_week", "late_fight", "countdown")
    )


def _mark_missing_effective_sparring_plan(day: dict[str, Any]) -> None:
    day.update(
        {
            "sparring_day_class": "none",
            "effective_load": "none",
            "status": "missing_effective_sparring_plan",
            "reason": "Protected late week requires hard_sparring_plan; declared_hard_sparring_days is context only.",
            "reason_codes": ["missing_effective_sparring_plan"],
        }
    )


def _resolve_week_countdown_span(week: dict[str, Any]) -> tuple[int, int] | None:
    """Resolve a week's ``(start_d_day, end_d_day)`` from any countdown contract.

    The normal-camp pipeline ships a list ``countdown_range`` (``[start, end]``)
    while the late-fight pipeline ships a ``countdown_span`` dict
    (``{"start_day": ..., "end_day": ...}``). Both describe the same thing: the
    countdown window the week covers, from furthest-out to closest-to-fight.
    Recognising both keeps the calendar the single source of truth regardless of
    which planner built the plan, so ≤21-day (late-fight) camps render the same
    countdown spine as longer camps instead of falling back to a blank day grid.
    """
    countdown_range = week.get("countdown_range")
    if isinstance(countdown_range, list) and len(countdown_range) == 2:
        try:
            return int(countdown_range[0]), int(countdown_range[1])
        except (TypeError, ValueError):
            pass
    countdown_span = week.get("countdown_span")
    if isinstance(countdown_span, dict):
        try:
            return int(countdown_span.get("start_day")), int(countdown_span.get("end_day"))
        except (TypeError, ValueError):
            pass
    return None


def _resolve_week_anchor_d_day(week: dict[str, Any]) -> int | None:
    """The closest-to-fight D-day of a week, from either countdown contract."""
    span = _resolve_week_countdown_span(week)
    return span[1] if span is not None else None


def _build_calendar_week_from_countdown_span(
    *,
    fight_date: Any,
    start_d_day: Any,
    end_d_day: Any,
) -> list[dict[str, Any]]:
    """Build exactly the days a countdown window covers, dated off the fight date.

    Late-fight weeks are countdown *segments* (D-20..D-14, D-7..D-7, D-4..D-2, …),
    not Mon-Sun weeks. Anchoring a seven-day calendar week on the segment's end
    day pushed every earlier weekday a week late — a hard-sparring day locked at
    D-18 rendered as D-11 — and invented days the segment never covered,
    including days *after* the fight. Building straight from the span keeps the
    weekday -> D-day mapping truthful and leaves out-of-window slots blank.

    A rendered week has one slot per weekday, so a window longer than seven days
    cannot fit. Only the D-21..D-14 bridge does (exactly eight days, at
    ``days_until_fight == 21``), where the first and last day share a weekday.
    Keep the seven closest to the fight: the dropped day is then the
    plan-creation day itself, not one the athlete still has to train.
    """
    try:
        parsed_fight_date = date.fromisoformat(str(fight_date))
        start_d = int(start_d_day)
        end_d = int(end_d_day)
    except (TypeError, ValueError):
        return []
    if start_d < end_d:
        start_d, end_d = end_d, start_d
    start_d = min(start_d, end_d + len(WEEKDAY_SHORT) - 1)

    days: list[dict[str, Any]] = []
    for d_day in range(start_d, end_d - 1, -1):
        current_date = parsed_fight_date - timedelta(days=d_day)
        weekday = WEEKDAY_SHORT[current_date.weekday()]
        day_label = f"D-{d_day}" if d_day > 0 else ("D-0" if d_day == 0 else "")
        days.append(
            {
                "weekday": weekday,
                "calendar_date": current_date.isoformat(),
                "d_day": d_day,
                "day_label": day_label,
                "weekday_with_label": f"{weekday} ({day_label})" if day_label else weekday,
                "is_fight_day": d_day == 0,
                "is_after_fight_day": d_day < 0,
            }
        )
    return days


def _open_ongoing_weekly_schedule(
    planning_brief: dict[str, Any], *, week_index: int
) -> dict[str, Any] | None:
    """Map a renewable open-plan template onto the live weekly schedule.

    Open plans intentionally have no fight date, countdown calendar, or
    ``weekly_role_map``. Their deterministic source of truth is instead
    ``open_plan_spec.weekly_template`` plus the four-week development block.
    Keeping that contract here lets Today/check-ins use the same schedule
    adapter as dated camps without inventing calendar dates.
    """

    open_spec = planning_brief.get("open_plan_spec")
    if not isinstance(open_spec, dict) or open_spec.get("plan_type") != "open_ongoing_system":
        return None
    template = open_spec.get("weekly_template")
    if not isinstance(template, dict):
        return None

    development_block = open_spec.get("development_block")
    week_count = len(development_block) if isinstance(development_block, dict) else 4
    week_count = max(1, week_count)
    if week_index >= week_count:
        return None

    training_days = {
        weekday
        for value in _clean_list(template.get("training_days"))
        if (weekday := _normalize_weekday(value)) is not None
    }
    hard_sparring_days = {
        weekday
        for value in _clean_list(template.get("hard_sparring_days"))
        if (weekday := _normalize_weekday(value)) is not None
    }
    coach_owned = template.get("coach_owned_days")
    coach_owned = coach_owned if isinstance(coach_owned, dict) else {}
    support_work_days = {
        weekday
        for value in _clean_list(
            template.get("support_work_days")
            or coach_owned.get("support_work_days")
            or coach_owned.get("technical_skill_days")
        )
        if (weekday := _normalize_weekday(value)) is not None
    }
    coach_led_days = hard_sparring_days | support_work_days
    if not training_days:
        return None

    days = [_empty_day(weekday) for weekday in WEEKDAY_SHORT]
    for day in days:
        weekday = day["weekday"]
        if weekday not in training_days:
            continue
        if weekday in coach_led_days:
            is_hard = weekday in hard_sparring_days
            day.update(
                {
                    "sparring_day_class": "primary_hard" if is_hard else "technical",
                    "effective_load": "hard" if is_hard else "technical",
                    "status": "hard_as_planned" if is_hard else "coach_led_session",
                    "title": f"{weekday} {'hard sparring' if is_hard else 'technical boxing'}",
                    "reason": f"Declared {'hard sparring' if is_hard else 'technical'} contact day from the renewable weekly rhythm.",
                }
            )
        else:
            day.update(
                {
                    "effective_load": "reduced",
                    "status": "open_plan_session",
                    "title": f"{weekday} training",
                    "reason": "Scheduled training day from the renewable weekly rhythm.",
                }
            )

    selection_summary = planning_brief.get("stage1_selection_summary")
    phase = (
        str(selection_summary.get("current_phase") or "").strip()
        if isinstance(selection_summary, dict)
        else ""
    )
    return {
        "week_index": week_index,
        "week_count": week_count,
        "phase": phase,
        "projected_days_until_fight_start": None,
        "projected_days_until_fight_end": None,
        "day_label": f"Development week {week_index + 1}",
        "countdown_range": [],
        "original_countdown_range": [],
        "week_countdown_label": "",
        "week_label_with_countdown": f"Development week {week_index + 1}",
        "days": days,
    }


def extract_weekly_schedule(
    planning_brief: Any, *, week_index: int = 0, fight_date: Any = None
) -> dict[str, Any] | None:
    if not isinstance(planning_brief, dict) or week_index < 0:
        return None

    weekly_role_map = planning_brief.get("weekly_role_map")
    if not isinstance(weekly_role_map, dict):
        return _open_ongoing_weekly_schedule(planning_brief, week_index=week_index)

    weeks = weekly_role_map.get("weeks")
    if not isinstance(weeks, list) or week_index >= len(weeks):
        return None

    week = weeks[week_index]
    if not isinstance(week, dict):
        return None

    resolved_fight_date = (
        fight_date
        or planning_brief.get("fight_date")
        or (planning_brief.get("athlete_model") or {}).get("fight_date")
    )

    calendar_days = week.get("calendar_days")
    calendar_entries = [
        entry for entry in calendar_days if isinstance(entry, dict)
    ] if isinstance(calendar_days, list) else []
    # True when the entries describe one countdown window exactly, so every day
    # the week covers is already present and nothing may be extrapolated around it.
    window_scoped = False
    if not calendar_entries:
        span = _resolve_week_countdown_span(week)
        if span is not None:
            calendar_entries = _build_calendar_week_from_countdown_span(
                fight_date=resolved_fight_date,
                start_d_day=span[0],
                end_d_day=span[1],
            )
            window_scoped = bool(calendar_entries)

    if calendar_entries:
        days_by_weekday: dict[str, dict[str, Any]] = {weekday: _empty_day(weekday) for weekday in WEEKDAY_SHORT}
        anchor_weekday: str | None = None
        anchor_date: date | None = None
        anchor_d_day: int | None = None
        for entry in calendar_entries:
            weekday = _normalize_weekday(entry.get("weekday"))
            if not weekday:
                continue

            day = days_by_weekday[weekday]

            raw_d_day = entry.get("d_day")
            try:
                d_day = int(raw_d_day)
            except (TypeError, ValueError):
                d_day = None

            day.update(
                {
                    "d_day": d_day,
                    "day_label": (
                        f"D-{d_day}"
                        if d_day is not None and d_day > 0
                        else ("D-0" if d_day == 0 else "")
                    ),
                    "calendar_date": entry.get("calendar_date") or entry.get("date"),
                    "is_fight_day": bool(entry.get("is_fight_day")),
                    "is_after_fight_day": bool(entry.get("is_after_fight_day")),
                }
            )
            day["weekday_with_label"] = (
                f"{weekday} ({day['day_label']})" if day["day_label"] else weekday
            )
            if isinstance(d_day, int) and day["calendar_date"]:
                try:
                    parsed_date = date.fromisoformat(str(day["calendar_date"]))
                except (TypeError, ValueError):
                    parsed_date = None
                if parsed_date is not None and anchor_weekday is None:
                    anchor_weekday = weekday
                    anchor_date = parsed_date
                    anchor_d_day = d_day

        # Extrapolating around the anchor fills the rest of the Mon-Sun grid. That
        # is only meaningful when the entries are a partial view of a full week —
        # for a window-scoped calendar it would re-invent the very out-of-window
        # days (and post-fight days) this function exists to keep out.
        if (
            not window_scoped
            and anchor_weekday is not None
            and anchor_date is not None
            and isinstance(anchor_d_day, int)
        ):
            anchor_index = WEEKDAY_SHORT.index(anchor_weekday)
            for weekday, day in days_by_weekday.items():
                weekday_index = WEEKDAY_SHORT.index(weekday)
                day_offset = weekday_index - anchor_index
                if not day.get("calendar_date"):
                    day["calendar_date"] = (anchor_date + timedelta(days=day_offset)).isoformat()
                if day.get("d_day") is None:
                    inferred_d_day = anchor_d_day - day_offset
                    day["d_day"] = inferred_d_day
                    day["day_label"] = f"D-{inferred_d_day}" if inferred_d_day > 0 else ("D-0" if inferred_d_day == 0 else "")
                    day["weekday_with_label"] = f"{weekday} ({day['day_label']})" if day["day_label"] else weekday
                if not day.get("is_fight_day"):
                    day["is_fight_day"] = day.get("d_day") == 0
        days = [days_by_weekday[weekday] for weekday in WEEKDAY_SHORT]
    else:
        days = [_empty_day(weekday) for weekday in WEEKDAY_SHORT]

    days_by_weekday = {day["weekday"]: day for day in days}

    # A declared sparring day belongs to the week only if the week's calendar
    # actually covers that weekday. Without this a plan entry keyed by weekday
    # name is stamped onto every week that has the slot — so one declared
    # Saturday surfaced as a contact day in four different weeks, each time at a
    # different (or missing) D-day. When the week rendered no calendar at all we
    # cannot tell what it covers, so every declared day still renders as before.
    rendered_weekdays = {
        weekday for weekday, day in days_by_weekday.items() if isinstance(day.get("d_day"), int)
    }

    def _covers(weekday: str | None) -> bool:
        if not weekday or weekday not in days_by_weekday:
            return False
        return not rendered_weekdays or weekday in rendered_weekdays

    hard_sparring_plan = week.get("hard_sparring_plan")
    hard_plan_is_list = isinstance(hard_sparring_plan, list)
    hard_entries = [entry for entry in hard_sparring_plan if isinstance(entry, dict)] if hard_plan_is_list else []
    if hard_entries:
        for entry in hard_entries:
            weekday = _normalize_weekday(entry.get("day") or entry.get("scheduled_day_hint"))
            if _covers(weekday):
                _fill_hard_day(days_by_weekday[weekday], entry)
    elif _is_protected_late_week(week):
        if not hard_plan_is_list:
            for day_name in _clean_list(week.get("declared_hard_sparring_days")):
                weekday = _normalize_weekday(day_name)
                if _covers(weekday):
                    _mark_missing_effective_sparring_plan(days_by_weekday[weekday])
        else:
            # Protected late/countdown weeks must not infer sparring dose from
            # declarations or legacy effective-day lists. The structured
            # hard_sparring_plan is the only authority for hard/technical/
            # managed sparring truth in these weeks.
            pass
    else:
        for day_name in _clean_list(week.get("declared_hard_sparring_days")):
            weekday = _normalize_weekday(day_name)
            if _covers(weekday):
                _fill_legacy_hard_day(days_by_weekday[weekday])

    original_countdown_range = week.get("countdown_range")
    d_days = [day.get("d_day") for day in days if isinstance(day.get("d_day"), int)]
    countdown_range = [max(d_days), min(d_days)] if d_days else []

    week_countdown_label = ""
    if isinstance(countdown_range, list) and len(countdown_range) == 2:
        start_d, end_d = countdown_range
        if isinstance(start_d, int) and isinstance(end_d, int):
            week_countdown_label = f"D-{start_d} → D-{end_d}"

    return {
        "week_index": week_index,
        "week_count": len(weeks),
        "phase": str(week.get("phase") or "").strip(),
        "projected_days_until_fight_start": week.get("projected_days_until_fight_start"),
        "projected_days_until_fight_end": week.get("projected_days_until_fight_end"),
        "day_label": str(week.get("day_label") or "").strip(),
        "countdown_range": countdown_range,
        "original_countdown_range": (
            original_countdown_range
            if isinstance(original_countdown_range, list) and len(original_countdown_range) == 2
            else []
        ),
        "week_countdown_label": week_countdown_label,
        "week_label_with_countdown": (
            f"Week {week_index + 1} — {str(week.get('phase') or '').strip()} ({week_countdown_label})"
            if week_countdown_label
            else f"Week {week_index + 1} — {str(week.get('phase') or '').strip()}"
        ),
        "days": days,
    }

web/app/admin/page.tsx:
"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import Link from "next/link";

import { RequireAuth } from "@/components/auth-guard";
import { useAppSession } from "@/components/auth-provider";
import { EmptyState } from "@/components/empty-state";
import { AdminQueue, AdminQueueList } from "@/components/admin-queue";
import { AdminFeedbackPanel } from "@/components/admin-feedback-panel";
import { formatAppDate, formatAppDateTime } from "@/lib/date-format";
import {
  adminArchivePlan,
  rejectAdminGenerationJob,
  approveAdminAthlete,
  approveAndResumeGenerationFromJob,
  backfillStructuredPlans,
  bulkPermanentlyDeleteArchivedPlans,
  cancelAdminGenerationJob,
  listAdminActiveGenerationJobs,
  listAdminAthletes,
  listAdminPlans,
  listAdminReviewPlans,
  listAdminReviews,
  listAdminTriageGenerationJobs,
  resolveAdminReview,
} from "@/lib/api";
import {
  PROFILE_REFRESH_FAILED_BANNER_BODY,
  PROFILE_REFRESH_FAILED_BANNER_TITLE,
  hasProfileRefreshFailedWarning,
} from "@/lib/profile-refresh-warning";
import {
  PROFILE_UNAVAILABLE_ROW_LABEL,
  isProfileServiceUnavailableMessage,
  nonProfileSectionError,
  summarizeProfileWarning,
} from "@/lib/admin-profile-warning";
import type {
  AdminAthleteRecord,
  AdminGenerationJobDiagnostic,
  AdminPlanSummary,
  AdminReviewRecord,
} from "@/lib/types";

function getPlanDisplayName(plan: { plan_name?: string | null; full_name?: string | null; athlete_email: string }) {
  return plan.plan_name?.trim() || plan.full_name || plan.athlete_email;
}

function getErrorMessage(error: unknown, fallback: string): string {
  return error instanceof Error ? error.message : fallback;
}

function formatDateTime(value: string | null | undefined): string {
  if (!value) {
    return "Not recorded";
  }
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "Not recorded" : formatAppDateTime(value);
}

function normalizeForSearch(...parts: unknown[]): string {
  return parts
    .flatMap((part) => (Array.isArray(part) ? part : [part]))
    .filter((part): part is string | number => typeof part === "string" || typeof part === "number")
    .join(" ")
    .toLowerCase();
}

function joinOrDash(values: string[] | null | undefined): string {
  const joined = Array.isArray(values)
    ? values.filter((value) => value?.trim()).join(", ")
    : "";
  return joined || "None logged";
}

function getJobDisplayName(job: AdminGenerationJobDiagnostic): string {
  return (
    job.athlete_full_name?.trim() ||
    job.request_payload_summary.athlete_name?.trim() ||
    job.athlete_email?.trim() ||
    "Unassigned athlete"
  );
}

function formatJobSource(source?: string | null): string {
  const label = (source || "").trim().replace(/_/g, " ");
  return label || "unknown source";
}

function getJobStatusLabel(job: AdminGenerationJobDiagnostic): string {
  if (job.is_stale) {
    return "Stale";
  }
  return job.status === "queued" ? "Queued" : "Running";
}

function getActiveJobProgress(job: AdminGenerationJobDiagnostic): number {
  if (job.is_stale) {
    return 88;
  }
  return job.status === "running" ? 64 : 28;
}

function countActiveJobStates(jobs: AdminGenerationJobDiagnostic[]) {
  return jobs.reduce(
    (counts, job) => {
      if (job.is_stale) {
        counts.stale += 1;
      } else if (job.status === "running") {
        counts.running += 1;
      } else {
        counts.queued += 1;
      }
      return counts;
    },
    { queued: 0, running: 0, stale: 0 },
  );
}

function isArchivedPlan(plan: AdminPlanSummary): boolean {
  return (plan.status || "").trim().toLowerCase() === "archived";
}

function ProfileUnavailableNote({ unavailable }: { unavailable?: boolean }) {
  if (!unavailable) {
    return null;
  }
  return <p className="muted admin-profile-unavailable-note">{PROFILE_UNAVAILABLE_ROW_LABEL}</p>;
}

function ProfileRefreshWarningBanner({ job }: { job: AdminGenerationJobDiagnostic }) {
  if (!hasProfileRefreshFailedWarning(job)) {
    return null;
  }

  return (
    <div className="admin-profile-refresh-warning" role="alert">
      <strong>{PROFILE_REFRESH_FAILED_BANNER_TITLE}</strong>
      <p>{PROFILE_REFRESH_FAILED_BANNER_BODY}</p>
    </div>
  );
}

const DIRECTORY_PAGE_SIZE = 10;
const ACTIVE_JOBS_POLL_INTERVAL_MS = 8000;
const SEARCH_DEBOUNCE_MS = 300;

export default function AdminPage() {
  const { isReady, isMeHydrated, session, me } = useAppSession();
  const [athletes, setAthletes] = useState<AdminAthleteRecord[]>([]);
  const [plans, setPlans] = useState<AdminPlanSummary[]>([]);
  const [activeJobs, setActiveJobs] = useState<AdminGenerationJobDiagnostic[]>([]);
  const [triageJobs, setTriageJobs] = useState<AdminGenerationJobDiagnostic[]>([]);
  const [reviewPlans, setReviewPlans] = useState<AdminPlanSummary[]>([]);
  const [reviewPlansWarning, setReviewPlansWarning] = useState<string | null>(null);
  const [attentionReviews, setAttentionReviews] = useState<AdminReviewRecord[]>([]);
  const [attentionWarning, setAttentionWarning] = useState<string | null>(null);
  const [resolvingReviewId, setResolvingReviewId] = useState<string | null>(null);
  const [approvingAthleteId, setApprovingAthleteId] = useState<string | null>(null);
  const [isDirectoryLoading, setIsDirectoryLoading] = useState(true);
  const [isJobsLoading, setIsJobsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [activeWarning, setActiveWarning] = useState<string | null>(null);
  const [triageWarning, setTriageWarning] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchNeedle, setSearchNeedle] = useState("");
  const [athletesOffset, setAthletesOffset] = useState(0);
  const [plansOffset, setPlansOffset] = useState(0);
  const [athletesHasMore, setAthletesHasMore] = useState(false);
  const [plansHasMore, setPlansHasMore] = useState(false);
  const [rejectingBuildId, setRejectingBuildId] = useState<string | null>(null);
  const [resumingJobId, setResumingJobId] = useState<string | null>(null);
  const [cancellingJobId, setCancellingJobId] = useState<string | null>(null);
  const [selectedArchivedPlanIds, setSelectedArchivedPlanIds] = useState<string[]>([]);
  const [bulkDeletingPlans, setBulkDeletingPlans] = useState(false);

  useEffect(() => {
    setSelectedArchivedPlanIds([]);
  }, [plansOffset, searchNeedle]);
  const [lastCheckedAt, setLastCheckedAt] = useState<string | null>(null);
  const [backfillPending, setBackfillPending] = useState(false);

  const token = session?.access_token;
  const isAdminReady =
    isReady && isMeHydrated && Boolean(token) && me?.profile?.role === "admin";
  const isLoading = isDirectoryLoading || isJobsLoading;

  const handleRetry = useCallback(() => {
    setMessage(null);
    setReloadKey((value) => value + 1);
  }, []);

  // Debounce the raw search box into the value we send to the server so that
  // each keystroke does not fire a paginated query against the API. Resetting
  // the page offsets in the same batched update (rather than a separate effect
  // keyed on searchNeedle) keeps a search change to a single directory fetch:
  // splitting them would fire one request with the stale offset and another at
  // page 1, racing each other for which result lands last.
  useEffect(() => {
    const handle = setTimeout(() => {
      setSearchNeedle(searchQuery.trim().toLowerCase());
      setAthletesOffset(0);
      setPlansOffset(0);
    }, SEARCH_DEBOUNCE_MS);
    return () => clearTimeout(handle);
  }, [searchQuery]);

  const filteredActiveJobs = useMemo(() => {
    if (!searchNeedle) return activeJobs;
    return activeJobs.filter((job) =>
      normalizeForSearch(
        getJobDisplayName(job),
        job.athlete_email,
        job.athlete_id,
        job.status,
        job.source,
        job.stage2_status,
        job.request_payload_summary?.athlete_name,
        job.request_payload_summary?.fight_date,
        job.request_payload_summary?.fight_format,
        job.request_payload_summary?.goals,
        job.request_payload_summary?.injuries,
      ).includes(searchNeedle),
    );
  }, [activeJobs, searchNeedle]);

  const activeAthleteCount = useMemo(
    () => new Set(activeJobs.map((job) => job.athlete_id).filter(Boolean)).size,
    [activeJobs],
  );

  const activeJobStates = useMemo(() => countActiveJobStates(activeJobs), [activeJobs]);

  const archivedPlanIds = useMemo(
    () => plans.filter(isArchivedPlan).map((plan) => plan.plan_id),
    [plans],
  );
  const archivedPlanIdSet = useMemo(() => new Set(archivedPlanIds), [archivedPlanIds]);
  const selectedArchivedIds = useMemo(
    () => selectedArchivedPlanIds.filter((planId) => archivedPlanIdSet.has(planId)),
    [archivedPlanIdSet, selectedArchivedPlanIds],
  );
  const selectedArchivedCount = selectedArchivedIds.length;
  const allArchivedPlansSelected =
    archivedPlanIds.length > 0 && selectedArchivedCount === archivedPlanIds.length;

  const triageAthleteCount = useMemo(
    () => new Set(triageJobs.map((job) => job.athlete_id).filter(Boolean)).size,
    [triageJobs],
  );

  const lastCheckedLabel = lastCheckedAt
    ? `Live jobs checked ${formatDateTime(lastCheckedAt)}`
    : isJobsLoading
      ? "Checking live generation jobs"
      : "Not checked yet";

  // Directory data (athletes + plans). Filtering and pagination happen on the
  // server so the dashboard scales past a few dozen records: the search term
  // and page offsets are query parameters, not client-side array work.
  useEffect(() => {
    if (!isAdminReady || !token) {
      if (isReady && isMeHydrated) {
        setIsDirectoryLoading(false);
      }
      return;
    }

    let active = true;
    setIsDirectoryLoading(true);
    setError(null);

    const loadDirectory = async () => {
      const loadErrors: string[] = [];

      try {
        try {
          const athletesResult = await listAdminAthletes(token, {
            q: searchNeedle,
            limit: DIRECTORY_PAGE_SIZE,
            offset: athletesOffset,
          });
          if (!active) return;
          setAthletes(athletesResult);
          setAthletesHasMore(athletesResult.length === DIRECTORY_PAGE_SIZE);
        } catch (athletesError) {
          if (!active) return;
          loadErrors.push(getErrorMessage(athletesError, "Unable to load athlete accounts."));
        }

        try {
          const plansResult = await listAdminPlans(token, {
            q: searchNeedle,
            limit: DIRECTORY_PAGE_SIZE,
            offset: plansOffset,
          });
          if (!active) return;
          setPlans(plansResult);
          setPlansHasMore(plansResult.length === DIRECTORY_PAGE_SIZE);
        } catch (plansError) {
          if (!active) return;
          loadErrors.push(getErrorMessage(plansError, "Unable to load plan history."));
        }

        setError(loadErrors.length ? loadErrors.join(" ") : null);
      } catch (adminError) {
        if (!active) return;
        setError(adminError instanceof Error ? adminError.message : "Unable to load admin data.");
      } finally {
        if (active) {
          setIsDirectoryLoading(false);
        }
      }
    };

    void loadDirectory();

    return () => {
      active = false;
    };
  }, [
    isAdminReady,
    isReady,
    isMeHydrated,
    me?.profile.role,
    token,
    searchNeedle,
    athletesOffset,
    plansOffset,
    reloadKey,
  ]);

  // Live generation jobs (active + triage). These are bounded queues that move
  // on their own, so we poll them on a fixed interval instead of reloading the
  // whole dashboard. Athlete and plan directories stay put while jobs refresh.
  useEffect(() => {
    if (!isAdminReady || !token) {
      if (isReady && isMeHydrated) {
        setIsJobsLoading(false);
      }
      return;
    }

    let active = true;
    let jobLoadInFlight = false;

    const loadJobs = async (isInitial: boolean) => {
      if (jobLoadInFlight) return;
      jobLoadInFlight = true;
      if (isInitial) {
        setIsJobsLoading(true);
      }

      try {
        try {
          const activeResult = await listAdminActiveGenerationJobs(token);
          if (!active) return;
          setActiveJobs(activeResult);
          setActiveWarning(null);
        } catch (activeError) {
          if (!active) return;
          // On a transient poll failure keep the last good snapshot rather
          // than blanking the live monitor; only clear it on first load.
          if (isInitial) setActiveJobs([]);
          setActiveWarning(getErrorMessage(activeError, "Unable to load active generation jobs."));
        }

        try {
          const triageResult = await listAdminTriageGenerationJobs(token);
          if (!active) return;
          setTriageJobs(triageResult);
          setTriageWarning(null);
        } catch (triageError) {
          if (!active) return;
          if (isInitial) setTriageJobs([]);
          setTriageWarning(getErrorMessage(triageError, "Unable to load suspended triage jobs."));
        }

        try {
          const reviewPlansResult = await listAdminReviewPlans(token);
          if (!active) return;
          setReviewPlans(reviewPlansResult);
          setReviewPlansWarning(null);
        } catch (reviewPlansError) {
          if (!active) return;
          if (isInitial) setReviewPlans([]);
          setReviewPlansWarning(getErrorMessage(reviewPlansError, "Unable to load held/review plans."));
        }

        try {
          const reviewsResult = await listAdminReviews(token, "pending");
          if (!active) return;
          setAttentionReviews(reviewsResult);
          setAttentionWarning(null);
        } catch (reviewsError) {
          if (!active) return;
          if (isInitial) setAttentionReviews([]);
          setAttentionWarning(getErrorMessage(reviewsError, "Unable to load the athlete attention queue."));
        }

        setLastCheckedAt(new Date().toISOString());
      } finally {
        jobLoadInFlight = false;
        if (active && isInitial) {
          setIsJobsLoading(false);
        }
      }
    };

    void loadJobs(true);
    const timer = setInterval(() => void loadJobs(false), ACTIVE_JOBS_POLL_INTERVAL_MS);

    return () => {
      active = false;
      clearInterval(timer);
    };
  }, [isAdminReady, isReady, isMeHydrated, me?.profile.role, token, reloadKey]);

  const athletesPage = Math.floor(athletesOffset / DIRECTORY_PAGE_SIZE) + 1;
  const plansPage = Math.floor(plansOffset / DIRECTORY_PAGE_SIZE) + 1;

  const goToAthletesPage = useCallback((delta: number) => {
    setAthletesOffset((value) => Math.max(0, value + delta * DIRECTORY_PAGE_SIZE));
  }, []);

  const goToPlansPage = useCallback((delta: number) => {
    setPlansOffset((value) => Math.max(0, value + delta * DIRECTORY_PAGE_SIZE));
  }, []);

  async function handleResolveReview(reviewId: string) {
    if (!session?.access_token || resolvingReviewId) return;
    setResolvingReviewId(reviewId);
    setError(null);
    setMessage(null);
    try {
      await resolveAdminReview(session.access_token, reviewId, {
        status: "resolved",
        resolution_notes: "reviewed from admin dashboard",
      });
      setAttentionReviews((reviews) => reviews.filter((review) => review.id !== reviewId));
      setMessage("Review resolved.");
    } catch (resolveError) {
      setError(resolveError instanceof Error ? resolveError.message : "Failed to resolve review.");
    } finally {
      setResolvingReviewId(null);
    }
  }

  async function handleApproveAthlete(athleteId: string) {
    if (!session?.access_token || approvingAthleteId) return;
    setApprovingAthleteId(athleteId);
    setError(null);
    setMessage(null);
    try {
      const approved = await approveAdminAthlete(session.access_token, athleteId);
      setAthletes((current) =>
        current.map((athlete) => athlete.athlete_id === athleteId ? approved : athlete),
      );
      setMessage(`${approved.full_name || approved.email} approved.`);
    } catch (approveError) {
      setError(approveError instanceof Error ? approveError.message : "Failed to approve account.");
    } finally {
      setApprovingAthleteId(null);
    }
  }

  async function handleBackfillStructuredPlans() {
    if (!session?.access_token || backfillPending) return;
    setBackfillPending(true);
    setError(null);
    setMessage(null);
    try {
      const result = await backfillStructuredPlans(session.access_token);
      setMessage(
        result.queued > 0
          ? `Queued ${result.queued} plan${result.queued === 1 ? "" : "s"} for structured-card backfill. Cards appear as each conversion finishes.`
          : "No plans need a structured-card backfill. Every displayable plan already has one.",
      );
    } catch (backfillError) {
      setError(
        backfillError instanceof Error
          ? backfillError.message
          : "Failed to queue the structured-card backfill.",
      );
    } finally {
      setBackfillPending(false);
    }
  }

  async function handleApproveAndResumeJob(jobId: string) {
    if (!session?.access_token || resumingJobId || rejectingBuildId) return;
    setResumingJobId(jobId);
    setError(null);
    setMessage(null);
    try {
      await approveAndResumeGenerationFromJob(
        session.access_token,
        jobId,
        { reason: "admin reviewed and approved from dashboard" },
      );
      setTriageJobs((jobs) => jobs.filter((job) => job.job_id !== jobId));
      setMessage("Resume queued.");
      setReloadKey((value) => value + 1);
    } catch (resumeError) {
      setError(resumeError instanceof Error ? resumeError.message : "Failed to approve and resume generation.");
    } finally {
      setResumingJobId(null);
    }
  }

  async function handleRejectBuild(id: string, name: string, kind: "job" | "plan") {
    if (!session?.access_token || rejectingBuildId || resumingJobId) return;
    if (!window.confirm(`Reject build for ${name}? ${kind === "plan" ? "The plan will be archived and kept in history." : "This closes the suspended build without generating a plan."}`)) return;
    setRejectingBuildId(id);
    setError(null);
    setMessage(null);
    try {
      if (kind === "job") {
        await rejectAdminGenerationJob(session.access_token, id);
        setTriageJobs((jobs) => jobs.filter((job) => job.job_id !== id));
      } else {
        await adminArchivePlan(session.access_token, id);
        setReviewPlans((items) => items.filter((plan) => plan.plan_id !== id));
      }
      setMessage(kind === "plan" ? "Build rejected. Plan archived in history." : "Build rejected.");
      setReloadKey((value) => value + 1);
    } catch (rejectError) {
      setError(getErrorMessage(rejectError, "Failed to reject build."));
    } finally {
      setRejectingBuildId(null);
    }
  }

  async function handleCancelGenerationJob(job: AdminGenerationJobDiagnostic) {
    if (!session?.access_token || cancellingJobId) return;
    const confirmed = window.confirm(
      `Cancel generation for ${getJobDisplayName(job)}? This stops the active job so cleanup can continue.`,
    );
    if (!confirmed) return;
    setCancellingJobId(job.job_id);
    setError(null);
    setMessage(null);
    try {
      await cancelAdminGenerationJob(session.access_token, job.job_id);
      setActiveJobs((jobs) => jobs.filter((item) => item.job_id !== job.job_id));
      setMessage("Generation cancelled. You can archive or delete the related plan now.");
      setReloadKey((value) => value + 1);
    } catch (cancelError) {
      setError(cancelError instanceof Error ? cancelError.message : "Failed to cancel generation.");
    } finally {
      setCancellingJobId(null);
    }
  }

  function toggleArchivedPlan(planId: string) {
    setMessage(null);
    setError(null);
    setSelectedArchivedPlanIds((current) =>
      current.includes(planId) ? current.filter((id) => id !== planId) : [...current, planId],
    );
  }

  function toggleAllArchivedPlans() {
    setMessage(null);
    setError(null);
    setSelectedArchivedPlanIds(allArchivedPlansSelected ? [] : [...archivedPlanIds]);
  }

  async function handleBulkDeleteArchivedPlans() {
    if (!session?.access_token || selectedArchivedCount === 0 || bulkDeletingPlans) return;
    const confirmed = window.confirm(
      `Permanently delete ${selectedArchivedCount} archived plan${selectedArchivedCount === 1 ? "" : "s"}? This cannot be undone.`,
    );
    if (!confirmed) return;
    setBulkDeletingPlans(true);
    setError(null);
    setMessage(null);
    try {
      const result = await bulkPermanentlyDeleteArchivedPlans(session.access_token, selectedArchivedIds);
      const deleted = new Set(result.deleted);
      setPlans((current) => current.filter((plan) => !deleted.has(plan.plan_id)));
      setSelectedArchivedPlanIds((current) => current.filter((planId) => !deleted.has(planId)));
      setMessage(
        `Deleted ${result.deleted_count} archived plan${result.deleted_count === 1 ? "" : "s"}.` +
          (result.skipped_count ? ` ${result.skipped_count} skipped.` : ""),
      );
    } catch (deleteError) {
      setError(deleteError instanceof Error ? deleteError.message : "Unable to delete archived plans.");
    } finally {
      setBulkDeletingPlans(false);
    }
  }

  // Collapse every profile-service signal across the dashboard into a single
  // compact banner instead of repeating a giant error block per section. The
  // queues themselves stay rendered with whatever athlete detail is available.
  const rowsDegraded =
    activeJobs.some((job) => job.profile_unavailable) ||
    triageJobs.some((job) => job.profile_unavailable) ||
    reviewPlans.some((plan) => plan.profile_unavailable);
  const profileWarning = summarizeProfileWarning({
    sectionErrors: [error, activeWarning, triageWarning, reviewPlansWarning, attentionWarning],
    rowsDegraded,
  });

  // Hide profile-service errors from per-section blocks (the compact banner
  // covers them) while still surfacing genuine, unrelated queue failures.
  const directoryDisplayError = nonProfileSectionError(error);
  const activeDisplayWarning = nonProfileSectionError(activeWarning);
  const triageDisplayWarning = nonProfileSectionError(triageWarning);
  const reviewPlansDisplayWarning = nonProfileSectionError(reviewPlansWarning);
  const attentionDisplayWarning = nonProfileSectionError(attentionWarning);
  const activeProfileError = isProfileServiceUnavailableMessage(activeWarning);
  const triageProfileError = isProfileServiceUnavailableMessage(triageWarning);
  const hasQueueWarning = Boolean(triageWarning || reviewPlansWarning || attentionWarning);
  const adminActionCount = triageJobs.length + reviewPlans.length + attentionReviews.length;
  const adminActionLabel = isJobsLoading
    ? "Scanning live queues"
    : hasQueueWarning
      ? "Queue status unavailable"
      : adminActionCount > 0
        ? `${adminActionCount} admin decision${adminActionCount === 1 ? "" : "s"} open`
        : "Queues clear";
  const reviewPlansProfileError = isProfileServiceUnavailableMessage(reviewPlansWarning);
  const attentionProfileError = isProfileServiceUnavailableMessage(attentionWarning);

  return (
    <RequireAuth adminOnly>
      <section className="panel admin-dashboard-panel">
        <div className="section-heading admin-dashboard-heading">
          <div className="admin-dashboard-copy">
            <p className="kicker">Admin</p>
            <h1>Fight camp control room</h1>
            <p className="muted">Live generation queues, athlete risk signals, and plan-review decisions in one operator view.</p>
            <div className="admin-priority-rail" role="region" aria-label="Admin priority status">
              <span className="admin-priority-label">{adminActionLabel}</span>
              <span>{lastCheckedLabel}</span>
            </div>
          </div>
          <div className="admin-summary-grid" aria-label="Admin dashboard summary">
            <article className="status-card admin-summary-card" data-tone={activeJobs.length > 0 ? "active" : "neutral"}>
              <p className="status-label">Generating now</p>
              <h2 className="plan-summary-title">{isJobsLoading ? "-" : activeJobs.length}</h2>
              <p className="muted">
                {isJobsLoading
                  ? "Checking jobs."
                  : `${activeAthleteCount} athlete${activeAthleteCount === 1 ? "" : "s"} in progress.`}
              </p>
            </article>
            <article className="status-card admin-summary-card" data-tone={triageJobs.length > 0 ? "danger" : "neutral"}>
              <p className="status-label">Triage queue</p>
              <h2 className="plan-summary-title">{isJobsLoading ? "-" : triageJobs.length}</h2>
              <p className="muted">
                {isJobsLoading
                  ? "Checking reviews."
                  : `${triageAthleteCount} athlete${triageAthleteCount === 1 ? "" : "s"} awaiting a decision.`}
              </p>
            </article>
            <article className="status-card admin-summary-card" data-tone={attentionReviews.length > 0 ? "danger" : "neutral"}>
              <p className="status-label">Needs attention</p>
              <h2 className="plan-summary-title">
                {isJobsLoading ? "-" : attentionReviews.length}
              </h2>
              <p className="muted">{isJobsLoading ? "Checking reviews." : attentionReviews.length ? "Athlete flags open." : "No flags open."}</p>
            </article>
            <article className="status-card admin-summary-card" data-tone="neutral">
              <p className="status-label">Athletes</p>
              <h2 className="plan-summary-title">{isDirectoryLoading ? "-" : athletes.length}</h2>
              <p className="muted">{searchNeedle ? "Matches on this page." : "Accounts on this page."}</p>
            </article>
            <article className="status-card admin-summary-card" data-tone={reviewPlans.length > 0 ? "danger" : "neutral"}>
              <p className="status-label">Held plans</p>
              <h2 className="plan-summary-title">{isJobsLoading ? "-" : reviewPlans.length}</h2>
              <p className="muted">{isJobsLoading ? "Checking reviews." : "Awaiting a decision."}</p>
            </article>
          </div>
        </div>

        {profileWarning.show ? (
          <div className="warning-banner admin-profile-warning-banner" role="status">
            <div className="admin-profile-warning-copy">
              <strong>{profileWarning.title}</strong>
              <span>{profileWarning.body}</span>
              {profileWarning.requestId ? (
                <span className="muted admin-profile-warning-request">
                  Latest request id: {profileWarning.requestId}
                </span>
              ) : null}
            </div>
            <button
              type="button"
              className="ghost-button"
              onClick={handleRetry}
              disabled={isLoading}
            >
              {isLoading ? "Retrying..." : "Retry"}
            </button>
          </div>
        ) : null}

        {directoryDisplayError ? (
          <div className="error-banner" role="alert">
            <span>{directoryDisplayError}</span>
            <button
              type="button"
              className="ghost-button"
              onClick={handleRetry}
              disabled={isLoading}
            >
              {isLoading ? "Retrying..." : "Try again"}
            </button>
          </div>
        ) : null}

        {message ? <div className="success-banner">{message}</div> : null}

        <div className="admin-toolbar">
          <div className="field admin-search-field">
            <label htmlFor="adminSearch">Search support records</label>
            <input
              id="adminSearch"
              type="search"
              value={searchQuery}
              onChange={(event) => setSearchQuery(event.target.value)}
              placeholder="Name, email, username, status"
            />
          </div>
          <button
            type="button"
            className="ghost-button admin-refresh-button"
            onClick={handleRetry}
            disabled={isLoading}
          >
            {isLoading ? "Refreshing..." : "Refresh"}
          </button>
          <button
            type="button"
            className="ghost-button admin-backfill-button"
            onClick={() => void handleBackfillStructuredPlans()}
            disabled={backfillPending}
            title="Re-run structured-card conversion for legacy plans that still fall back to plain text"
          >
            {backfillPending ? "Backfilling..." : "Backfill structured cards"}
          </button>
        </div>


        <AdminQueue className="admin-active-panel" header={(
          <div className="form-section-header">
            <div>
              <p className="kicker">Live generation monitor</p>
              <h2>Plans currently being generated</h2>
              <p className="muted admin-panel-subtext">{lastCheckedLabel}</p>
            </div>
            <span className="badge">
              {isJobsLoading
                ? "Checking"
                : searchNeedle
                  ? `${filteredActiveJobs.length}/${activeJobs.length} active`
                  : `${activeJobs.length} active`}
            </span>
          </div>
        )}>

          {!isJobsLoading ? (
            <div className="admin-active-summary" aria-label="Active generation states">
              <span>Running {activeJobStates.running}</span>
              <span>Queued {activeJobStates.queued}</span>
              <span>Stale {activeJobStates.stale}</span>
            </div>
          ) : null}

          {isJobsLoading ? (
            <div className="support-panel">
              <p className="muted">Loading active generation jobs...</p>
            </div>
          ) : activeDisplayWarning ? (
            <div className="support-panel">
              <p className="error-text">{activeDisplayWarning}</p>
              <p className="muted">Triage, athlete, and plan history can still be reviewed while this feed retries.</p>
            </div>
          ) : activeProfileError && activeJobs.length === 0 ? (
            <div className="support-panel">
              <p className="muted">Live generation details are limited while the profile service recovers. See the notice above.</p>
            </div>
          ) : activeJobs.length === 0 ? (
            <div className="support-panel support-panel-success">
              <p className="kicker">Idle</p>
              <h3 className="form-section-title">No plans are generating right now.</h3>
              <p className="muted">Queued and running jobs will appear here with athlete, timing, and plan context.</p>
            </div>
          ) : filteredActiveJobs.length === 0 ? (
            <div className="support-panel">
              <p className="muted">No active generation jobs match this search.</p>
            </div>
          ) : (
            <AdminQueueList className="admin-active-list" label="Live builds">
              {filteredActiveJobs.map((job) => (
                <article
                  key={job.job_id}
                  className={`admin-active-row ${job.is_stale ? "admin-active-row-stale" : ""}`.trim()}
                >
                  <div className="admin-active-row-main">
                    <div>
                      <h3 className="plan-card-title">{getJobDisplayName(job)}</h3>
                      <p className="muted">{job.athlete_email || job.athlete_id || "No athlete email"}</p>
                      <ProfileUnavailableNote unavailable={job.profile_unavailable} />
                    </div>
                    <span className="badge">{getJobStatusLabel(job)}</span>
                  </div>
                  <div className="admin-active-progress" aria-label={`${getJobStatusLabel(job)} progress`}>
                    <span style={{ width: `${getActiveJobProgress(job)}%` }} />
                  </div>
                  <ProfileRefreshWarningBanner job={job} />
                  <details className="admin-build-details">
                    <summary>Build details</summary>
                  <div className="admin-job-meta">
                    <span>Created {formatDateTime(job.created_at)}</span>
                    <span>Started {formatDateTime(job.started_at)}</span>
                    <span>Heartbeat {formatDateTime(job.heartbeat_at)}</span>
                    <span>Source {formatJobSource(job.source)}</span>
                  </div>
                  <div className="admin-job-summary">
                    {job.is_stale ? <p className="error-text">{job.stale_reason || "This generation has stopped heartbeating."}</p> : null}
                    <p className="muted">Fight date: {job.request_payload_summary?.fight_date ? formatAppDate(job.request_payload_summary.fight_date) : "Not set"}</p>
                    <p className="muted">Format: {job.request_payload_summary?.fight_format || "Not set"}</p>
                    <p className="muted">Goals: {joinOrDash(job.request_payload_summary?.goals)}</p>
                  </div>
                  </details>
                  <div className="plan-card-actions">
                    {job.athlete_id ? (
                      <Link href={`/admin/athletes/${job.athlete_id}`} className="ghost-button">
                        Open athlete
                      </Link>
                    ) : null}
                    {job.plan_id ? (
                      <Link href={`/plans/${job.plan_id}`} className="ghost-button">
                        Open plan
                      </Link>
                    ) : null}
                    <button
                      type="button"
                      className="ghost-button danger-button"
                      onClick={() => void handleCancelGenerationJob(job)}
                      disabled={cancellingJobId !== null}
                    >
                      {cancellingJobId === job.job_id ? "Cancelling..." : "Cancel generation"}
                    </button>
                  </div>
                </article>
              ))}
            </AdminQueueList>
          )}
        </AdminQueue>

        <AdminQueue className="admin-triage-panel" header={(
          <div className="form-section-header">
            <div>
              <p className="kicker">Triage resume queue</p>
              <h2>Suspended generations</h2>
            </div>
            <span className="badge">{isJobsLoading ? "Checking" : `${triageJobs.length} open`}</span>
          </div>
        )}>

          {isJobsLoading ? (
            <div className="support-panel">
              <p className="muted">Loading protected triage jobs...</p>
            </div>
          ) : triageDisplayWarning ? (
            <div className="support-panel">
              <p className="error-text">{triageDisplayWarning}</p>
              <p className="muted">Athlete accounts and plan history can still be reviewed while the queue retries.</p>
            </div>
          ) : triageProfileError && triageJobs.length === 0 ? (
            <div className="support-panel">
              <p className="muted">Triage details are limited while the profile service recovers. See the notice above.</p>
            </div>
          ) : triageJobs.length === 0 ? (
            <div className="support-panel support-panel-success">
              <p className="kicker">Clear</p>
              <h3 className="form-section-title">No suspended triage generations need approval.</h3>
              <p className="muted">New protected triage outcomes will appear here even when no plan row was created.</p>
            </div>
          ) : (
            <AdminQueueList className="plans-grid admin-queue-grid" label="Suspended builds">
              {triageJobs.map((job) => (
                <article key={job.job_id} className="plan-card admin-triage-card">
                  <div className="plan-card-header">
                    <div>
                      <h3 className="plan-card-title">{getJobDisplayName(job)}</h3>
                      <p className="muted">{job.athlete_email || job.athlete_id || "No athlete email"}</p>
                      <ProfileUnavailableNote unavailable={job.profile_unavailable} />
                    </div>
                    <span className="badge">Needs resume</span>
                  </div>
                  <p className="muted">
                    Review the athlete&apos;s intake before approving this build.
                  </p>
                  <ProfileRefreshWarningBanner job={job} />
                  <details className="admin-build-details">
                    <summary>Build details</summary>
                  <div className="admin-job-meta">
                    <span>Created {formatDateTime(job.created_at)}</span>
                    <span>Source {job.source || "unknown"}</span>
                    <span>Job {job.job_id}</span>
                  </div>
                  <div className="admin-job-summary">
                    <p className="muted">Fight date: {job.request_payload_summary.fight_date ? formatAppDate(job.request_payload_summary.fight_date) : "Not set"}</p>
                    <p className="muted">Goals: {joinOrDash(job.request_payload_summary.goals)}</p>
                    <p className="muted">Injuries: {joinOrDash(job.request_payload_summary.injuries)}</p>
                  </div>
                  </details>
                  <div className="plan-card-actions">
                    {job.athlete_id ? (
                      <Link href={`/admin/athletes/${job.athlete_id}`} className="ghost-button">
                        Open athlete
                      </Link>
                    ) : null}
                    <button type="button" className="ghost-button danger-button"
                      onClick={() => void handleRejectBuild(job.job_id, getJobDisplayName(job), "job")}
                      disabled={rejectingBuildId !== null || resumingJobId !== null}>
                      {rejectingBuildId === job.job_id ? "Rejecting..." : "Reject build"}
                    </button>
                    <button
                      type="button"
                      className="cta"
                      onClick={() => void handleApproveAndResumeJob(job.job_id)}
                      disabled={resumingJobId !== null || rejectingBuildId !== null}
                    >
                      {resumingJobId === job.job_id ? "Approving..." : "Approve & Resume"}
                    </button>
                  </div>
                </article>
              ))}
            </AdminQueueList>
          )}
        </AdminQueue>

        <AdminQueue className="admin-review-plans-panel" header={(
          <div className="form-section-header">
            <div>
              <p className="kicker">Held &amp; review plans</p>
              <h2>Plans awaiting an admin decision</h2>
            </div>
            <span className="badge">{isJobsLoading ? "Checking" : `${reviewPlans.length} held`}</span>
          </div>
        )}>

          {isJobsLoading ? (
            <div className="support-panel">
              <p className="muted">Loading held and review plans...</p>
            </div>
          ) : reviewPlansDisplayWarning ? (
            <div className="support-panel">
              <p className="error-text">{reviewPlansDisplayWarning}</p>
              <p className="muted">Live jobs, triage, and athlete records can still be reviewed while this queue retries.</p>
            </div>
          ) : reviewPlansProfileError && reviewPlans.length === 0 ? (
            <div className="support-panel">
              <p className="muted">Held plan details are limited while the profile service recovers. See the notice above.</p>
            </div>
          ) : reviewPlans.length === 0 ? (
            <div className="support-panel support-panel-success">
              <p className="kicker">Clear</p>
              <h3 className="form-section-title">No plans are held for review.</h3>
              <p className="muted">Held, blocked, and review-required plans appear here so they stay visible even when athlete details are unavailable.</p>
            </div>
          ) : (
            <AdminQueueList className="plans-grid admin-queue-grid" label="Held plans">
              {reviewPlans.map((plan) => (
                <article key={plan.plan_id} className="plan-card admin-triage-card">
                  <div className="plan-card-header">
                    <div>
                      <Link href={`/plans/${plan.plan_id}`}>
                        <h3 className="plan-card-title">{getPlanDisplayName(plan)}</h3>
                      </Link>
                      <p className="muted">{plan.athlete_email || plan.athlete_id || "No athlete email"}</p>
                      <ProfileUnavailableNote unavailable={plan.profile_unavailable} />
                    </div>
                    <span className="badge">{plan.status}</span>
                  </div>
                  <div className="admin-job-meta">
                    <span>Created {formatDateTime(plan.created_at)}</span>
                    <span>Plan {plan.plan_id}</span>
                  </div>
                  <div className="plan-card-actions">
                    {plan.athlete_id ? (
                      <Link href={`/admin/athletes/${plan.athlete_id}`} className="ghost-button">
                        Open athlete
                      </Link>
                    ) : null}
                    <button type="button" className="ghost-button danger-button"
                      onClick={() => void handleRejectBuild(plan.plan_id, getPlanDisplayName(plan), "plan")}
                      disabled={rejectingBuildId !== null || resumingJobId !== null}>
                      {rejectingBuildId === plan.plan_id ? "Rejecting..." : "Reject build"}
                    </button>
                    <Link href={`/plans/${plan.plan_id}`} className="cta">
                      Review plan
                    </Link>
                  </div>
                </article>
              ))}
            </AdminQueueList>
          )}
        </AdminQueue>

        <AdminQueue className="admin-attention-panel" header={(
          <div className="form-section-header">
            <div>
              <p className="kicker">Athlete attention queue</p>
              <h2>Needs attention</h2>
            </div>
            <span className="badge">{isJobsLoading ? "Checking" : `${attentionReviews.length} open`}</span>
          </div>
        )}>

          {isJobsLoading ? (
            <div className="support-panel">
              <p className="muted">Loading the attention queue...</p>
            </div>
          ) : attentionDisplayWarning ? (
            <div className="support-panel">
              <p className="error-text">{attentionDisplayWarning}</p>
            </div>
          ) : attentionProfileError && attentionReviews.length === 0 ? (
            <div className="support-panel">
              <p className="muted">Attention queue details are limited while the profile service recovers. See the notice above.</p>
            </div>
          ) : attentionReviews.length === 0 ? (
            <div className="support-panel support-panel-success">
              <p className="kicker">Clear</p>
              <h3 className="form-section-title">No athletes are flagged for review.</h3>
              <p className="muted">
                Injury reports, sustained high fatigue, and repeated missed sessions land here automatically from daily check-ins and session logs.
              </p>
            </div>
          ) : (
            <AdminQueueList className="plans-grid admin-queue-grid" label="Athlete attention">
              {attentionReviews.map((review) => (
                <article key={review.id} className="plan-card admin-triage-card">
                  <div className="plan-card-header">
                    <div>
                      <h3 className="plan-card-title">{review.athlete_name || review.athlete_email || review.athlete_id}</h3>
                      <p className="muted">{review.athlete_email || review.athlete_id}</p>
                    </div>
                    <span className="badge">{review.injury_flag_id ? "Injury flag" : "Review"}</span>
                  </div>
                  <p className="muted">{review.reason}</p>
                  <div className="admin-job-meta">
                    <span>Flagged {formatDateTime(review.created_at)}</span>
                  </div>
                  <div className="plan-card-actions">
                    <Link href={`/admin/athletes/${review.athlete_id}`} className="ghost-button">
                      Open athlete
                    </Link>
                    <button
                      type="button"
                      className="cta"
                      onClick={() => void handleResolveReview(review.id)}
                      disabled={resolvingReviewId !== null}
                    >
                      {resolvingReviewId === review.id ? "Resolving..." : "Mark resolved"}
                    </button>
                  </div>
                </article>
              ))}
            </AdminQueueList>
          )}
        </AdminQueue>

        {token ? (
          <AdminQueue className="admin-feedback-disclosure" header={<h2>Feedback review</h2>}>
            <AdminFeedbackPanel token={token} reloadKey={reloadKey} />
          </AdminQueue>
        ) : null}

        <div className="admin-grid">
          <AdminQueue header={(
            <div className="form-section-header">
              <p className="kicker">Athletes</p>
              <h2>{searchNeedle ? "Matching accounts" : "Recent accounts"}</h2>
            </div>
          )}>

            {isDirectoryLoading ? (
              <div className="support-panel">
                <p className="muted">Loading athlete accounts...</p>
              </div>
            ) : athletes.length === 0 && searchNeedle ? (
              <div className="support-panel">
                <p className="muted">No athlete accounts match this search.</p>
              </div>
            ) : athletes.length === 0 && athletesOffset > 0 ? (
              <div className="support-panel">
                <p className="muted">No more athlete accounts on this page.</p>
              </div>
            ) : athletes.length === 0 ? (
              <EmptyState
                eyebrow="Athlete accounts"
                title="No athletes yet."
                description="Athlete accounts appear here once someone signs up to the beta."
                example="Each row will show the athlete's name, email, saved plan count, and a link into their profile for support."
                primaryAction={{ label: "Open signup page", href: "/signup" }}
              />
            ) : (
              <>
                <div className="plans-grid">
                  {athletes.map((athlete) => (
                    <article key={athlete.athlete_id} className="plan-card">
                      <div className="plan-card-header">
                        <div>
                          <Link href={`/admin/athletes/${athlete.athlete_id}`}>
                            <h3 className="plan-card-title">{athlete.full_name || athlete.email}</h3>
                          </Link>
                          <p className="muted">{athlete.email}</p>
                        </div>
                        <span className="badge">
                          {athlete.access_status === "pending"
                            ? "Approval needed"
                            : `${athlete.plan_count} plan${athlete.plan_count === 1 ? "" : "s"}`}
                        </span>
                      </div>
                      <p className="muted">Created {formatDateTime(athlete.created_at)}</p>
                      <div className="plan-card-actions">
                        {athlete.access_status === "pending" ? (
                          <button
                            type="button"
                            className="cta"
                            onClick={() => void handleApproveAthlete(athlete.athlete_id)}
                            disabled={approvingAthleteId !== null}
                          >
                            {approvingAthleteId === athlete.athlete_id ? "Approving…" : "Approve access"}
                          </button>
                        ) : null}
                        <Link href={`/admin/athletes/${athlete.athlete_id}`} className="ghost-button">
                          View profile
                        </Link>
                      </div>
                    </article>
                  ))}
                </div>
                <div className="admin-pager" aria-label="Athlete pagination">
                  <button
                    type="button"
                    className="ghost-button"
                    onClick={() => goToAthletesPage(-1)}
                    disabled={isDirectoryLoading || athletesOffset === 0}
                  >
                    Previous
                  </button>
                  <span className="muted">Page {athletesPage}</span>
                  <button
                    type="button"
                    className="ghost-button"
                    onClick={() => goToAthletesPage(1)}
                    disabled={isDirectoryLoading || !athletesHasMore}
                  >
                    Next
                  </button>
                </div>
              </>
            )}
          </AdminQueue>

          <AdminQueue header={(
            <div className="form-section-header">
              <div>
                <p className="kicker">Plans</p>
                <h2>{searchNeedle ? "Matching generations" : "Latest generations"}</h2>
              </div>
              {archivedPlanIds.length ? (
                <span className="badge">{archivedPlanIds.length} archived</span>
              ) : null}
            </div>
          )}>

            {isDirectoryLoading ? (
              <div className="support-panel">
                <p className="muted">Loading plan history...</p>
              </div>
            ) : plans.length === 0 && searchNeedle ? (
              <div className="support-panel">
                <p className="muted">No plan history matches this search.</p>
              </div>
            ) : plans.length === 0 && plansOffset > 0 ? (
              <div className="support-panel">
                <p className="muted">No more plans on this page.</p>
              </div>
            ) : plans.length === 0 ? (
              <EmptyState
                eyebrow="Plan history"
                title="No plans generated yet."
                description="Generated fight camps appear here once athletes start creating them."
                example="Each row will show plan name, athlete email, status, creation time, and a quick open link."
                primaryAction={{ label: "Open Demo Plan", href: "/demo-plan" }}
              />
            ) : (
              <>
                {archivedPlanIds.length ? (
                  <div className="admin-athlete-plan-bulkbar admin-plan-cleanup-bar">
                    <label className="admin-athlete-plan-select">
                      <input
                        type="checkbox"
                        checked={allArchivedPlansSelected}
                        onChange={toggleAllArchivedPlans}
                        disabled={bulkDeletingPlans}
                        aria-label="Select archived plans on this page"
                      />
                      <span className="muted">
                        {selectedArchivedCount > 0
                          ? `${selectedArchivedCount} archived selected`
                          : `Select archived (${archivedPlanIds.length})`}
                      </span>
                    </label>
                    <button
                      type="button"
                      className="ghost-button danger-button"
                      onClick={() => void handleBulkDeleteArchivedPlans()}
                      disabled={selectedArchivedCount === 0 || bulkDeletingPlans}
                    >
                      {bulkDeletingPlans
                        ? "Deleting..."
                        : `Delete archived${selectedArchivedCount ? ` (${selectedArchivedCount})` : ""}`}
                    </button>
                  </div>
                ) : null}
                <div className="plans-grid">
                  {plans.map((plan) => (
                    <article key={plan.plan_id} className="plan-card">
                      <div className="plan-card-header">
                        <div className="admin-plan-title-row">
                          {isArchivedPlan(plan) ? (
                            <label className="admin-athlete-plan-select" aria-label={`Select ${getPlanDisplayName(plan)}`}>
                              <input
                                type="checkbox"
                                checked={selectedArchivedIds.includes(plan.plan_id)}
                                onChange={() => toggleArchivedPlan(plan.plan_id)}
                                disabled={bulkDeletingPlans}
                              />
                            </label>
                          ) : null}
                          <div>
                            <Link href={`/plans/${plan.plan_id}`}>
                              <h3 className="plan-card-title">{getPlanDisplayName(plan)}</h3>
                            </Link>
                            <p className="muted">{plan.athlete_email}</p>
                          </div>
                        </div>
                        <span className="badge">{plan.status}</span>
                      </div>
                      <p className="muted">Created {formatDateTime(plan.created_at)}</p>
                      <div className="plan-card-actions">
                        <Link href={`/plans/${plan.plan_id}`} className="ghost-button">
                          Open plan
                        </Link>
                      </div>
                    </article>
                  ))}
                </div>
                <div className="admin-pager" aria-label="Plan pagination">
                  <button
                    type="button"
                    className="ghost-button"
                    onClick={() => goToPlansPage(-1)}
                    disabled={isDirectoryLoading || plansOffset === 0}
                  >
                    Previous
                  </button>
                  <span className="muted">Page {plansPage}</span>
                  <button
                    type="button"
                    className="ghost-button"
                    onClick={() => goToPlansPage(1)}
                    disabled={isDirectoryLoading || !plansHasMore}
                  >
                    Next
                  </button>
                </div>
              </>
            )}
          </AdminQueue>
        </div>
      </section>
    </RequireAuth>
  );
}

web/app/page.tsx:
"use client";

import Link from "next/link";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useTranslations } from "next-intl";
import { type ReactNode, useCallback, useEffect, useRef, useState } from "react";

import { useAppSession } from "@/components/auth-provider";
import { EmptyState } from "@/components/empty-state";
import { FightCountdown, FightCountdownSkeleton } from "@/components/fight-countdown";
import { InstallUnlxck } from "@/components/install-unlxck";
import { PlansFeaturedSkeleton, Skeleton } from "@/components/skeleton";
import { XpProgressCard, XpProgressCardSkeleton } from "@/components/xp-progress-card";
import { getPlan, getToday } from "@/lib/api";
import { getFightCountdown } from "@/lib/fight-countdown";
import {
  getOptionLabel,
  PROFESSIONAL_STATUS_OPTIONS,
  STANCE_OPTIONS,
  TACTICAL_STYLE_OPTIONS,
  TECHNICAL_STYLE_OPTIONS,
} from "@/lib/intake-options";
import { humanizeIfRawEnum } from "@/lib/plan-labels";
import { formatPlanFightDate, formatPlanTimestamp, getPlanDisplayName, isOpenOngoingPlan } from "@/lib/plan-format";
import {
  getCampDayLabel,
  getOverviewCommandEyebrow,
  getOverviewPrimaryAction,
  getRiskTimeframeLabel,
  getTierMeta,
  resolveTodayDecision,
} from "@/lib/today";
import type { PlanSummary, StructuredPlan, TodayActivePlan, TodayCommandView } from "@/lib/types";

function formatPlanCount(value: number): string {
  return `${value} saved plan${value === 1 ? "" : "s"}`;
}

function OverviewDetailList({
  items,
}: {
  items: Array<{
    label: string;
    value: string;
    highlight?: boolean;
    badgeText?: string;
    helperText?: string;
    progressValue?: number;
  }>;
}) {
  return (
    <div className="review-detail-list overview-detail-list">
      {items.map((item) => (
        <div
          key={`${item.label}-${item.value}`}
          className={item.highlight ? "review-detail-row overview-detail-row-highlight" : "review-detail-row"}
        >
          <div className={item.highlight ? "overview-detail-heading overview-detail-heading-highlight" : "overview-detail-heading"}>
            <p className="review-detail-label">{item.label}</p>
            {item.badgeText ? <span className="overview-inline-badge">{item.badgeText}</span> : null}
          </div>
          <p className={item.highlight ? "review-detail-value overview-detail-value-strong" : "review-detail-value"}>{item.value}</p>
          {typeof item.progressValue === "number" ? (
            <div className="overview-progress-track" role="presentation" aria-hidden="true">
              <span
                className="overview-progress-fill"
                style={{ width: `${Math.max(0, Math.min(100, item.progressValue))}%` }}
              />
            </div>
          ) : null}
          {item.helperText ? <p className="overview-progress-helper">{item.helperText}</p> : null}
        </div>
      ))}
    </div>
  );
}

function OverviewDetailGrid({
  items,
}: {
  items: Array<{
    label: string;
    value: string;
    highlight?: boolean;
    badgeText?: string;
    helperText?: string;
    progressValue?: number;
  }>;
}) {
  const midpoint = Math.ceil(items.length / 2);
  const columns = [items.slice(0, midpoint), items.slice(midpoint)].filter((column) => column.length);

  return (
    <div className="overview-detail-grid">
      {columns.map((column, index) => (
        <div key={`column-${index + 1}`} className="overview-detail-column">
          <OverviewDetailList items={column} />
        </div>
      ))}
    </div>
  );
}

function OverviewDisclosure({
  title,
  summary,
  badge,
  children,
}: {
  title: string;
  summary: string;
  badge?: string;
  children: ReactNode;
}) {
  return (
    <details className="overview-disclosure">
      <summary className="overview-disclosure-summary">
        <div className="overview-disclosure-copy">
          <p className="kicker">{title}</p>
          <p className="overview-disclosure-title">{summary}</p>
        </div>
        <div className="overview-disclosure-meta">
          {badge ? <span className="overview-inline-badge">{badge}</span> : null}
          <span className="overview-disclosure-chevron" aria-hidden="true" />
        </div>
      </summary>
      <div className="overview-disclosure-body">{children}</div>
    </details>
  );
}

function WorkspaceOverviewSkeleton() {
  return (
    <>
      <section
        className="hero-panel overview-command-shell overview-command-primary athlete-motion-slot athlete-motion-header"
        aria-busy="true"
      >
        <div className="overview-primary-grid">
          <div className="status-card overview-command-card overview-decision-lead">
            <Skeleton variant="text" width={110} height={12} />
            <Skeleton variant="text" width="70%" height={40} />
            <Skeleton variant="text" width="88%" height={16} />
            <Skeleton variant="text" width="76%" height={16} />
            <div className="plan-summary-actions overview-primary-actions">
              <Skeleton variant="block" width={168} height={44} />
              <Skeleton variant="block" width={140} height={44} />
            </div>
          </div>
          <div className="overview-primary-session">
            <XpProgressCardSkeleton />
          </div>
        </div>
      </section>
      <section className="panel overview-secondary athlete-motion-slot athlete-motion-status" aria-busy="true">
        <div className="overview-operational-strip" aria-label="Workspace status loading">
          {[0, 1, 2, 3].map((index) => (
            <div key={index} className="overview-operational-item">
              <Skeleton variant="text" width={72} height={10} />
              <Skeleton variant="text" width={120} height={16} />
            </div>
          ))}
        </div>
        <PlansFeaturedSkeleton />
      </section>
    </>
  );
}

function enrichConfirmedActivePlan(
  commandPlan: TodayActivePlan | null | undefined,
  latestPlan: PlanSummary | null | undefined,
): TodayActivePlan {
  if (!commandPlan?.id) {
    return commandPlan ?? {};
  }

  const canUseLatestPlanFields = latestPlan?.plan_id === commandPlan.id;
  if (!canUseLatestPlanFields) {
    return commandPlan;
  }

  return {
    ...commandPlan,
    name: commandPlan.name || getPlanDisplayName(latestPlan),
    status: commandPlan.status || latestPlan.status,
    fight_date: commandPlan.fight_date || latestPlan.fight_date,
  };
}

/**
 * Condensed Overview risk index. Today owns the full explanation and action;
 * this card names only the two highest-priority signals and routes overflow to
 * that actionable surface.
 */
function OverviewRiskWatch({ risks = [] }: { risks?: TodayCommandView["risk_watch"] }) {
  if (!risks.length) {
    return (
      <article className="status-card overview-command-card overview-risk-card">
        <p className="status-label">Risk watch</p>
        <p className="muted">No active warnings.</p>
      </article>
    );
  }

  const safeRisks = risks ?? [];
  const visible = safeRisks.slice(0, 2);
  const overflow = safeRisks.length - visible.length;

  return (
    <article className="status-card overview-command-card overview-risk-card">
      <p className="status-label">Risk watch</p>
      <div className="overview-risk-list">
        {visible.map((risk, index) => {
          const timeframe = getRiskTimeframeLabel(risk.timeframe);
          const riskLabel = humanizeIfRawEnum(risk.label) || risk.label;
          return (
            <div key={`${risk.category}-${risk.label}-${index}`} className="overview-risk-row" data-tone={risk.tone}>
              <span className="overview-risk-row-label">{timeframe || riskLabel}</span>
              {timeframe ? <span className="overview-risk-row-text">{riskLabel}</span> : null}
            </div>
          );
        })}
      </div>
      {overflow > 0 ? (
        <Link href="/today" className="overview-risk-more">
          Review {overflow} more on Today
        </Link>
      ) : null}
    </article>
  );
}

export default function HomePage() {
  const publicT = useTranslations("PublicHome");
  const landingOutcomePoints = [1, 2, 3].map((index) => ({
    label: publicT(`outcome${index}Label`),
    value: publicT(`outcome${index}Value`),
  }));
  const landingWorkspaceRows = [
    { step: "01", label: publicT("intake"), status: publicT("row1Status"), title: publicT("intake"), body: publicT("row1Body") },
    { step: "02", label: publicT("row2Label"), status: publicT("row2Status"), title: publicT("row2Label"), body: publicT("row2Body") },
    { step: "03", label: publicT("row3Label"), status: publicT("row3Status"), title: publicT("row3Label"), body: publicT("row3Body") },
    { step: "04", label: publicT("today"), status: publicT("row4Status"), title: publicT("today"), body: publicT("row4Body") },
  ];
  const landingProductProofPoints = [
    { label: publicT("today"), title: publicT("proof1Title"), body: publicT("proof1Body") },
    { label: publicT("row2Label"), title: publicT("proof2Title"), body: publicT("proof2Body") },
    { label: publicT("proof3Label"), title: publicT("proof3Title"), body: publicT("proof3Body") },
  ];
  const landingWorkflowSteps = [1, 2, 3, 4].map((index) => ({
    label: publicT(`step${index}Label`),
    title: publicT(`step${index}Title`),
    body: publicT(`step${index}Body`),
  }));
  const { isReady, isMeHydrated, hasTransientMeError, session, me, signOut, refreshMe } = useAppSession();
  const router = useRouter();
  const [commandState, setCommandState] = useState<TodayCommandView | null>(null);
  const [commandError, setCommandError] = useState<string | null>(null);
  const [structuredPlan, setStructuredPlan] = useState<StructuredPlan | null>(null);
  // Which active plan's structured_plan request has finished (loaded or
  // failed). The fight countdown waits for it so it appears once, already
  // animating, instead of showing today's count and then replaying.
  const [planSettledFor, setPlanSettledFor] = useState<string | null>(null);

  useEffect(() => {
    if (isReady && session && isMeHydrated && !me) {
      router.replace("/login");
    }
  }, [isReady, isMeHydrated, me, router, session]);

  const [isReloadingCommand, setIsReloadingCommand] = useState(false);
  const latestTokenRef = useRef(session?.access_token);

  useEffect(() => {
    latestTokenRef.current = session?.access_token;
  }, [session?.access_token]);

  const loadCommandState = useCallback(async () => {
    const token = session?.access_token;
    if (!token) {
      setCommandState(null);
      return;
    }
    setIsReloadingCommand(true);
    setCommandError(null);
    try {
      const state = await getToday(token);
      // Ignore results from a request the current session has moved past.
      if (latestTokenRef.current !== token) {
        return;
      }
      setCommandState(state);
      setCommandError(null);
    } catch {
      if (latestTokenRef.current !== token) {
        return;
      }
      setCommandError("We couldn't load your camp status. Please try again.");
    } finally {
      if (latestTokenRef.current === token) {
        setIsReloadingCommand(false);
      }
    }
  }, [session?.access_token]);

  useEffect(() => {
    let active = true;
    if (!session?.access_token) {
      setCommandState(null);
      return () => {
        active = false;
      };
    }
    void getToday(session.access_token)
      .then((state) => {
        if (!active) return;
        setCommandState(state);
        setCommandError(null);
      })
      .catch(() => {
        if (!active) return;
        setCommandError("We couldn't load your camp status. Please try again.");
      });
    return () => {
      active = false;
    };
  }, [session?.access_token]);

  // Best-effort structured plan for the fight countdown's calendar. Read-only:
  // if it fails, the countdown shows without its bar (the rest of the command
  // view is unaffected). Mirrors how Today loads the same data.
  const activePlanId = commandState?.active_plan?.id;
  useEffect(() => {
    const token = session?.access_token;
    if (!token || !activePlanId) {
      setStructuredPlan(null);
      return;
    }
    let cancelled = false;
    getPlan(token, activePlanId)
      .then((detail) => {
        if (!cancelled) {
          setStructuredPlan(detail.outputs?.structured_plan ?? null);
          setPlanSettledFor(activePlanId);
        }
      })
      .catch(() => {
        if (!cancelled) {
          setStructuredPlan(null);
          setPlanSettledFor(activePlanId);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [session?.access_token, activePlanId]);

  if (session && hasTransientMeError) {
    return (
      <section className="panel loading-card">
        <p className="kicker">Overview</p>
        <h1>Workspace temporarily unavailable</h1>
        <p className="muted">We couldn&apos;t load your athlete profile. Please try again.</p>
        <div className="hero-actions">
          <button type="button" className="cta" onClick={() => void refreshMe()}>
            Retry
          </button>
          <button type="button" className="secondary-button" onClick={() => void signOut()}>
            Sign out
          </button>
        </div>
      </section>
    );
  }

  if (!isReady) {
    return (
      <section className="panel loading-card">
        <p className="kicker">Overview</p>
        <h1>Loading your athlete workspace</h1>
        <p className="muted">Checking saved intake and plan history.</p>
      </section>
    );
  }

  if (session && !isMeHydrated) {
    return <WorkspaceOverviewSkeleton />;
  }

  if (session && isMeHydrated && !me) {
    return (
      <section className="panel loading-card">
        <p className="kicker">Overview</p>
        <h1>Redirecting to login</h1>
        <p className="muted">Session expired. Sign in again.</p>
      </section>
    );
  }

  if (session && me) {
    const latestPlan = me.latest_plan ?? null;
    const draft = (me.profile.onboarding_draft as { current_step?: number } | null) ?? null;
    const latestIntake = me.latest_intake;
    const hasMeaningfulDraft = Boolean(
      draft && typeof draft === "object" && Object.keys(draft as Record<string, unknown>).length > 0,
    );
    const isFirstTimeUser =
      me.plan_count === 0 && !latestPlan && !latestIntake && !hasMeaningfulDraft;

    if (isFirstTimeUser) {
      return (
        <section className="hero-panel welcome-panel athlete-motion-slot athlete-motion-header">
          <div className="hero-panel-copy welcome-copy">
            <p className="eyebrow">Welcome to UNLXCK</p>
            <h1 className="hero-title">Build your fight camp in minutes.</h1>
            <p className="overview-command-summary">
              Create your athlete profile, generate a structured camp plan, and manage your setup from one dashboard.
            </p>
            <p className="muted welcome-context">
              Designed for fighters and combat athletes. Quick Build takes about 2 minutes. Advanced Intake gives more control.
            </p>
            <div className="hero-actions welcome-actions">
              <Link href="/onboarding" className="cta">
                Start Advanced Intake
              </Link>
              <Link href="/quick-build" className="secondary-button">
                Use Quick Build
              </Link>
              <Link href="/demo-plan" className="ghost-button">
                View Demo Plan
              </Link>
            </div>
            <InstallUnlxck variant="inline" />
          </div>
        </section>
      );
    }

    if (!commandState && !commandError) {
      return <WorkspaceOverviewSkeleton />;
    }

    if (!commandState && commandError) {
      return (
        <section className="panel loading-card">
          <p className="kicker">Overview</p>
          <h1>Camp command view unavailable</h1>
          <p className="muted">{commandError}</p>
          <div className="hero-actions">
            <button type="button" className="cta" onClick={() => window.location.reload()}>
              Retry
            </button>
            <Link href="/plans" className="secondary-button">
              View plans
            </Link>
          </div>
        </section>
      );
    }

    const activePlan = enrichConfirmedActivePlan(commandState?.active_plan, latestPlan);
    const hasActivePlan = Boolean(activePlan.id);
    // "No active plan" splits into two states the whole primary area must agree
    // on: saved plans exist (pick one) vs no plans at all (build the first).
    const hasSavedPlans = (me.plan_count ?? 0) > 0;
    const resolvedDecision = commandState ? resolveTodayDecision(commandState) : null;
    const risks = commandState?.risk_watch ?? [];
    const recommendation = commandState?.today?.recommendation_state ?? "not_checked_in";
    // Overview consumes the same authoritative resolver as Today. The backend
    // tier controls safety; structured severe-injury data only supplies truthful
    // STOP presentation and the injury check-in action.
    const decisionBanner = resolvedDecision?.banner ?? null;
    const decisionTier = resolvedDecision?.displayTier ?? "not_checked_in";
    const tierMeta = getTierMeta(decisionTier);
    const safetyNoticeLeads = resolvedDecision?.primaryMessageKind === "safety_notice";
    const decisionTitle = safetyNoticeLeads
      ? decisionBanner?.title ?? "Current safety"
      : tierMeta.label;
    const overviewEyebrow = safetyNoticeLeads
      ? "Current safety"
      : getOverviewCommandEyebrow(decisionTier);
    const decisionLines = decisionBanner
      ? (safetyNoticeLeads
          ? [decisionBanner.action, decisionBanner.detail]
          : [decisionBanner.detail, decisionBanner.action]
        ).filter((line): line is string => Boolean(line))
      : ["Submit today's fast check-in to unlock your training decision."];
    const decisionSafety = decisionBanner?.safety;
    // With no active plan there is no training decision to render, so the whole
    // primary area (headline + body) is overridden to match the CTA instead of
    // showing a stale "CHECK IN REQUIRED" that the athlete cannot act on.
    const overviewTitle = !hasActivePlan
      ? hasSavedPlans
        ? "Select active plan"
        : "Build your plan"
      : decisionTitle;
    const overviewLines = !hasActivePlan
      ? [
          hasSavedPlans
            ? "Choose which saved plan should control Today, check-ins and session tracking."
            : "Create your first plan to unlock Today and session tracking.",
        ]
      : decisionLines;
    // Safety copy only belongs to a real decision — never on the no-plan states.
    const overviewSafety = hasActivePlan ? decisionSafety : undefined;
    // Today's countdown to the fight, and whether the scheduled session is today
    // (vs a future planned day that must read as pending, not cleared).
    const campDay = getCampDayLabel(commandState?.today?.training_day, String(activePlan.fight_date || ""));
    const openOngoing = hasActivePlan && isOpenOngoingPlan(activePlan.fight_date);
    const sessionIsToday = resolvedDecision?.sessionIsToday ?? false;
    // Decision tone drives the colour accents on the decision card (matches
    // Today). Neutral/preview carries no accent — the next-session preview stays
    // grey and is never tinted red just because today is a pull-back. The
    // exception is a severe injury: it blocks the scheduled session, so its card
    // IS the blocked one and correctly reads red.
    const decisionTone =
      decisionBanner && decisionBanner.tone !== "neutral" ? decisionBanner.tone : undefined;
    // One dominant next action, resolved from the whole state by a pure helper so
    // the button can never contradict the headline/body (and is unit-tested per
    // state). STOP never falls through to a "train" label — see
    // getOverviewPrimaryAction.
    const primaryAction = getOverviewPrimaryAction({
      hasActivePlan,
      planCount: me.plan_count ?? 0,
      hasInjuryOverride: Boolean(resolvedDecision?.severeInjuryBlocksCurrentSession),
      recommendation,
      decisionTier,
      hasSafeSession: Boolean(resolvedDecision?.useSafeReplacement),
      sessionIsToday,
    });
    const primaryHref = primaryAction.href;
    const primaryLabel = primaryAction.label;

    return (
      <>
        {/* Primary command area — today's decision, the session it affects, and
            one dominant action lead the first viewport. */}
        <section className="hero-panel overview-command-shell overview-command-primary athlete-motion-slot athlete-motion-header">
          <div className="overview-primary-grid">
            <div className="status-card overview-command-card overview-decision-lead" data-tone={decisionTone}>
              <p className="eyebrow">{overviewEyebrow}</p>
              <h1 className="hero-title overview-decision-headline">{overviewTitle}</h1>
              <div className="overview-decision-copy">
                {overviewLines.map((line, index) => (
                  <p key={index} className="muted">{line}</p>
                ))}
                {overviewSafety ? <p className="muted overview-decision-safety">{overviewSafety}</p> : null}
              </div>
              <div className="plan-summary-actions overview-primary-actions">
                <Link href={primaryHref} className="cta overview-primary-action">{primaryLabel}</Link>
                {hasActivePlan ? (
                  <Link href={`/plans/${activePlan.id}`} className="secondary-button">Camp plan</Link>
                ) : (
                  <Link href="/quick-build" className="secondary-button">Quick Build</Link>
                )}
              </div>
            </div>
            <div className="overview-primary-session">
              <XpProgressCard />
            </div>
          </div>
          {commandError ? (
            <div className="error-banner" role="alert">
              <span>{commandError}</span>
              <button
                type="button"
                className="error-banner-retry"
                onClick={() => void loadCommandState()}
                disabled={isReloadingCommand}
              >
                {isReloadingCommand ? "Retrying..." : "Retry"}
              </button>
            </div>
          ) : null}
        </section>

        {/* Secondary — camp context, progress, full risk watch, disclaimer.
            Available but visually reduced so it never competes with the command. */}
        <section className="panel overview-secondary athlete-motion-slot athlete-motion-status">
          <p className="kicker overview-secondary-eyebrow">{openOngoing ? "Training context" : "Camp context"}</p>
          <div className="overview-operational-strip" aria-label={openOngoing ? "Training status" : "Camp status"}>
            <div className="overview-operational-item"><span className="overview-operational-label">Plan</span><span className="overview-operational-value">{String(activePlan.name || "No active plan")}</span></div>
            <div className="overview-operational-item"><span className="overview-operational-label">{openOngoing ? "Cycle" : "Camp day"}</span><span className="overview-operational-value">{openOngoing ? "Renewable 4-week block" : campDay || "Not set"}</span></div>
            <div className="overview-operational-item"><span className="overview-operational-label">{openOngoing ? "Mode" : "Phase"}</span><span className="overview-operational-value">{openOngoing ? "Ongoing" : humanizeIfRawEnum(activePlan.phase) || "Not set"}</span></div>
            <div className="overview-operational-item"><span className="overview-operational-label">Fight date</span><span className="overview-operational-value">{openOngoing ? "Not scheduled" : formatPlanFightDate(String(activePlan.fight_date || ""))}</span></div>
          </div>
          {planSettledFor === activePlanId ? (
            <FightCountdown
              fightDate={activePlan.fight_date ? String(activePlan.fight_date) : null}
              trainingDay={commandState?.today?.training_day}
              phase={activePlan.phase ? String(activePlan.phase) : null}
              plan={structuredPlan}
            />
          ) : getFightCountdown({ fightDate: activePlan.fight_date, trainingDay: commandState?.today?.training_day }) ? (
            <FightCountdownSkeleton />
          ) : null}
          <OverviewRiskWatch risks={risks} />
        </section>
      </>
    );
  }

  return (
    <>
      <section className="hero-panel public-hero-panel">
        <div className="public-hero-grid">
          <div className="hero-panel-copy public-hero-copy">
            <p className="public-hero-motto" aria-label={publicT("motto")}>
              <span>UNLXCK</span>
              <span>{publicT("motto").replace(/^UNLXCK\s+/i, "")}</span>
            </p>
            <h1 className="hero-title public-hero-title" aria-label={publicT("heroTitle")}>
              <span>{publicT("heroLine1")}</span>
              <span>{publicT("heroLine2")}</span>
            </h1>
            <p className="public-hero-lead">{publicT("lead")}</p>
