  limit = 60,
): Promise<TodaySessionCompletionRecord[]> {
  return withTransientRetries(() =>
    readJson<TodaySessionCompletionRecord[]>(`/api/today/session-completions?limit=${limit}`, {
      token,
    }),
  );
}

