): Promise<SparringLogHistoryResponse> {
  return withTransientRetries(() =>
    readJson<SparringLogHistoryResponse>(`/api/today/sparring-logs?limit=${limit}`, { token }),
  );
}

export function listTodayCheckinHistory(
  token: string,
